/* 平成21年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h21.committeeSessions.push(...[{"id":"h21-20090414-7","meetingId":"h21-cm04","date":"2009年4月14日","dateIso":"2009-04-14","committee":"厚生委員会","time":"午後１時０３分～午後３時１２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"東部療育センターに何床ぐらいあって、どのぐらい利用されているのか。それからもう１点、前回も、１泊２日の受入れというところで、昼間だけの受入れ体制も欲しいという願いには、なかなかこたえられにくいようだったんですけれども、その辺で、医療的なものも含めて、入所施設ではなくて、日中の通所のところで、受け入れてくださるところがあるのかどうか、ちょっとその辺も含めて教えてください。","respondent":"高橋障害者福祉課長","answer":"１泊２日の問題ですが、１泊２日がショートステイの基本的な考え方で、今後、昼間の場合でも可能になるということで検討を進められているということは聞いております。","voiceIndex":38,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"デイサービスが、預かることが可能な方は、通所で通う。それは通所で通う人の場合ですよね。だから、緊急的に何かあったときに通えるといった意味のデイサービス的なところが、入所施設ではなくて、ほかにそういうのが可能な施設というか、場所があるのかどうか、教えてください。","respondent":"高橋障害者福祉課長","answer":"緊急に通えるというと、その日だけということになると、やはりショートステイの中で、その日に朝早く行って、必要がなければ、夕方、午後に帰っていただくという形が一番適切かなと、今の段階では、そういうふうに考えております。","voiceIndex":40,"id":"exchange-002"},{"speaker":"阿部委員","kind":"確認","question":"前回のときに、ヘルパーの派遣で足りるというようなご答弁が中にあったかと思うんです。これは確認なんですけれども、緊急時だけではなくて、例えば、介護に当たられているご家族のレスパイトなど、広い理由で使えるということだったか、どうか、確認させてください。","respondent":"高橋障害者福祉課長","answer":"この場合については、１日８時間、ものによっては１２時間まで可能ということで、その辺については、入浴、排泄とか、食事の介護、それから外出時に移動の介護ということで、例えば、通院に必要な場合については、その方がついて行くという場合もありますので、その辺については。","voiceIndex":42,"id":"exchange-003"},{"speaker":"阿部委員","kind":"質問","question":"要は時間の中身の話ではなくて、ご家族のレスパイトとして使えるかということと、それが利用制限等があるのか。あるとすると、どのぐらいまで使えているのかということを教えてください。時間的な利用制限ということです。","respondent":"高橋障害者福祉課長","answer":"ですから、３６５日の時間数を受給者証として発行しますので、利用する方については、その時間利用ができると考えております。","voiceIndex":45,"id":"exchange-004"},{"speaker":"阿部委員","kind":"質問","question":"とすると、この請願にあるような重い障害の子どもを抱えて、例えばお母さんが日常的にケアをしている場合でも、もちろん障害の重さが合っていればですけれども、しんどいなと思うときには、この制度を自由に使ってちょっと休むというようなことが、現実的に可能な運用であるということでよろしいのでしょうか。","respondent":"高橋障害者福祉課長","answer":"重度訪問介護というのは、安定している方で、この請願にあります医療依存度の高いということで、痰吸引とか、そういう方については、今の段階ではヘルパーがやることはできませんので、このヘルパー派遣で痰吸引も人工呼吸器の重度の方についても。","voiceIndex":47,"id":"exchange-005"},{"speaker":"阿部委員","kind":"質問","question":"ちょっと蒸し返しになってはいけないんですけれども、一番しんどい家庭のところに手が届いていないというのが今の制度であって、そこに対して、何らかの方策が必要であろうと、それは区とか、都とか、国とか、いろいろあると思うんですけれども、どうお考えなんでしょうか。","respondent":"高橋障害者福祉課長","answer":"私どもが行っているのは福祉的サービスで、そのほかの身体的な介助とかの部分については、私どもでやるということになりますので、両方の連携の中で、実際上、在宅生活を続けていっていただいているというのが現状です。","voiceIndex":49,"id":"exchange-006"},{"speaker":"阿部委員","kind":"質問","question":"今日の議題は、あくまでも医療依存度の高いケースですので、ヘルパー派遣の話は、今回はむしろ関係ないと言ってもいいかもしれないです。むしろ、今おっしゃった訪問看護のほうだと思うんですけれども、これは、区内で十分に使える状況になっているのでしょうか。","respondent":"高橋障害者福祉課長","answer":"私のほうでは、現在、その状況が満ぱいなのか、不足しているのかということについては、ちょっとつかんでおりません。","voiceIndex":51,"id":"exchange-007"},{"speaker":"阿部委員","kind":"質問・要望","question":"これで最後にしたいと思いますが、医師が判断する、これは都度判断であるのか、包括的判断というのがあり得るのかというのを、ちょっと教えていただきたいのと、この状況をどういうふうに運用されていて、それが、ニーズの実態に合っているかというところまでは、ぜひ区でも把握をしていただきたいと思います。ぜひ、把握をお願いいたします。","respondent":"高橋障害者福祉課長","answer":"人工呼吸器装着の障害者については、前回もお話ししたとおり、私どもで実際上、福祉サービスを利用するそういう状況の方については把握しておりますので、プラスアルファの部分については、状況の把握はちょっと難しいかと思います。","voiceIndex":53,"id":"exchange-008"},{"speaker":"阿部委員","kind":"質問・要望","question":"把握を、というのは、要は、訪問看護師が必要に応じて派遣してもらえるような状況になっているかどうかということを把握してほしいということであって、医療が必要な障害の方がいらっしゃるかどうかというのは、前回、人数を伺っていますので、要はニーズ把握をしていただきたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうふうに、区がある一定の保証をしながら、医療依存度の高い方のベッド確保という形でのショートステイみたいなもので受け入れられるような仕組みを、区内で、あるいはほんとうに荏原病院でもすぐに近くのところで、そういうものをつくることはできないのかなと思うんですけれども、そこら辺のところも、ちょっとお聞かせいただきたいと思います。","respondent":"高橋障害者福祉課長、木下健康福祉事業部長","answer":"ということで、申しわけないんですが、医療ショートステイということでの制限のある部分については、私のほうはつかんでおりません。これは、介護保険が始まった段階で、いわゆるショートステイ制度が、老健も含めてでき上がりましたので、当該制度については廃止したという経過があるです。","voiceIndex":56,"id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ほんとうに医療依存度の高い方というのは、介護保険のショートステイではちょっと難しいということがあると思いますので、前に旧関東逓信病院と北品川病院で、医療依存度の高い方のショートステイがあったということなので、また区としても、介護ではカバーできない医療依存度の高い方のショートステイを近いところで利用できるような形で、ぜひご検討いただけないかなと思うんですけれども。","respondent":"木下健康福祉事業部長","answer":"そういう点で、こういうニーズに、現在のところでは、やはり東京都の療育センター等のショートステイ以外に対応がされる制度的なものがないというのが、現在の状況であるです。","voiceIndex":60,"id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"意見","question":"自民党としては、本日、結論を出すということでお願いいたします。ただ、今までの４回の質疑にいつも出ていますし、今、健康福祉事業部長のお答えにもありましたけれども、医療と福祉との問題というところで、最終的に法上の問題ということからすると、この趣旨に基づいて看護師の派遣ができるような福祉支援というのは、品川区としては、今の段階で受け入れることはできないと、私どもは判断しております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-012"},{"speaker":"堺委員","kind":"質問","question":"お気持ちはよく理解できます。ただ、いろいろなものはすべて法律に基づいた形で、あるいは規則に基づいた形で運営されているという中にあっては、その思いがどうしても法律の壁にぶち当たって、なかなかスムーズにいかないという場合もあるということから、今回の請願についても、健康福祉事業部長のご説明を伺うにつけ、また、前回の質疑の中でも、そういうようなことがございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"本日、結論を出すということでお願いしたいと思います。高齢者の在宅介護のところも、今、たくさん問題を抱えていますけれども、今日、意見陳述を伺っていて、特に医療依存度の高い重度障害児・者のところは、もっともっと内容を知っていきながら、援助が必要であるなと、今日、また強く感じたわけです。そういった面で、なかなかそこでは解決できない部分を、今日、感じました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-014"},{"speaker":"阿部委員","kind":"質問・要望","question":"本日、結論を出したいと思います。ただ、それを今すぐ、やれと言うわけにはいきませんので、そういったちょっと広くとらえつつも、いろいろな方法を考えていただきたい。ただ、残念ながら、この項目に書いてあるような手法での改善というのはやはり難しいということで、申しわけないんですけれども、願意に沿いがたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-015"}]},{"id":"topic-02","title":"の(2)高齢者見守りネットワーク事業","agenda":"の(2)高齢者見守りネットワーク事業","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私ども、死までいかないけれども、倒れていた方もいらっしゃるし、逆に亡くなったという話も聞いていますので、その中で、今回、町会にやっていただくということで出されていますが、町会に対しては、このペーパーが出るという判断でいいんですか。区内に２００町会ぐらいある中で、どのぐらい手が挙がってくるかわからないけれども、では、どの町会をという判断材料を、ちょっと教えていただきたいのが１点。","respondent":"冨岡高齢者福祉課長","answer":"基本的には、このパンフレットでご説明申し上げようと考えていますが、ただこれだけでは足りないですと、例えば、前年度の部分で、ある程度報告書の類をつくっておりまして、それの概要みたいなものがもしつくれれば、そういうものを一緒にして。","voiceIndex":72,"id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"区として、こういう体制に対して、町会に対するお願いをしていく協働ということの一つだと思うんですけれども、そこら辺を考えると、町会のやっていただける人数が少ない中、実際にこの見守りはやってもらいたいんですけれども、もう少し時間的に余裕を持ってほしいという感じがしたんです。そこら辺、詰めていく段階の話なのか、もう決まってしまったのか、そこら辺も説明をいただければと思います。","respondent":"冨岡高齢者福祉課長","answer":"確かに、６月３０日ではちょっと早いというお考えもあるかと思いますが、今回、取り上げさせていただいたこの期限は、今まで、少しずつでもこういう形の取り組みを始められるなり、町会の中で、ある程度構想がおありになって、出しやすい町会がおありでしたら。","voiceIndex":74,"id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"説明はわかりましたけれども、ちょっと今の説明の中で引っかかったのは、今まで取り組んでいるところが中心になっちゃうのかなと。それだったら、皆さん応募してくださいというと、何か違うのではないのかと。わかりました、結果的には、高齢者見守りのほうをうまくやっていただきたいということをお願いして、さっきの件は要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-018"},{"speaker":"阿部委員","kind":"質問","question":"何点か教えてください。締切りの考え方なんですけれども、意向調書の中で、「まだ、具体的なプランはないが区と相談して検討したい」とありますが、この相談の締切りが６月と考えてもよろしいんでしょうか。予算の話はいいですが、課題の大きさにくらべて、打ち出し方がどうも地味な感じがするんですけれども、率直にどうお考えなのか、教えてください。","respondent":"冨岡高齢者福祉課長","answer":"締切りの考え方ですけれども、意向調書のイで、「まだ具体的なプランがないが区と相談して検討したい」という部分も、当然ありますので、お気持ちといいますか、やってみようということでありましたら、出していただければ。","voiceIndex":77,"id":"exchange-019"},{"speaker":"阿部委員","kind":"質問・要望","question":"６月までには、まだ意思表明だけでいいのだということなんですけれども、そうすると、６月３０日段階で、相談して検討したいというところは５カ所でなくても構わないわけですよね。出てきたところは、すべてご相談に応じつつと。ということは、先ほどの質問にもありましたように、結果的に５件を超えることもあり得ると考えてよろしいんでしょうか。これは質問です。後半のほうは要望です。","respondent":"冨岡高齢者福祉課長","answer":"６月３０日までに、町会・自治会でおやりになりたいということでお出しいただければ、そこから話をまとめてまいりますので、結果的に、５件で打切りということではございません。とにかく、どういうご意思があるのかということでお話しして、超える場合はあると思います。","voiceIndex":79,"id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"調査検討会議の到達点というのが、この見守りが大事というところだという解釈でいいんでしょうか。その辺の、今、どのぐらい実態をとられているのかということと、今後、こういうふうにやっていきたいところの一つなんだと、今後の見通しあたりを、品川区がどうとらえているのかを、まずお聞きしたいんですが。","respondent":"冨岡高齢者福祉課長","answer":"方向性につきましては、先ほど、じっくりとと申し上げましたけれども、ある一定エリアにおきまして、緩やかなあいさつ程度のものから、日常の見守り、それから、いざというときの対応。","voiceIndex":81,"id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問","question":"はい、ありがとうございました。それから、今回の部分はあくまでもひとり暮らしの世帯というくくり方ですよね、まず第一歩が。そういう範囲ですと、特に老々介護や何かの問題点もあるので、ぜひその辺も広げて、ひとり暮らしではなくて、世帯というところにおいて考えていく必要があるのではないかと思うんですが、いかがでしょうか。","respondent":"冨岡高齢者福祉課長","answer":"例えば、町会独自の取り組みの中で広げていただくということは、私どもは、今回、ひとり暮らし等実態調査の「等」の部分も、資料としてお渡ししているわけですので、それは差し支えないと考えております。","voiceIndex":83,"id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"基本的なことを一つ教えていただきたいんですが、今回、「孤立死」という取り上げ方ですね。厚生労働省が、最近、孤立死という言葉を使って、前は孤独死という言葉が一般化されていましたよね。その辺の考え方の違いというか、どこにあるのか、基本的なところで教えていただけたらと思います。","respondent":"冨岡高齢者福祉課長","answer":"いわば社会から孤立した状態で亡くなられたということで、孤立死というふうに考えているところです。","voiceIndex":85,"id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問","question":"そういった見方、精査をして出されたのが、平成１９年度のこの１５件ということですか。さっき、すみません、きちんと聞き取れなかったんですが１０２件のうち１５件ということですが、１０２件というのはどういうことなのか、もう１回、そこのところを聞かせてください。","respondent":"冨岡高齢者福祉課長","answer":"孤立死につきましては、さまざまな機関が、例えば警察も含めて、そういうところで対応されていると思うんですが、これは、在宅介護支援センターと高齢者福祉課で把握した部分ということで、今言った状態にある死亡ケースを孤立死です。","voiceIndex":87,"id":"exchange-024"},{"speaker":"浅野委員","kind":"質問・要望","question":"品川区からそういう状況が発生しないように、ぜひとも取り組んでいただきたいと思うわけです。各委員からいろいろお話が出ておりまして、私が質問したいことはほとんど質問していただいたので、理解するところなんですが、少し気になる点があります。例えば配食サービスなんかも一つでございまして、隣の港区は、配食サービスを６回から７回にするというような新聞記事もありました。意見だけで終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-025"},{"speaker":"阿部委員","kind":"質問","question":"すみません、１点なんですけれども、ひとり暮らし高齢者というのは、別の目で見ると、災害弱者でもあるかと思います。このネットワーク事業と、例えば防災関係を組み合わせるなり、何か連携を取るようなことを考えていらっしゃるかどうか、教えてください。","respondent":"冨岡高齢者福祉課長","answer":"障害者等も含めて、災害要援護者と、今回の地域の見守りネットワークは、今後どういうふうにうまく関連し合っていくかというのは一つの課題であると受けとめておりますが、対象者がぴったり合うかどうかという部分はあるかと思いますので、その辺も含めて。","voiceIndex":90,"id":"exchange-026"},{"speaker":"阿部委員","kind":"意見","question":"さっき、浅野委員がおっしゃったような、見守ってくれなくていいという方でも、防災についてであれば、門戸を開く可能性もないわけでもないかもしれないなどと考えると、やはり何かの連携があってもいいかなと思いますので、ご検討いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":92,"id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"高齢者福祉課だけでなく、生活福祉課ですとか、庁内でほかにどういうところがあるかわからないんですけれども、警察とかも含めて、区内の孤立死がどれぐらいあるかというのは、こういう対策を取るときに、やっぱりきちんと把握する必要があるんではないかと思うんですけれども、その点を一つお聞きしたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"さらにそれをまた、どういう状況で、どういう背景でなったのかというのは、一つの研究課題としてはあるかと思いますけれども、どちらかというと、こういう孤立死の重要さを考えて、少しでも多くの地域の見守りを実際に進めてまいりたいということで、おっしゃる部分については。","voiceIndex":93,"id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"生活福祉課のほうでも把握しているということであれば、こういう対策をとる高齢者福祉課のほうとしても、それを踏まえた、全体的なとらえ方をした上での対策というところで、ご報告いただけたらありがたいと思っています。それから、一つひとつをほんとうに検討する中で、対策につながってくるのではないかなと考えていますので、そこら辺のところは、ぜひ、今後の課題ということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":95,"id":"exchange-029"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"さっきの報告で、ちょっと数字が早くて聞き取れなかったので、介護施設の１４１名の次が、どこの施設で何名だったか、もう１回教えてください。","respondent":"平澤生活福祉課長","answer":"介護施設１４１名、うち３０名が都外に入所されている方、次が、これは生活福祉関係の施設なんですが、救護施設等に３５名、うち２名が都外施設、障害者施設１０名、うち３名が都外、有料老人ホームが６名ですべて都外、最後に無届けと思われる施設が１２カ所で。","voiceIndex":101,"id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問","question":"どういう経過をたどって、このようなそれぞれの施設に入居され、どういう方が選ばれるというか、よくわからないんですが、こういう施設に入居されるのか、その辺のことをお伺いしたい。それから、「ＥＢＡＲＡ夢フェスタ２００９」なんですが、何でこれが厚生委員会なのかなと思ったら、高齢者の相談体験が入っている。これはどういう中身なのか、ひとつお伺いしたい。その辺が一つと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問","question":"無届けの施設のところなんですが、例えば入院をされて、アパートとかが見つからない緊急の場合なんかに入居されるということなんですけれども、その後、アパートをご自身が探さないとだめなんですか。品川区に住み続けたいという願いを持っていらっしゃったら、品川区内に戻ってこれるのでしょうか。ちょっとその辺を教えてください。","respondent":"平澤生活福祉課長","answer":"こちらの施設に入っていらっしゃる方が、それほどまだ長い方がいらっしゃらないということで、今後につきましては、こちらの方の自立度と申しましょうか、どの程度生活が可能なのかという状況によりまして、それぞれのケースで判断していきたいと考えております。","voiceIndex":108,"id":"exchange-032"},{"speaker":"鈴木（真）委員","kind":"質問","question":"中身はわかりました。ですから、区としては、この言葉しかないんでしょうけれども、こういう有料老人ホームというのは、例えば、月々どのぐらいの金額だとか、そこら辺の仕分けをしておかないと、何かイメージとして、生活保護を受けている方が結構高い有料老人ホームに入っていると思われてしまう危険があると思うんですけれども、ちょっとその辺、説明していただけますでしょうか。","respondent":"平澤生活福祉課長","answer":"したがいまして、東京都の特別基準、単身ですと、５万３,７００円以下となっております。各施設を見ましても、そういうことになっておりまして、安いところですと３万５,０００円とか、かなり低額なところもあります。","voiceIndex":110,"id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"質問","question":"数字的に安い金額というのはわかっていますけれども、何かそこら辺がもう少し出せるような形を考えてもらいたいなということを、マスコミの持って行き方もあるんでしょうけれども、ちょっと区として何か検討しておいてもらえないかなという気がします。何か方法がないんでしょうか。施設は、これしか書きようがないということですよね。","respondent":"平澤生活福祉課長","answer":"法律上の名称でいきますと、老人福祉法第２９条に定めるということになりますので、有料老人ホームという言い方しかないわけですけれども、委員のご提案のとおり、確かにわかりづらいといいますか、一般の区民に理解しづらいという部分があると思いますが、それにつきましては。","voiceIndex":112,"id":"exchange-034"},{"speaker":"阿部委員","kind":"確認","question":"すみません、確認させてください。それから、やっぱりさっきの、よくわからなかったんですが、要は有料老人ホームですね、これは例えば生活保護の方を主に対象とした施設なんですか、そういうものって、事実上、あるんでしょうか。あるいは、ここの６人が入っていらっしゃるのは、まさにそういうものなんでしょうか。たまたまなのか、ちょっと教えてください。","respondent":"平澤生活福祉課長","answer":"したがいまして、こういったところがあるということで、ご理解いただければと考えています。","voiceIndex":114,"id":"exchange-035"},{"speaker":"阿部委員","kind":"確認","question":"お伺いしたのは、入所されている有料老人ホームというのが、紹介の対象になっていたりするのであれば、ある程度把握されていると思うんですけれども、実態として、生活保護の方が主に利用されるような形で運営されているものなのか、どうか。ちょっとイメージとして持っていたいので、教えてください。","respondent":"平澤生活福祉課長","answer":"こちらなんですけれども、入居される場合には、必ずケースワーカーが同行いたしまして、その施設で実際にどのような処遇が行われるかということを見てまいります。","voiceIndex":116,"id":"exchange-036"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"生活保護の入居施設のことなんですけれども、介護施設に入られている方は、多くは特別養護老人ホームということで考えていいんでしょうか。特別養護老人ホームに入るとなると、大体要介護４とか５でないと、なかなか難しいと思うんですけれども、有料老人ホームとか、無届けの施設の方は、要介護度はどれぐらいまで入られているのか、教えていただきたい。","respondent":"平澤生活福祉課長","answer":"無届けの場合、この施設的な基準ができないで、というお話だったかと思うんですけれども、国のほうから、今回の火事を受けまして、有料老人ホーム、先ほどちょっとご紹介しました第２９条に当たるところなんですけれども、例えば食事の介護とか。","voiceIndex":118,"id":"exchange-037"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"あそこも食事は提供していただけるんですよね。それから、先ほどちょっとお聞きした介護度がどれぐらいの方が入られているかということも、わかったら教えていただきたいと思います。","respondent":"平澤生活福祉課長","answer":"最後に、食事の件なんですけれども、食事につきまして、先ほど、全部で１２カ所と申し上げましたが、４カ所につきましては食事の提供もしていないということで、こちらについては、果たしてこれが有料老人ホームに当たるかどうかというところも、なかなか難しいということで。","voiceIndex":120,"id":"exchange-038"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そうしますと、自立の方はいらっしゃらないということですね、結局。要介護状態の方が、かなり重度の４までの方もいらっしゃるんだなと思ったんですけれども、特別養護老人ホームまではなかなか難しいという途中の方、特別養護老人ホームにはまだ入れない要介護度の方が生活保護を受けながら入る施設というとらえ方でいいでしょうか。最後にこれだけ教えていただいて、終わります。","respondent":"平澤生活福祉課長","answer":"本来的には、生活保護を受給されている方がこういった施設等に入っていただいた場合には、三つの自立ということで、経済的な自立を目指すのか、精神的な自立を目指すのか、日常生活の自立を目指すのか、そういったようなことをきちんと考えながら。","voiceIndex":122,"id":"exchange-039"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"最後にもう一つだけ。すみません、なかなかイメージがはっきりよくわからなくて。そうしますと、この有料老人ホームの６名も、１７名も同じような施設と考えていいわけですよね。そして、このところは、多分有料老人ホームで、特定施設とかの介護保険の制度は使っていないで、生活保護費だけで大体運営をしているという施設と考えていいんでしょうか。","respondent":"平澤生活福祉課長","answer":"そういった意味で、現在、国のほうで、本来届出が必要な部分はきちんと届出をしなさいということで指導をしているです。以上、わかりにくい説明で恐縮ですが、よろしくお願いしたいと思います。","voiceIndex":124,"id":"exchange-040"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そうしますと、この介護保険というのは、有料老人ホームで特定施設をとっているというのではなくて、住居としてヘルパーにきてもらったりとか、そういう形での介護保険の制度を使っているという考え方ですか。","respondent":"平澤生活福祉課長","answer":"そうです。","voiceIndex":126,"id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3232#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":33060,"voices":129}},{"id":"h21-20090414-8","meetingId":"h21-cm04","date":"2009年4月14日","dateIso":"2009-04-14","committee":"建設委員会","time":"午後１時０２分～午後２時４３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"そういったところがどのようになっていくのか、何かお考えがあれば、少しお聞かせいただきたいと思います。","respondent":"工藤環境課長","answer":"いずれにいたしましても、環境課の清掃担当と品川区清掃事務所のリサイクル推進係が連携をとりながら、さまざまな事業についてＰＲしたり、区民からの手続きに対応したいと考えております。","voiceIndex":40,"id":"exchange-001"},{"speaker":"井上委員","kind":"質問","question":"そうすると、清掃事業に対して何か問い合わせをしたり、現場でもリサイクルの分別みたいなものはリサイクル推進係というのを置いておられるんですが、清掃一部事務組合との関係とか、そういう部分はどういうふうになっているのかというようなことは、清掃担当のほうが把握し、問い合わせにも答えていくというような関係ですか。","respondent":"工藤環境課長","answer":"そうです。現場での問い合わせは、基本的には清掃事務所で対応していただくということになります。","voiceIndex":42,"id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"次は、水とみどりの課のみどりの係と、防災まちづくり事業部のほうの公園整備係なんですけれども、ハードとソフトみたいな感じかなと思うんですけれども、公園整備というときは、ランドスケープというか、全体の計画がないと、ちぐはぐに、結果的にバリアフリーだけやりました、でも、こっちの植栽はちょっと違いましたみたいなこととか。","respondent":"藤田水とみどりの課長","answer":"ただ、今回のみどりの係の担うべき部分の中に、緑の保全、それから、緑化の推進も含めた緑の計画論的な部分については、こちらのみどりの係のほうで所管してやっていこうと考えておりますので、トータル的には都市計画部門とか。","voiceIndex":44,"id":"exchange-003"},{"speaker":"井上委員","kind":"意見","question":"品川区は結構、事業部制でいろいろ取り組むというところがあったのかと思いますので、事業部をまたがっても、きちんとした連携ができるようにということだけはしっかりとお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-004"},{"speaker":"菊地委員","kind":"質問","question":"今の井上委員の話の中で、清掃一組とのところがよくわからなかったんですけれども、従来だと、例えば、清掃一組のことで報告事項があるとすると、総務委員会で報告があったんですか。区民委員会であったんですか。清掃一組の関係で何か議会で報告しなければならないという問題が起きたときに、この建設委員会に報告をされるという意味合いだったんでしょうか、そこがちょっとよくわからない。","respondent":"久保田都市環境事業部長","answer":"そうは言っても、やはり本庁と清掃事務所は場所も離れているということで、本庁を目当てにやってくるお客様がかなりいるし、これからも継続していくだろうということが１つありましたので、ある程度、そういうところの窓口対応も含めて、残さざるを得ないだろうということで。","voiceIndex":47,"id":"exchange-005"},{"speaker":"菊地委員","kind":"質問・要望","question":"工期との関係で１点お聞きしたいのは、これを見ると、工事そのものはもう始まってからの説明会ということなんですか。その辺がよくわからないのと、それともう１つ、あの地域の町会の皆さんからいろいろな要望が出されていて、その辺はどのように酌み取られたのか、その辺を、ちょっと東京都から聞いていればお聞かせ願いたいという点。","respondent":"松代都市計画課長","answer":"目黒幹線のボックスカルバートの敷設工事を１１月までの予定で進めております。その関係で、その工事が終了した後、１１月ごろからこの今回の工事にかかると聞いてあります。その後の予定としましては、今回示しました工程のとおりです。","voiceIndex":54,"id":"exchange-006"},{"speaker":"菊地委員","kind":"質問・要望","question":"住民の皆さんの要望に対して、幾つかの改善を行うということなんですけれども、脱硝装置をつけるというのは、従来の東京都の説明を聞いていると、環境上、決して悪くなるわけではないという話をずっと、東京都の説明会なんかでもしていたように思うんですけれども、その辺、脱硝装置をつけるようになった理由というのがあれば教えていただきたいのと、区内は五反田、南品川、八潮と３カ所ありますけれども。","respondent":"松代都市計画課長","answer":"２点目の、それ以外の換気所について、脱硝装置をどうするかというのは、まだ正式には回答として受け取っておりませんが、これも同様に東京都としてはきちんと対応方、考えていくものと我々は考えています。","voiceIndex":56,"id":"exchange-007"},{"speaker":"原委員","kind":"質問","question":"私も菊地委員に続けて質問なんですけれども、私は建設委員になる前から合同連絡会のメンバーでございまして、今のご説明の中で非常にわかったんですが、昨年なんかは、下水道の前にガスがありまして、地域住民のほうから、説明がないということで、止まったという過程がありまして、今、この辺がちょっと微妙な表現になろうかと思うんですけれども、実際には東京都と会社なので、ただ、ガス、下水道。","respondent":"松代都市計画課長","answer":"これは地元に対しての説明の云々というところで、地元に対して、今回の関連事業としてのきちっとした説明が十分になされていなかったのではないかという感じはしております。しかしながら、全体工事の中で、工事のステップということを説明しています。","voiceIndex":58,"id":"exchange-008"},{"speaker":"原委員","kind":"質問","question":"ただ、その中で、もう１点だけ、先ほども菊地委員のほうから話が出たように、これは交通がかなり、要するに、ダンプです。大体のダンプの台数、もう１回、以前にもあったんですけれども、これは面積が減るものですから、掘り込みの部分が、どのぐらいのものなのかということと、それに付随して、今、品川区のほうにセンターをつくっていますよね。その辺について、東京都から品川区への説明があったかどうか。","respondent":"松代都市計画課長","answer":"そういったことから、全体の大きさが３分の２ぐらい、換気塔の大きさも４分の１ぐらいでやっているんですけれども、スリム化することによっての工事上の範囲、影響等を少なくするという対応をしてくれると聞いてあります。","voiceIndex":60,"id":"exchange-009"},{"speaker":"三上委員","kind":"質問・要望","question":"私どもにとってみると、本当に２０年以上も前からこの中央環状品川線についてはもう十分気を使っていくということを前提としてずっと発言もし、提言もしてきました。そういう準備というのは十分した上でお願いしたいと思うんですけれども、どうですか。","respondent":"松代都市計画課長","answer":"当然そういったことが説明会等で、地元で質問を含めて、出るでしょうから、その辺のところは少し前倒しして、東京都に示していただくことは改めてこちらのほうからも申し上げたいと考えています。","voiceIndex":62,"id":"exchange-010"},{"speaker":"三上委員","kind":"質問・要望","question":"ですから、下部工事だから、上部についてはその後に示しますということではなくて、もうその段階で、示せるぎりぎりのものについてはこういうところまで、今、具体的にはここまでしかできていないけれども、こういう状況ですというようなことについての、とにかく先々の説明をしてやっていくように、東京都のほうにはきちんとやりなさいということは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-011"},{"speaker":"菊地委員","kind":"質問","question":"私は、この本質的なところがよくわからないんですけれども、この中で、概要の中で、跡地を取得する主体と書かれていますよね。土地というか、地域そのものは、大田区の単位の中に入る部分なんだと思うんですけれども、この跡地を取得する主体というのは、何を意味しているものなんですか。まさか品川区があそこの土地を買うということはあまり考えられないんだけれども、どういうことなんですか。","respondent":"松代都市計画課長","answer":"そういった中で、どういったものが利用者にとって一番ふさわしいのか、全体的なまちづくりをするに当たって、どういったものが必要なのか、それを検討しながら、だれがそれをやっていくのか、ＰＦＩ方式だとか、いろいろな方法があろうかと思いますけれども。","voiceIndex":70,"id":"exchange-012"},{"speaker":"菊地委員","kind":"質問・要望","question":"そうすると、実際に国からどこが買い取って、どうするかということは、これからの問題として、こういう計画がありますという話なんですよね。そうすると、大田区内にある土地の中で、これから新たに発生するこの土地について、品川区の副区長がこの協議会に参加しているという、それの理由だけ、ちょっともう１回教えていただきたいと思います。","respondent":"松代都市計画課長","answer":"そういった中で、今回たまたま５３haの土地利用のところで特化されてなされていますけれども、広くはずっとそういった歴史的な経緯の中で、今度Ｄ滑走路ができて、増便計画が図られ、２４時間就航することが開始されますと、当然のことながら、品川区に対しても。","voiceIndex":72,"id":"exchange-013"},{"speaker":"三上委員","kind":"意見","question":"前に、二世帯住宅の助成のときに申込期間というのが１年に１回、それもどちらかというと、夏以降ぐらいに、その年の初めからずっと通して１年間の助成ということで、それを何とか改善してもらいたいという話をして、改善してもらったわけですけれども、この一連の省エネルギー対策等については、助成の申し込みをする段階から助成までの期間というのはどれくらいあるのか。","respondent":"柏原住宅担当課長","answer":"ただ、いかんせんまだこういう金額ですので、あっという間に助成の金額がなくなってしまうことも考えられますので、次年度に向けて、その辺、支払いの方法であるとか、いかに迅速にできるかというのは検討させていただければと思います。","voiceIndex":86,"id":"exchange-014"},{"speaker":"三上委員","kind":"質問・要望","question":"この３００万円を使い切ったといって、それだけ今、住民は要望しているんだと思ったら、その段階で、６月補正だって、９月補正だってあるじゃないですか。今求めているのは、こういうところを求めているんだということになったら、そこのところを少し拡大したっていいわけでしょう。そうだったら、そういう気概というのを示すという意味合いで、もうちょっとしっかりやったほうがいいんじゃないですか。","respondent":"岩田防災まちづくり事業部長","answer":"ただ、区としてもやはり予算枠だけは倍ほど用意すると。今回申込期間を限定はしていますけれども、これはこの間に着工しなければいけないというものではなくて、今年度中、来年３月までに工事が完了する予定がある方はだれでも申し込めると。","voiceIndex":88,"id":"exchange-015"},{"speaker":"三上委員","kind":"質問","question":"これは戸建て住宅に限らずですか。マンション等については、管理組合等、いろいろな形で申請してきた場合には、対象になるのかならないのか。","respondent":"柏原住宅担当課長","answer":"一応戸建てということで、募集しております。","voiceIndex":90,"id":"exchange-016"},{"speaker":"三上委員","kind":"質問","question":"もう１つは、ここで問題なのは、複層ガラスの建具を使用する工事、断熱効果ガラス、これは私、いつか予算特別委員会でも言ったガラスの結露の問題等についても、そういうふうに改修するんだったら、今、古い共同住宅はこの問題でいっぱい悩んでいます。だから、戸建て住宅だけじゃなくて、共同住宅にしても使える制度にしていかないとおかしなことになってくるんじゃないですか、どうなんですか。","respondent":"柏原住宅担当課長","answer":"特に今年度は東京都であるとか、国の助成も始まりましたので、東京都のほうは集合住宅のほうも対応するような助成制度のようですので、そういったところを見ながら、どこまで広げるのか、どこまでやるべきなのかというのは、今年度の状況を見ながら。","voiceIndex":92,"id":"exchange-017"},{"speaker":"三上委員","kind":"質問","question":"この制度そのものというのが、省エネルギー型設備設置工事、断熱・遮熱化工事、シックハウス対策工事と３つのことを言っているわけでしょう。となれば、シックハウスというのは、戸建て住宅だけにあるんですか。","respondent":"片田建築課長","answer":"シックハウスについては、マンションとか、戸建て住宅を問わず、住宅については、シックハウス、揮発性有機化合物を生じさせないような材料を使っていただくということでの考え方で今進めている状況です。","voiceIndex":94,"id":"exchange-018"},{"speaker":"三上委員","kind":"質問・要望","question":"だけれども、そうじゃなくて、断熱・遮熱化工事、それから、シックハウスまで含んだ、そういう住環境を少しでも高めようということで一緒にした募集要項をつくっているわけだから、そうであるならば、それはそれなりにすべてに対応できるような制度にしていかないと、おかしな話になってしまうということだと思いますので、やっぱり見直しできるところについては。","respondent":"岩田防災まちづくり事業部長","answer":"既に出発している戸建て住宅のものについては、とりあえず乗せようということで始めておりますので、総合的な環境対策として、今後区として、企業等も含めて、どういった助成、あるいは指導というもの、誘導策をとっていけるかということは。","voiceIndex":96,"id":"exchange-019"},{"speaker":"井上委員","kind":"意見","question":"今のことに大分関連してくるかなと思うんですが、今、最後に部長が、住宅支援策としてのものに、環境政策がついてきた事業であるということで、私もこの環境共生住宅という事業の内容をもうここで分けて、自然エネルギー中心というところの、今回区内のＣＯ2を把握した上で、地域推進計画をつくるというのがありつつ。","respondent":"柏原住宅担当課長","answer":"ただ単に住宅だけの話ということではなくて、環境全体の話ということ、それは関連の課と協議等、いろいろ話をしながら、どういったことができるのか、どういった政策が一番いいのかというのは、今後詰めていきながら、こういった政策を進めていきたいと考えております。","voiceIndex":98,"id":"exchange-020"},{"speaker":"井上委員","kind":"質問","question":"聞かれたら答えますと、たったの２行もあればいいわけで、それはもう新聞とかを見ていれば、みんな思っていることだけれども、区はそれができないのかということになると思うので、そういう配慮は必要だと思うんですけれども、これがもうこのまま１３日に出されてしまっているんですけれども、そういったところは考えないんでしょうか。","respondent":"柏原住宅担当課長","answer":"ただ、東京都のほうは２年間だけの助成事業のようですので、あと国がどのぐらいやるかというのもありますが、その辺も考えながら、次の募集のときに、どういった形が効果的なのかというのはちょっと検討したいと考えています。","voiceIndex":100,"id":"exchange-021"},{"speaker":"井上委員","kind":"質問・要望","question":"いつも行政のほうの説明というのは、問われれば答えますという姿勢がいろいろなところであらわれていると思いますので、ホームページなんかもそうなんですが、詳しくはお問い合わせください、もう少し書いた上でお問い合わせならいいんですけれども、題名だけ書いてお問い合わせくださいと、何て失礼なんでしょう、こういうふうに思うところもありますので、もう出していいものであればどんどんと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-022"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"井上委員","kind":"質問","question":"このＥＢＡＲＡ夢フェスタは、駅の完成記念式典と伺っていたと思うんですが、夢フェスタ２００９とあるということは、実行委員会の方たちのお話かもしれないんですが、恒例にしていこうという、それで２００９なんでしょうか。","respondent":"松代都市計画課長","answer":"そういう夢はあると思いますが、現在のところ、私どもが一緒にやっている中では、まずは今回を成功させようと、そこの１点に集中していますので、その結果等を見て、地元の方々の発意等があれば、また引き続き続けていけるものではないかと思ってあります。","voiceIndex":108,"id":"exchange-023"},{"speaker":"原委員","kind":"質問・要望","question":"１点だけ、ちょっと前にこの夢フェスタという、何か配布物を配って、回収してまた配っているということを聞いたので、その辺、簡単で結構なので、教えていただきたい。","respondent":"松代都市計画課長","answer":"委員ご指摘のとおりでございまして、チラシ、ポスターをつくりました。それを一部配布したところですけれども、その内容の一部に不具合がございまして、刷り直すということで、大変不手際ですけれども、回収して、今新しいものを作成しています。","voiceIndex":110,"id":"exchange-024"},{"speaker":"三上委員","kind":"質問","question":"予算特別委員会でも、５００万円は何かという私の質問に、リース料だというだけで終わってしまったんです。心配するのは、もう天気だけだというんだったら、いいんです。報告があったから、一言言わせてもらったけれども、本当に区としても、だれがこれについて、取りまとめはここですと、そこに聞けば、すべてわかりますということであってもいいんじゃないかなと思うんですけれども、どうですか。","respondent":"松代都市計画課長、岩田防災まちづくり事業部長","answer":"数年前から目黒線立体化工事等々の完成をにらみ、また、駅前広場の完成をにらみ、何か地域を上げてイベントをという思いがずっとあったように聞いています。それを具体化するようになったのは、ここ１年のことだと考えています。したがって、品川区は実行委員会の委員のメンバーではなくて、共催のメンバーとして、一緒に計画をつくっているということで、すべての動きを把握しているのはパルムの商店街の会長が把握しているということと、品川区のほうは。","voiceIndex":112,"id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3940#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":29490,"voices":116}},{"id":"h21-20090414-9","meetingId":"h21-cm04","date":"2009年4月14日","dateIso":"2009-04-14","committee":"文教委員会","time":"午後１時０３分～午後３時１８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の組織改正に伴う事業部等の所管事項の変更","agenda":"の組織改正に伴う事業部等の所管事項の変更","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"もう一回ご説明いただきたいと思うんですけれども、はじめに教育委員会のほうで１点なんですけども、今回の組織改正で、従来学務課の学事制度担当が庶務課の教育施設調整担当に統合という話でしたけど、位置づけがどう変わるのか、変更の理由をもう少しご説明いただけるでしょうか。位置づけの変更はあるのかどうか、理由を含めて教えてください。","respondent":"田村庶務課長","answer":"それで、もともとの名称が昨年３月までが、要は校舎改築計画担当と、要するにハード部分のどうしても名前の印象から校舎改築の計画をどんどん進めていくよと、具体的なハード部分、技術職も含めているんですが。","voiceIndex":22,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"それと、子ども未来事業部のことなんですけども、一つは、奨学金に関する事務が区民課から移行とありますけども、似たような質問なんですけど、奨学金の位置づけというか目的、そこに何か変更があるのか、そこを説明していただきたいというのが一つ。","respondent":"田村庶務課長、小林青少年育成課長","answer":"先ほどの繰り返しになりますけど、やはりハード部門というのは、固定化して３０年なり、改築すると３０年、５０年もつ校舎を建てなきゃならないというので、今までも学務課とは調整をしながら学級数の見込みを含めて。１点目の奨学金の位置づけですけれども、特に移管に伴いまして視点の変更等はございません。従前どおり区の担当している部分として、高校在学の子どもたちに対しての就学の環境を整えるという形で考えております。","voiceIndex":24,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほどちょっとご説明ありましたけど、児童センター、保育園、品川・大崎地区、大井・八潮地区、荏原地区と３分割するんですけれども、運営のイメージのポイントと言いますか、解説というよりもねらいをもうちょっとご説明いただきたいというのと、現に保育園を利用されている保護者の方、児童センターの保護者の方、さまざまいらっしゃるわけで、保護者の方への説明といいますか。","respondent":"小林青少年育成課長","answer":"保護者の方への周知ですけれども、こうした組織の考え方あるいは事業の流れというのは、先にお届けさせていただきました子育ての特集号等を使って周知していくほか、保育園や幼稚園では保護者会がありますので、その中で十分その趣旨を説明していければと思います。","voiceIndex":27,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"その辺、ちょっとどんなふうに対応してきたか、ちょっと抽象的な質問で申しわけないんですけど、そこを一つと、今年とりわけ保育園に入れなかったお子さんが多かっただけに、実際どれぐらいの数だったのか少し教えていただきたいんですけれども、カウントの仕方でいろいろ数が違うので、４月入園を申し込みながら、これがかなわなかった子どもの数、そこだけ教えていただけますか。","respondent":"小林青少年育成課長、吉岡保育課長","answer":"４月１日時点での在園状況については、保育課長のほうから説明をします。この１,５００人を超える申し込みに対しまして、１,１０１名の方に対しまして入園はできたところですけれども、特に１歳の乳児の方を中心として、平成２０年度と同程度。","voiceIndex":29,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"待機者は昨年よりも増えているというお話ですけど、例えば兄弟が別々になってしまうとかがあって、そうすると、地域割も別々になってしまう方もおられるのかもしれない。地域割、担当割といいますか、これをどのように機能するのか、正直まだ不安が残るなと思います。子どもや保護者の実態と合わせて進めていただきたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"すまいるスクールというものが学校の中にあるんですけれども、小学校の子どもたちの位置づけというのはどうなってくるのかがちょっとなかったので、そこはどういう連携をつくるのか、つくらないのか、単独ですまいるスクールは、すまいるスクールとしていってしまうのか、地域の子どもというくくりになると、それはもうちょっと広い意味で見ていかないといけないのかな。","respondent":"小林青少年育成課長、田村庶務課長","answer":"大切なことは、この３地区、地域に根ざすというところで、地域を大切にしながらも、同じ連携を強めるということで、幼稚園、保育園、あるいは児童センターの人たちが一同に会して子どものためにはという視点で連携を強める。すまいるスクールの関係ですが、既にすまいるスクールは放課後対策ということで３８校の小学校で実施しておりますけど、特にブロック、その中でまた幾つかのブロック、ブロック会というのを全体会と設けています。","voiceIndex":33,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"要望はありますけれども、ＰＴＡの、保育園ＰＴＡですが、幼稚園にもＰＴＡがあって、そこはもうちょっとコラボレートといいますか、いろいろお互いが接するようなことをやっていただきたい、幼稚園と保育園の間ですね。一つ関連で確認したいんですけど、この表の中に児童センター、その他、キッズ館というのがあります。キッズ館というのはどういうものを示しているのかをお聞かせください。","respondent":"小林青少年育成課長、吉岡保育課長、古川子ども未来事業部長","answer":"前段の保護者の関係は、同時に子どもを育成していくという関係の一つとして、親育ちの点も含めて対応していきたいと考えています。今、ご説明いたしましたように、品川・大崎地区、大井・八潮地区、荏原地区と３地区に、地区の中での子育ての総合的な展開ということで考えてありますので。しかしながら、伊藤児童センターを館長館というのは、今の現状の中でちょっと難しい部分がありますので。","voiceIndex":36,"id":"exchange-007"},{"speaker":"川西委員","kind":"質問","question":"全体の組織としては別にこれで運営されることと思いますので、ちょっと部分的なことで質問します。幼稚園のことですけれども、幼稚園が各３課に地区ごとに分割をされたということと、今まで学校長が幼稚園長、公立ですよ、兼務しておられたのはどうなっているのか。これも３課にまたがっていて、地域ごとに分割されているのは、どこで取り扱うかですね。１回区切ります。","respondent":"小林青少年育成課長、吉岡保育課長、田村庶務課長","answer":"幼稚園の園児募集は、一つは受け付けは各園で受け付けておりますけれども、各園で受け付けたものは。園長ＯＢの配置ですけれども、その辺につきましては、保育課のほうの配置になってあります。ＰＴＡの調整の事業ですけれども、基本的には現行３月まで生涯学習でやっていた方が庶務課のほうに異動したです。","voiceIndex":40,"id":"exchange-008"},{"speaker":"川西委員","kind":"質問・要望","question":"大方わかりました。それで、幼稚園なんですけれども、公立幼稚園、定数がありまして、地区によってはちょっと都心はオーバー気味で、例えば私は城南幼稚園の地区に住んでいるんですけれども、毎年オーバー気味で、許容範囲というのは一応の流れの中で規則があって、３４人とか３３人までとか、歴史的な経過はちゃんと引き継いでいただいているんでしょうかね。その辺は専門的な立場からいかがでしょうか。","respondent":"古川子ども未来事業部長、小林青少年育成課長","answer":"そういう点から申し上げますと、小学校の校長先生が幼稚園の園長を兼任されているということは、ある意味では小学校との大変心強いかかわり方も出てまいりますので、現状がそうであるからではないんですが、当然専任を求めつつも。幼稚園の入園の件ですけれども、ご承知のとおり幼稚園は１クラス編制３０名を基本としながら規則の改正によりまして３５名までは対応可能という制度の中で、より多くの入園希望に柔軟に対応していくという考え方で対応しております。","voiceIndex":47,"id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１点目は、教育委員会のほうでお願いだけというか、期待を込めてというか、これは変わっていないんですけれど、すまいるスクールの担当（主査）制がそのまま残されていたというか、そのまま庶務課にあるわけですけれども、非常に金額も大きくなってきているし、私はここは担当主査という形でいいのかと本当に思っているところがあります。ぜひそれをお願いしたいな。それをぜひお願いしたいと思っています。","respondent":"小林青少年育成課長","answer":"今度は、保育園、幼稚園、児童センター、そういった子ども全体の計画、例えば次世代育成の計画ですとか、そういった極めて上位に位置する二元的な政策形成については青少年育成課で３課の知識を持ち寄って対応していくというイメージで考えております。","voiceIndex":50,"id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひわかるようにしていただきたい。ここはたまたま保育課だけれども、この「等」に児童センターもあるわけだし、幼稚園もあるわけだから、保育課と書いてあるけれども、そこの運営係で児童センター、それから幼稚園等も全部そういう修繕だ、何だというのを一括管理して予算執行をしていくという理解でいいんですかね。","respondent":"小林青少年育成課長、古川子ども未来事業部長","answer":"今年度の到達点として、児童センターにつきましては、引き続き旧児童課、新たな施設で子育て支援課がキッズ館を除きまして全体を統括し、そして施設の管理等も行っていくということで対応を予定しております。大前提として、ちょっと先ほど来説明している中で、これはちょっと前提となりますのは、児童センターと保育園、幼稚園、これは全く同じに今回は扱っていないということです。","voiceIndex":52,"id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"意見","question":"このＡ３のやつなんだけど、今のご説明で大体はわかったんですけど、青少年育成課長のところの下に事務局と丸がありますよね。これはこの三つのある程度統括をして、だから、我々の理解で言うと、庶務担当課長みたいな部分で、上位計画もやるけれども、その部分の中で、そういう部分を全部統括してある程度意見を集約して、事業部の中の考えをここでまとめていくよという課と思えばいいという理解でいいのか。","respondent":"古川子ども未来事業部長","answer":"それは部の庶務担当課である青少年育成課が当然担っていく役割だろう、こういうことです。委員のご指摘のとおりです。","voiceIndex":55,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"このくくりは、いわゆる地域センターというか、町会というか、青少年というか、それなのかどうか教えていただきたいのと、原小学校にできた西大井の保育園、名前をど忘れしちゃったんですけども、こうほうえん、あの保育園というのは、この中だと、どこに入るのか教えていただきたい。","respondent":"小林青少年育成課長","answer":"西大井はキッズタウン西大井という認可保育園。こちらは私立保育園になっておりますので、公立の中には入れておりませんが、キッズタウンを含めまして、全１０私立保育園同様に、別な意味で対応、連携をとりながら認可保育園としての一体性を持っていくということです。","voiceIndex":57,"id":"exchange-013"}]},{"id":"topic-02","title":"平成２１年度学級編制","agenda":"平成２１年度学級編制","exchanges":[{"speaker":"川西委員","kind":"質問・要望","question":"小学校のほうで、１５番の原小学校、それから大井第一小学校のことなんですけれども、何学級まで教室の収容能力があるのか教えておいてください。それから、伊藤学園のほうですね。伊藤学園のほうは、ここも教室数としては５学級が限度なのか、これが６学級まで行った場合に教室があるのかどうか教えておいていただきたい。","respondent":"富田学務課長","answer":"それと、大井第一小学校が何学級までですが、最近では各学年４学級ということが多い傾向ですが、年度によりまして５学級まで増えた学年も最近あったかと思います。中学校につきまして、６番の伊藤学園ですが、施設的には５学級を想定した施設です。","voiceIndex":68,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"前の文教委員会でもご報告があったと思うんですけど、もう一回教えていただきたいんですけど、抽選が行われた学校と、あと空き待ちをしても希望する学校に入学できなかった学校、抽選後も繰り上げみたいな形で、結果としてみんな入れる場合と入れない場合があるので、抽選が行われた学校と、それと結果としてどうしても入れなかった学校、小学校と中学校で、ちょっと教えていただけますか。","respondent":"富田学務課長","answer":"小学校についてですが、抽選を行いましたのは、６番城南第二小学校、８番第二日野小学校、１０番第三日野小学校、１５番原小学校の４校です。結果として、待機のままの方が出ましたのは１０番の第三日野小学校１校です。","voiceIndex":72,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"なぜ伺ったのかというと、昨年の秋ぐらいの文教委員会だったでしょうか、今年４月から入学する子どもたちについて、学校選択制の受入枠の説明がありました。","respondent":"富田学務課長","answer":"今回希望申請で抽選をした学校というのがありますけれども、本来の通学区域の方しか入れなかった学校というのはございません。","voiceIndex":74,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"わかりにくくてごめんなさい。そこをどういう理由なのか教えていただきたい。例えば、品川小学校で言うと、６０人という説明だったけど、ここには７９人と載っているので、だけれども、抽選が行われなかったという説明だったので、その辺がよくわからないので教えていただきたい。この８校では、選択制がされなかったという、ちょっとよく意味がわからないので教えてください。","respondent":"富田学務課長","answer":"６０人等といった受入枠はあくまでも目安ということでございまして、各学校長と調整をしながら、できるだけ希望に沿えるような形で努力をした結果、このような形になったものです。","voiceIndex":76,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"ということは、中学校のほうも超えているということは、同じ理由だということでよろしいんでしょうか。あのときの説明で、施設上の理由から人数を設定したんですというお話と、その１点も実態に応じて受け入れているというところの整合性がよくわからないんですよね。その辺の判断の基準がよくわからなかったので、その受け入れの目安ということの説明を教えていただけますか。","respondent":"富田学務課長","answer":"小学校については６年間、また中学校については３年間という間にその学区域への転入・転居の方々がいらした場合に、その学校に受け入れをしていくということを基本としながら、どの辺までオーケーかということを各学校長とぎりぎり調整した結果です。","voiceIndex":78,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"あのときの受入枠を決めましたというその説明は何だったのかよくわからなくなっちゃうんですけども、もう一度、その意味というか、理由というか、そこを教えていただけますか。","respondent":"富田学務課長","answer":"何回も繰り返すようですけれども、受入枠というのは、施設上の都合を勘案した、状況を勘案したところでの受け入れる学級、人数の目安です。","voiceIndex":80,"id":"exchange-019"},{"speaker":"西本委員","kind":"質問","question":"小学校のほうなんですが、２年生のところに学級維持制度適用というところが２カ所ありますが、宮前小学校はわかりました、３９人で適用になったということなんでしょうけど、山中小学校は４３人で２学級というのはどういうこと、もともと２クラスではなかったんですかね。ところが、特別支援が１クラスになっているんですが、これはどういう意味でしょうか。","respondent":"富田学務課長、冠木指導課長","answer":"学級維持制度についてですけれども、学級維持制度というのは、クラス替えにより安定した学級経営や児童・生徒への継続的な支障が生じる理由がある場合ということで、増の場合でも、また減の場合でもあるのですけれども。ただし、１カ月以下、短い期間で入院されていて、勉強の面倒を見るというような場合には、その学校のほうから、清水台小学校のほうから病院のほうに赴いて指導等がなされていると、そういう状況もあります。","voiceIndex":82,"id":"exchange-020"},{"speaker":"西本委員","kind":"質問","question":"清水台小学校については、今長期の入院の方はいらっしゃらないということですけれども、クラスが一つというのはどういう意味なんですかね。特別支援学級という考え方は、清水台小学校の中に所属する人はだれもいないけれども、一つの部屋を確保しなきゃいけないということなのか、あるかもしれないということで、クラスだけは確保しておきましょうということですかね。","respondent":"冠木指導課長","answer":"清水台小学校のさいかち学級については、委員ご指摘のとおりです。戸越小学校の通級学級につきましても、今委員おっしゃったように子どもの数に合わせて、教員の数、学級とかが決まりますので、そのとおりです。","voiceIndex":85,"id":"exchange-021"},{"speaker":"西本委員","kind":"質問","question":"先ほど宮前小学校と戸越小学校のほうは、平成２１年度は３クラスなわけですよ。２３人で２クラスなわけですよ。だから、初めのご答弁のところでは子どもの状況に応じてクラス数があるんですよという答弁だったんですが、次の答弁の中では、人数によって決まっていますと。それだったら、２１人で３クラスで、２３人で２クラスというのは、どういう意味なんですか。","respondent":"若月教育長","answer":"これは障害の種類ですね。聴こえと、それから言葉と、この２種類があるんですね。それによって、教育の、要するに機器だとかさまざまなものが違いますから、それによって変わってくるわけです。その学級の数も子どもも変わってくるわけです。","voiceIndex":87,"id":"exchange-022"},{"speaker":"山元委員","kind":"質問・要望","question":"一つだけ教えていただきたいと思います。中学校のほうの浜川中学校なんですけれども、特別支援の生徒数が２２人ということで３クラスということなんですが、内訳を教えていただけますでしょうか。何年生に何人とかということを教えていただけますか。","respondent":"富田学務課長","answer":"すみません、特別支援学級の学年ごとの内訳はちょっと手元に本日持ってきておりません。申しわけありません。","voiceIndex":89,"id":"exchange-023"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１点だけ、すみません、教えてください。そうすると、毎年、例えば今回であれば、三木小学校が３９人とか、第一日野小学校８２人とか、大原小学校なら４０人とか、こうあるわけですね。これは非常に早い時点で減ることを前提に申請をするかということが１点教えていただきたいのと、あと、私、間違っていたのかもしれないんだけど、例えば品川小学校みたいに７９人だと。それでいいのかどうか。","respondent":"富田学務課長","answer":"品川小学校の７９人についてですが、４０人の学級編制、４０人編制でやっておりますので、８１人から３学級になるですが、これは４月１日に基準日となっておりまして、この届出で協議を行っておりますが、４月７日現在の児童・生徒数で変更があった場合には。","voiceIndex":93,"id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"意見","question":"だから、私が言いたいのは、学級維持制度というのは１年、２年でクラスもかえないでそのままいこう。５年、６年もいろいろ中学に行く、私立に行ったりいろんなことがあるから、あまりクラス替えもしないでいこうよという理解ね。８年生、９年生もそうなんだけど。そのときには、別にクラスの中でどうということではなくて、２年になるときには３クラスになるんでしょうという理解でいいのかどうか。","respondent":"富田学務課長、若月教育長","answer":"申しわけありませんでした。８１人を超えた場合、３学級となることを学校のほうで希望する場合にはそのままでいれば３学級になるということです。だから、さっき説明の中で、増減と言ったでしょう。そういうことなんですよ。確かに品川の場合には考えにくいことかもしれないんですけれども、東京都も広いんですね。","voiceIndex":95,"id":"exchange-025"},{"speaker":"石田（秀）委員","kind":"意見","question":"これは来年も３クラスで、もし７９人になったとしても、３クラスでお願いしますよというのを早目に申請するんでしょう。考え方で嫌だというところがあるかもしれないというから、品川区の考え方で、例えば品川小学校とか大原小学校みたいに４１人とか８１人になった場合に、品川区は前もってその人数が増えた場合は３クラスにしますよというのを申請しておかなくちゃいけないわけ。","respondent":"若月教育長","answer":"そうです。","voiceIndex":98,"id":"exchange-026"}]},{"id":"topic-03","title":"の平成２１年度品川区立幼・小・中学校（園）長、副校（園）長異動者名簿","agenda":"の平成２１年度品川区立幼・小・中学校（園）長、副校（園）長異動者名簿","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"ちょっと教えていただきたいんですけど、施設一体型小中一貫校は、１人の校長先生と３人の副校長先生ということですけれども、東京都教育委員会には、それぞれ小学校の校長、小学校の副校長、中学校の校長、中学校の副校長というふうに届ける、届けるのかよくわからないですけど、その辺の仕組みが前からよくわかっていなかったので教えていただけますか。","respondent":"和氣小中一貫教育担当課長、冠木指導課長","answer":"基本的にどこの籍にあるか、校長は１名ですので、中籍か小籍、どちらかになります。後段の質問についてですが、区費の教員の配置先ですけれども、１名が大井第一小学校、１名が第二延山小学校、１名が大崎中学校、１名が鈴ヶ森中学校、１名が冨士見台中学校です。","voiceIndex":108,"id":"exchange-027"},{"speaker":"中塚委員","kind":"質問","question":"校長先生と副校長先生の小籍と中籍という、ちょっと意味がよくわからなかったんですけど。小学校に籍がある、中学校に籍があるという意味ですよね。そうすると、厳密に決めていないということなのか、それとも一応決めてあるのか、よくわからないので教えていただけますか。","respondent":"和氣小中一貫教育担当課長","answer":"例えば、日野学園でも小籍の副校長先生が異動したんですけど、もともと中籍だった主幹をその小籍の副校長に充てています。という形で、そこは協議をして対応できますので、実際の学校の今後の方針も含めまして検討して配置を決めているところです。","voiceIndex":111,"id":"exchange-028"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"すみません。もしわかったらでいいんで、言えれば番号で言っていただきたいんですけど、数が多いというなら、小学校何人とかでもいいんですけど、再任用の方を教えてほしい。","respondent":"冠木指導課長","answer":"再任用の校長先生につきましては、現在９番の芳水小学校、それから２６番の大原小学校、３０番の第二延山小学校でございまして、中学校のほうは２番の城南中学校と１１番の荏原第三中学校です。","voiceIndex":113,"id":"exchange-029"},{"speaker":"石田（秀）委員","kind":"質問","question":"なければいいんですけど、幼稚園はないのかというのと、あと副校長先生はないのかというのも教えていただければありがたい。","respondent":"冠木指導課長","answer":"幼稚園の園長先生には再任用の方はいらっしゃいません。それから、副校長のほうにも再任用の副校長先生はいらっしゃいません。","voiceIndex":115,"id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"質問","question":"そうすると、幼稚園とはちょっと違うという形があるのかもしれないけれども、考え方として再任用の方々でも一生懸命３日の時間のあれ以外でも常勤で再任用というと大変その中でやっていただいている方が多いわけですけれども、幼稚園もそういう方向性で少し考えるのか、保育園は多いからね、園が。いい人がいればそういうことも考えるということか、お考えを教えてください。","respondent":"若月教育長","answer":"基本的に教育委員会として幼稚園だから、小学校だから、中学校だからという明確な区別をするようなことは考えておりません。","voiceIndex":117,"id":"exchange-031"},{"speaker":"西本委員","kind":"質問・要望","question":"幾つかお聞きしますが、まず、この表の見方の中で、括弧で欠番というのが書いてあるんですね。統廃合になっているので、というところもあるわけですね。それと最後に、校長先生、副校長先生を含めて、人事権というのはどこまで教育委員会の意思が、採用権、人事権は都になるわけですから、それをどれぐらい品川区の要望というのは取り入れられているものなのか、ほとんど品川の要望どおりになるのか。","respondent":"冠木指導課長、和氣小中一貫教育担当課長","answer":"しかし、品川区の教育改革を進めていく上で、必要な人材というのは私どももこういう人材といったものを考えとして持ってありますので、そういった部分で東京都のほうに今後も内申をして働きかけをしていきたいと考えています。小中一貫校の校長先生は中籍じゃなきゃいけない、小籍じゃなきゃいけないという考えはございません。力があれば、どなたでもというふうに考えてあります。","voiceIndex":119,"id":"exchange-032"},{"speaker":"西本委員","kind":"質問","question":"欠番の表記の件ですけれども、次回からとなると、結局一番左側の数字というのが抜けているのがあるんですよね。それが抜けないで通し番号になりますよという理解でいいのか、施設一体型のところに８、３、１５、６、こういう数字が出ているんですが、これは今後どういうふうになってくるのか、関連でお聞きしたいと思います。そういう考え方をちょっとお聞きしたいなと思います。","respondent":"和氣小中一貫教育担当課長、若月教育長、市川教育次長","answer":"したがいまして、小中一貫校においても、そういう経験のある分野もありますけども、新しい校種といいますか、違う校種のことをよくわかった上で。だから、臨機応変に対応していかなきゃならない。そういう部分がこの品川ですらまだあるんだです。私から名簿についてのご説明をします。","voiceIndex":122,"id":"exchange-033"},{"speaker":"石田（秀）委員","kind":"意見","question":"再度、１点だけ。もちろん教育委員会はご理解されているんだと思うんだけど、地域では校長先生と副校長先生が一気にかわった場合、非常に戸惑う、最初の４月ぐらいから。そうすると、地域で行われていることに新任の先生が２人とも、例えば校長先生、副校長先生、両方かわった場合は、本当に最初の１年ぐらい大変、地域の方々もね。そこら辺のフォローはどう考えられているのか。","respondent":"市川教育次長","answer":"そういう場合には、私どもの教育委員会の学校の管理職としての経験がある学校経営指導員なりを学校運営が軌道に乗るまできちっと補助スタッフとして配置するなど、そういった対応をしてまいりたいと考えています。","voiceIndex":126,"id":"exchange-034"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"質問","question":"そこでここで報告をされたのかということ。それからもう一つは、５月１７日１１時の記念式典なんですが、これは対象となる例えば委員会とかはあるんですか、委員側からいうと。普通、こういう式典ですと、担当の委員会の委員が参加するという形になっていたり、それが全員がとか、対象全員だとかいろいろあるんですけど、そういう区別があるんでしょうか。","respondent":"安井子育て支援課長","answer":"ご招待とか、式典のほうのご招待の関係については、まだちょっと詳しいところは決まっておりません。申しわけございません。","voiceIndex":132,"id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"わかりました。かなりここだけではなくて、いろんなものがあるんですかね、一応同時開催事業というので、関連しているものをここに出されたと思うんですけれども、もうちょっとほかにもあるんであれば、全体も何かあるんですか、お知らせとか、そういう冊子とか。そういうものがあれば、全体図が見えないので。","respondent":"安井子育て支援課長","answer":"今チラシとかは作成している段階だというふうには聞いておりますが、まだ私どものほうには手元に来ておりませんので、そういう段階です。","voiceIndex":134,"id":"exchange-036"},{"speaker":"中塚委員","kind":"質問","question":"日本保育サービスの認証保育園ということですけれども、品川区との調整というか打ち合せというか、いつごろから始まって、どういう経過で今日こういう報告になったか、その経過を教えていただけますか。","respondent":"吉岡保育課長","answer":"それにつきましては、ちょっと時期がいつというのは手元に持ってございませんけれども、昨年度来、こちらの株式会社日本保育サービスのほうからお話を受けまして、保育課として行政指導する中で、今申し上げたような開設の運びになったものです。","voiceIndex":139,"id":"exchange-037"},{"speaker":"中塚委員","kind":"質問","question":"昨年から話があって、その経過が見えないので、どういう調整をして今日に至ったのか、その経過を教えていただけますか。","respondent":"吉岡保育課長","answer":"経過ですけれども、一応開設をするに当たって定員をどうするかとか、園児の受け入れについてとか、施設の内容等々を調整してまいりまして、今申し上げたような結果になったところです。","voiceIndex":141,"id":"exchange-038"},{"speaker":"中塚委員","kind":"質問・要望","question":"どうしてそんなことを聞いたのかというと、今年から認証保育所の誘致が１,０００万円から３,０００万円に上がりましたよね。この辺の流れがちょっと不自然さを感じたので聞いたんですけれども、１,０００万円だから集まらなかったから３,０００万円にしたんだという話と、これは昨年から話があったんだというところの整合性がよくわからないので教えていただきたい。","respondent":"小林青少年育成課長","answer":"昨年来の折衝の経過ですので、昨年度中から施設の設置、それから東京都の認証を受ける関係もありまして、そういった折衝をしてまいった経過が年度をまたいだということでございまして、特段１,０００万円、３,０００万円ということが起因するものではございません。","voiceIndex":143,"id":"exchange-039"},{"speaker":"中塚委員","kind":"確認","question":"この日本保育サービスは１,０００万円の開設だということなのか、それとも３,０００万円ということなのか、そこをもう一回確認させてください。","respondent":"小林青少年育成課長","answer":"日本保育サービスは、この間認証の開設を前提として検討してまいりましたので、その時点で該当の会社は１,０００万円までの助成が物によっては受けられる可能性があるということを前提に参入を検討してまいった経過があります。","voiceIndex":145,"id":"exchange-040"},{"speaker":"西本委員","kind":"質問","question":"認証保育の施設上の、施設上難しいという場合はいろいろあると思うんですけれども、困ったという話を聞くんですよ。例えば認証保育所の中の保育の中身を、こういうクレームが来たので、こういう苦情が来たので、こういう形で検討しなさいとか、してくださいと言うのか、しなさいと言うのか、どこまで権限を持っているものなんでしょうか。","respondent":"小林青少年育成課長","answer":"事業者にいたしましても、助成金を、運用助成ですね、もらっているのは、品川区から、いわゆる認可保育園に相当する措置費に該当する助成金を交付されておりますので、不適切な運営がされれば、一定の限度はありますけれども。","voiceIndex":147,"id":"exchange-041"},{"speaker":"西本委員","kind":"質問・要望","question":"できれば、認可保育園に入りたいんですよ。できればその人たちは認可保育園に入りたいんですけど、でもなかなか入れない事情もあるので、そういう枠がないとか、保育園にはできないという現状があるので、やっぱり保育の内容をよくするということは、区のほうからもどんどんやっていただきたいと思いますが、ご意見をお聞きしたいと思います。","respondent":"小林青少年育成課長","answer":"基本的に親と十分連携して子育てということが可能になるという現状からいえば、区も十分な指導をして意思疎通がきちっとできるように指導してまいります。","voiceIndex":149,"id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4664#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":38356,"voices":156}},{"id":"h21-20090414-5","meetingId":"h21-cm04","date":"2009年4月14日","dateIso":"2009-04-14","committee":"総務委員会","time":"午後１時０２分～午後４時２３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"林委員","kind":"質問","question":"総務委員会の議事係の方が２人、一遍に動かれているんだけれども、これは委員長、事前にお聞きになっているんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-001"},{"speaker":"林委員","kind":"質問","question":"２人も一緒にかわってしまうということのデメリットみたいなものはないんですか。","respondent":"須藤委員長","answer":"もちろんデメリットなしとは言いませんけれども、本田書記については前に区議会事務局のほうにいらしたということであって、まるっきり新しくということではなくて、議会の状況を知っているというようなことの説明をいただきました。","voiceIndex":20,"id":"exchange-002"},{"speaker":"林委員","kind":"質問","question":"委員長はそういうわけで納得された。これを実績に、本来は議長がやるべきところの仕事も入っているかもわからないけれども、区長部局で議会事務局の異動をするというときに、そういう点についての配慮というのはないんですか。","respondent":"榎本人事課長","answer":"人事異動一括で、それぞれの仕事の内容をお聞きして動かしておりますけれども、細かい事務分担というところまでは、すべてを網羅するというのはなかなか難しいので、なるべく網羅はしていきたいと考えていますけれども、結果としてこうなる場合もあるかなと感じております。","voiceIndex":22,"id":"exchange-003"},{"speaker":"林委員","kind":"質問","question":"細かい点までなかなか考慮がいかないということがあれば、事務局長にお聞きしますけれども、一たん内示というか、そういうときに、この人とこの人を一度に動いちゃうと、議会事務局としては、こういうことで配慮をしてほしいというようなことを言うような仕組みにはなっていないんですか。","respondent":"桑村区議会事務局長","answer":"その意味で、すべてを議会のほうでの考え方というのを私が通すというわけには、なかなか難しいのかなと考えておるところです。","voiceIndex":24,"id":"exchange-004"},{"speaker":"林委員","kind":"質問・要望","question":"一般的に、普通、ふだんの異動というのはそれはそれで区長部局でお考えになってやられるんだろうけれども、議会サイドの中の、こういうふうにたまたま同じ委員会の議事係の方が２人、一遍に動くというのは、もちろん支障が出ないように周りの人もサポートしてくださるだろうし、委員長もいろいろお気遣いされるんでしょうけれども、やっぱりちょっと、一遍に２人の方というのは異様に映るので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-005"}]},{"id":"topic-02","title":"の組織改正に伴う事業部等の所管事項の変更","agenda":"の組織改正に伴う事業部等の所管事項の変更","exchanges":[{"speaker":"林委員","kind":"確認","question":"本当に９時ぐらいまで、残っている人がこの中にいればわかるだろうけれども、こうこうと電気がついていた。それを異常に感じたのは僕だけなのかなと思いますけれども、お客さんは、その時間まではいないはずだろうから、中の細かい整理をされていたんだろうと思うんだけれども、確認の意味で、大丈夫だったんでしょうね。","respondent":"久保田行財政改革担当課長","answer":"私もいろいろと庁内の中、歩いているときに、職員がお客様、いろいろ迷っている方がいますと、積極的に声をかけている姿も見てありますので、そういった意味ではお客様に混乱は与えなかったと考えています。","voiceIndex":31,"id":"exchange-006"},{"speaker":"林委員","kind":"質問・要望","question":"だから、僕は、しばらく、４月になってからは、３７７７－１１１１で、「何々課の何々課長さんとか、何々係長さんをお願いしたいんですけれども」って。この方は企画部長という立場におられた方で、企画部長が室長にかわるというのは、相当、僕らでは考えられない事態だと思うんですけれども、ご本人は耳に栓をしておいてもらって、説明をしてくださった行財政改革担当課長に答えていただきたい。","respondent":"久保田行財政改革担当課長","answer":"会計管理室につきましては、組織規則とは別のところで、会計管理室の設置規則で書かれておりますので、そういう組織上の変更ということではございませんけれども、私どもといたしましては、昨今、いろいろな金融情勢等が不安定な状況にあるということもございまして。","voiceIndex":33,"id":"exchange-007"},{"speaker":"林委員","kind":"意見","question":"収入役室がなくなってまだ５年ぐらいかな、五、六年ぐらい。だけれども、企画部長というのは品川区という組織の中では、１位、２位と順位をつけるのはいかがなものかと思うけれども、やっぱり自治体としては企画室が一つ、いろいろな意味で引っ張っていくというのは僕らの認識なんですわ。当事者でもいいし、変えたほうでもいいし、区の責任者でもいい。","respondent":"本間副区長","answer":"そこの経営基盤もいろいろと専門的に、できる限り審査をするという部分も出てきております。そういう意味では、会計管理室というものの職責を担う者を今回このような形で考えたということなんですが、一方で、じゃ、企画部をさげすんでいるとか何かということではございません。","voiceIndex":35,"id":"exchange-008"},{"speaker":"林委員","kind":"質問・要望","question":"いっぱい聞きたいことがあるんだけれども、最後に１つだけ、総務委員会に関係すると思われる、１ページ目の施設整備課という新設された課があって、そこにいろいろな担当主査制が入っているんだけれども、この役割についてはライセンスというか、資格というか、そういうものがあって、ここの仕事につける、あるいはここの係長、主査につけるというふうに思うんだけれども。","respondent":"榎本人事課長","answer":"ただ、そうはいえ、団塊の世代の退職を見据えていきますと、若手の職員で若干、資格をとっていない方もいますので、それは今、資格助成ということで取るような形をしていますし、それとあわせて経験者採用というところの中で、建築士とか。","voiceIndex":37,"id":"exchange-009"},{"speaker":"林委員","kind":"質問","question":"きょうもニュースでクレーンが倒れて、おおけがの事故があったという。事故につながるような部署ですので、きちんとした資格を持った人にきちんとした指示を与えて、仕事をしていかれるようにお願いをしておきます。いずれお聞きしたいと思いますけれども、きょうはこれでやめておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-010"},{"speaker":"南委員","kind":"提案","question":"２つ目は、消費者センターが商業・観光課になるんですけれども、今、国でも消費者庁設置の部分で、いろいろと検討が具体的になってきているんですが、そういう状況を見たときに、消費者行政というの、いろいろ、今までは消費者センターで苦情も含めていろいろな対応をしていたと思うんですけれども、その辺、国との関係の中で、商業・観光課というところに、組織改正で、これ、決まったことですから。","respondent":"久保田行財政改革担当課長","answer":"ただ、私どもとしましては、保育課で管理運営をやってありますので、教育委員会が基本ですけれども、その運営の部分について補助執行という形で、保育課でやっていくということのご説明をさせていただいたところです。","voiceIndex":40,"id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"幼稚園の部分なんですけれども、今までの、ここ一、二年前から、幼稚園が保育課のほうと一緒になって管理運営をしているということは承知してきているんですけれども、改めて、この間のそういう事務執行というか、事業を展開されていて、直接の担当じゃないのであれですけれども、長短、改善しなくちゃいけない部分がもしあれば。","respondent":"久保田行財政改革担当課長","answer":"幼稚園につきまして、幼保一体施設といったところで、保育園と幼稚園との連携を進めているというところがありますので、就学前教育というところでは、幼保一体の連携というのは非常に必要だという形で考えておりますし、区民の方からも。","voiceIndex":42,"id":"exchange-012"}]},{"id":"topic-03","title":"２番目の品川区長期基本計画および品川区総合実施計画（第１次）の策定","agenda":"２番目の品川区長期基本計画および品川区総合実施計画（第１次）の策定","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"その辺についてはどういうふうにとらえているのか、必要ないということで記述していないのか、その辺の考え方を伺っておきたいと思います。","respondent":"久保田行財政改革担当課長","answer":"例えば「未来を創る子育て・教育都市」のところですけれども、４３ページに親育ちサポート事業の充実の中で、父親の子育て参加促進事業といったもの、また父親になる前の中高、大学生子育て体験ワークショップなどの充実をいたしまして。","voiceIndex":49,"id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"そこのところは税収の関係でどういうふうに見ているのかというのは、この一覧表を見たときに非常に気になったんです。その辺の見方という、予想、どういうふうに見ておられるのかを伺っておきたいと思います。","respondent":"久保田行財政改革担当課長、金子企画財政課長","answer":"私のほうからは、１点目の事業費のところのお答えですけれども、私のほうの説明が足りなかったかもしれませんけれども、こちら、３年間の計画事業ですので、実施計画の本体に載っている事業につきましては。事業計画費の税収等々のお尋ねでありますけれども、こちらの実施計画の中にありますとおり、特別区税につきましては平成２１年度から平成２２年度、平成２３年度にかけては減少していくというふうな見込みを立てております。","voiceIndex":51,"id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっと気になって、もう一回、再確認なんですけれども、税制改正のところの今、説明なんですが、税制改正というと具体的にどういう内容の税制改正というふうに見て、今のを説明していただいたのか、その辺を詳しく教えていただきたいと思います。","respondent":"金子企画財政課長","answer":"ご案内のとおり、現在、新経済対策ということで、また税制改正が見込まれているところであります。そういったことについてはこの計画には一切見込めておりませんので、基本的には平成２０年度の改正、それが本年度に影響する部分について見込んでいるです。","voiceIndex":54,"id":"exchange-015"},{"speaker":"林委員","kind":"質問","question":"最後の点、つながるのかな。この総合実施計画のダイジェスト版の第１次の３年間の計画の中で、この数字をばあっと見ていくと、えっと思う欄があるんだけれども、わかる？企画部。わからないでしょう。この第１次の３年間の計画の表にまとめてくれていて、僕らにわかりやすく、こういう予想なんでしょう。これは品川区でやってきた行財政改革という大きい勲章を外すという意味になるんですか。","respondent":"日下部企画部長","answer":"ただし、そうなりますと逆に委託の経費、物品費が上がってまいりますので、これがこういう形で、逆な形ではね返ってくると。そういうことでご理解をいただきたいと思います。","voiceIndex":56,"id":"exchange-016"},{"speaker":"林委員","kind":"質問","question":"全然答えが違う。人件費は上がって、下がる。今言ったような理由もあるだろうしということ。それから、公債費はどういう仕組みで、これ、１割も減るんだよね。去年まで２年ぐらい、公債費、起債をしなかったという自信のあらわれなのか。行財政改革ということを品川区は忘れちゃって、上がるものはしようがないでしょうという、そういうふうにも受け取れるんだけれども、そんなことなんですか。","respondent":"日下部企画部長","answer":"公債費の関係、ちょっとご説明しますと、公債費につきましては、今、この１０カ年の計画の前提といたしましては、平成２１年度予算で城南小学校の学校誘致の取得をいたしました。あれは、要するに区の持ち出しは一切ないという前提で、あれは起債を活用しました。","voiceIndex":58,"id":"exchange-017"},{"speaker":"林委員","kind":"意見","question":"だけれども、じゃ、これはどういうことを説明する？１万２,０００円の定額給付金という名前だっけ、あれ。１万２,０００円。あれの申込書というのかな、来て、送り返すと振り込んでくれるという申込書の１面に、寄附してくださいという欄がある。こんなに余裕があるんだったら、あんな、寄附してくださいという欄をなぜ入れるの。あれをぱっと見たときに、あっ、１万２,０００円が交付されるんだなと。","respondent":"日下部企画部長","answer":"そういう思いが私どもにありますので、今回、定額給付金の実施に当たりまして、区民の皆様方にご寄附をできればお願いしたいというふうに呼びかけましたのは、そういうふうな趣旨もありますので、ぜひともご理解をいただきたいと思います。","voiceIndex":60,"id":"exchange-018"},{"speaker":"林委員","kind":"質問","question":"東京都の日野市で先週まで、同じようなことが書いてあるんです。みんな、あれ、相談してやったんでしょう。自治体がね。幾ら寄附されたと思う？２６０万円。もう少し、僕は、きちんと考えるべきだと思うんだよね。平成２３年なんて、１割予算が減る。これでいくと１,３８３億円から１,２７５億円という数字が並んでいるんだけれども、１割弱の減になっている。そういう考えでいいんですか。","respondent":"日下部企画部長","answer":"全体の年間の予算の総額の関係でまいりますと、確かに平成２３年度、かなり大きく落ち込んでおりますが、実は学校の改築、耐震改修、それから一貫校というのが、平成２２年度ぐらいまでかなり集中をしている面があります。","voiceIndex":62,"id":"exchange-019"},{"speaker":"林委員","kind":"意見","question":"金利の話も出て、それは払うより払わないほうがいいんだろうけれども、いっとき前、区民債というのを覚えています？３億円？５億円？だから、やっぱり寄附というのは税金と同じでしょう。どうぞ一緒にやりましょう、皆さんの将来の、お子さんのためとか、そういうのならわかるけれども。もともと。必要なときは、あなたも今言ったように、必要だから一緒に協働作業してほしい。はっきり言っておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":64,"id":"exchange-020"}]},{"id":"topic-04","title":"３番目の平成２１年度オリンピックムーブメント事業","agenda":"３番目の平成２１年度オリンピックムーブメント事業","exchanges":[{"speaker":"土井委員","kind":"意見","question":"ということは、要するに１,０００万円来ますけれども、これくらいのことをやれば渡しっ切りでもらいますよという金だと。ただし、それはひょっとしたらオーバーするかもしれない。人件費等も含めれば。ひょっとしたら少ないかもしれない。そういうものだと理解をします。今のお話を聞いて。オーバーするほうがどうも濃いように思えてしようがないものだから、聞いているんです。","respondent":"久保田行財政改革担当課長","answer":"オーバーすることもございませんので、予算の９００万円の中でやっていただくというところを予定しています。","voiceIndex":74,"id":"exchange-021"},{"speaker":"南委員","kind":"質問・要望","question":"今の説明は。その辺を確認するのと、違うんだったら違うで、正確に、わかるように説明していただきたいと思うんですけれども、夢フェスタとムーブメント事業は別の事業だと思うのでね、その辺も含めて教えていただきたいと思います。それから、同日、１６日、１７日、２日間、夢フェスタは２日間ですよね。","respondent":"久保田行財政改革担当課長","answer":"夢フェスタとオリンピックムーブメント事業の予算の関係ですけれども、夢フェスタとムーブメント事業の予算は別物です。私が今説明しました９００万円は、オリンピックムーブメント事業を執行するに当たっての経費ですので、夢フェスタの経費はこの中には含まれてございません。","voiceIndex":76,"id":"exchange-022"},{"speaker":"南委員","kind":"質問","question":"そういうところに関して、スポーツ協会が受けとめてやっていくということなんだけれども、そういうことでやるということですけれども、私はリンクするべきじゃないと思うので、その点について改めて区としての見解、認識を伺っておきたいし、オリンピックに対する区民の感情というのかしら、区民の世論、意識というのかな、そういうところは品川区としてはどういうふうに思っているのかなというのと。","respondent":"久保田行財政改革担当課長","answer":"ただ、品川区といたしまして、区長会もそうですけれども、東京都が進めますオリンピックムーブメント事業に協力していこうという姿勢はありますので、今回、こういう事業がありましたらば、私どもとしましては、オリンピック招致も当然のことではありますけれども。","voiceIndex":78,"id":"exchange-023"},{"speaker":"南委員","kind":"意見","question":"だけれども、１,０００万円のオリンピックムーブメント事業として東京都が品川区に補助を出すという、こういうことで使うという、そういうシステム中でやられる事業ということと、それが今、こんなに経済不況の中で、本当にみんな苦労している、いろんな収入が、いろいろなレベルがあるけれども、しかし、圧倒的に厳しい人たちが増えてきている、そういう中で、こういうところにお金を使うのは、私は。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":80,"id":"exchange-024"},{"speaker":"南委員","kind":"質問","question":"自説じゃないですよ。区民の一部の意見ですからね、それは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-025"},{"speaker":"須貝委員","kind":"質問・要望","question":"ただ、ぱっと見た感じでは、どうしてもオリンピックムーブメントのほうにお子さんも、地域の人も、やはりかなり目が行っちゃう。見たいなと、会いたいなということが結構出てくると思うので、その辺、私からの要望なんですが、うまく相乗効果が出るように、やはり双方が盛り上がるように工夫をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-026"},{"speaker":"金野委員","kind":"質問・要望","question":"１点だけ。事業内容で教えていただきたいところが、４番目の家族を結ぶセミナーの開催とあるんですが、(1)、(2)、(3)の事業内容は何となくわかりますし、ああ、こういうものかなとイメージするんですが、４番目のこのセミナーに関しては、いわゆる講師の方とかが開催の、そういうのに当たっての内容、どんな感じでやるのか中身を、決まっていれば教えていただきたいと思います。","respondent":"久保田行財政改革担当課長","answer":"こちらについてなんですけれども、これという形でまだがちっと決まっているわけではございませんけれども、今調整をしていますけれども、オリンピックを感じてもらうといったところのコンセプトで、スポーツゲームとかでコミュニケーション能力をアップするような。","voiceIndex":85,"id":"exchange-027"},{"speaker":"金野委員","kind":"質問・要望","question":"オリンピックを感じるということで、トレーナーの方たちにトレーナーコーナーを、スポーツゲーム、また区の歯科健診みたいなものもするというような、今、ご説明で、何となくわかるんですが、(1)、(2)、(3)のアスリートたちに触れ合う、また展示コーナーを見るということのほかに、この(4)というのが何となくうまく結びつくような、結びつかないような、そんなイメージをしていましたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-028"},{"speaker":"林委員","kind":"質問","question":"この１６日というのは何かの日なの？僕の知っている範囲では、この日にハンマー投げの室伏さんが品川区に来る。この日なんです。この日って、オリンピックと関係のある、きょうは、たまたまオリンピックの調査がきょうから始まったというふうに聞いているんだけれども、何かと関係があるんでしょうか。この５月１６日。","respondent":"久保田行財政改革担当課長","answer":"すみません、５月１６日については特にオリンピックと何か関係のある日というふうには伺ってございません。私どもとしては、夢フェスタを５月１６日、１７日にありますので、オリンピックイベントもそこにあわせて開催ということで、１６日の開催になったというところが経緯です。","voiceIndex":88,"id":"exchange-029"},{"speaker":"林委員","kind":"質問","question":"とすると、武蔵小山の駅前、西小山は１７日と聞いているんだけれども、お客さんが分散されちゃわない？片方は八潮とか品川のほうだから、武蔵小山とは遠く離れている場所であるけれども、これは、非常に至近距離にあるところでこういうことを計画されると、武蔵小山の駅前の祭典とかイベントを妨害、妨害とまではいかないけれども、同じような時間帯にされるとという心配はないですか。","respondent":"久保田行財政改革担当課長","answer":"私どものほうとしては、区の同時開催事業として荏原文化センターで２日間にわたって文化フェスティバルとか、そういったものやるといった中でオリンピックムーブメントもやっていくというのが一つでございまして、私どもは庁内で連絡検討会を立てまして。","voiceIndex":90,"id":"exchange-030"},{"speaker":"林委員","kind":"質問","question":"そんなに気合いが入っているの？夢フェスタに。だったら循環バスか何か出すぐらいの心意気で、寄附が集まったのをバス代にしたらいかがですか。でも、武蔵小山のイベントにお金を使うのは、そんなにぐずぐず言う人はいないと思うんで、今からでもバスを２、３台借りるにはそんなに時間かからないんだから、検討してみてください。お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-031"}]},{"id":"topic-05","title":"４番目の男女共同参画のための品川区行動計画（第４次）素案の策定","agenda":"４番目の男女共同参画のための品川区行動計画（第４次）素案の策定","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"この間、行動計画が何回か策定されて、今回第４次計画だという説明を受けて、資料もそういうふうに構成されているんですけれども、今までの行動計画の上に立って、今日的な、２００９年からの、これからの行動計画があると理解するんですけれども、どういうふうに１次から２次、３次となっていく上で、ここにかいつまんで項目は紹介されていますけれども。","respondent":"中山人権啓発課長","answer":"２点目のＤＶについてなんですが、ＤＶの支援というのはすごく難しいと思います。確かに経済的な、ＤＶの相談がある中でも、就労されている方というのが半分ぐらい。残りの方は就労されていない方。いわゆる専業主婦でＤＶを受けているという感じの方ですね。","voiceIndex":99,"id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"でも、そのわりには、品川区だけでやれる部分でもないので、項目が掲げられていても、叙述されている中身は非常に、品川区の範囲のことで、字数の上で評価するわけじゃないですけれども、少ないということはどうしても否めないんですけれども、品川区として最大限、所管するところが人権啓発課と経理課と４つの課にまたがっているんですけれども。","respondent":"中山人権啓発課長","answer":"こちら、商業観光化ですとか、ものづくり・経営支援課も一緒になって対応していただいているところですが、まず、ここの1)の「ワーク・ライフ・バランス支援事業の促進」というところの一番上のワーク・ライフ・バランスコンサルタント費用等の助成というのは。","voiceIndex":101,"id":"exchange-033"},{"speaker":"南委員","kind":"確認","question":"イメージとして、あっ、こういうふうになっているんだとか、このぐらいの企業がそういうふうにかかわって、頑張ってやってくださっているんだみたいな、そういう確認をしたいなと思ったので、そんな質問をしたんですけれども、どんななんでしょうか。","respondent":"中山人権啓発課長","answer":"ただ、うちのこの事業を進めるに当たりましては、当然、各課、連携しまして、６２ページに策定に至る経過、策定体制ということで載せしていますが、先ほどの行動計画の推進会議の答申はもとより、男女共同参画推進行政連絡会というものを設けてございまして。","voiceIndex":103,"id":"exchange-034"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、これからの課題として、そこもぜひ積極的にリサーチしていただいて、品川区の、そういう姿勢と状況になっているんだという中身にしていただきたいということをあえてお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-035"},{"speaker":"林委員","kind":"意見","question":"大変すばらしい。多分、東商なんかも区と協力しながら推進していきたいとおっしゃっている。ところで、品川区役所の中で、この件について問題はないんですよね。広報のほうがいいか？だって、区役所以外のところの、例えば事業家の集まりの東商だとか、そういうところで経営者の人たちと品川でこういう第４次を始めたいと、おそらく相談はされている。学校も含め、幼稚園も含め、保育園も含め。","respondent":"榎本人事課長","answer":"学校は私も全部聞いていないんですけれども、学校につきましても公務員としての賃金体系は平等であるということと、あとは配置につきましてもそれぞれ配慮した形でやっていますけれども、特に育児休業のところでいきますと、ほとんど、１００％近い取得ということで。","voiceIndex":106,"id":"exchange-036"},{"speaker":"林委員","kind":"質問・要望","question":"第３次のときも少しずつという話は出ていた。男性の育児については。ひとり親。特に女性が自立して、１人で子どもを生み、育てられる。だから男は弱いんですよ。男はそんなもの、何にもできない。でも、ひとり親の自立支援というのは、ぜひ、できる範囲、品川区で取り組んでいっていただきたいと思いますけれども、非常に財政的にも難しいところがあると思うんだけれども、覚悟のほどを決めていただけますか。","respondent":"市岡総務部長","answer":"今のご趣旨、実はこの行動計画のいろいろご論議をいただいた中に、男性の方もお二人入っていらっしゃいまして、実は私も出席したときにちょうど、海外調査のときの見聞をご紹介したことがありまして、林委員と同様のご意見をいただきましたので、実現に向けては、なかなか。","voiceIndex":108,"id":"exchange-037"},{"speaker":"須貝委員","kind":"質問","question":"知り合い、知人、友人に相談するということになって、もっと専門家、品川区の方にも大勢いらっしゃるし、多岐にわたって、またほんとうに有識者、そういうことに、ケアに対して知識等を持っている方もたくさんいらっしゃるんですが、そこまでたどり着くに当たって相当時間がかかったり、連絡できなかったりということがあるんですが、区の今の体制として、今回、ＤＶがあって困ったなというときに。","respondent":"中山人権啓発課長","answer":"こちらには男女共同参画センターの案内と、それから東京都のウィメンズプラザが時間帯をもっと幅広く相談をやっておりますので、こういったところも紹介をしておりまして、おトイレとかに置いてあるので、何かの機会にちょっと目に触れて。","voiceIndex":111,"id":"exchange-038"},{"speaker":"須貝委員","kind":"質問・要望","question":"本当に身近に相談できる窓口、または２４時間とかは無理だと思うんですが、私は、留守番電話でもいいから、そこに電話したらこちらからまた翌日折り返し電話をしますという形でもいいから、そういうふうにすぐ救済を求められる、相談できるような、連絡できるような場所というとのが身近にあると、もっと多くの方が救われるんじゃないかなとちょっと思いましたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-039"}]},{"id":"topic-06","title":"５番目の総合区民会館第４期舞台照明設備改修工事請負契約","agenda":"５番目の総合区民会館第４期舞台照明設備改修工事請負契約","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"当然、これ、９月１１日から工期ということで、何日間か、何週間かは閉館になるわけですよね。したがって、今、大舞台の(3)のところの工事の状況によって、若干日にち的に変更はあるかもしれませんけれども、そういう周知というのはされると思うんですけれども、どのぐらいの工期というんですか、ちょっと、私、今の説明になかったと思うので、改めて工事期間、それを教えていただきたいと思います。","respondent":"阿部経理課長","answer":"これにつきましては、既にきゅりあんの予約システムの中でＰＲしているということです。あわせまして、今後、舞台機構の改修も行われますけれども、それも、今申し上げた期間、７月２７日から９月１１日までの間は閉館をして、工事をするという予定です。","voiceIndex":119,"id":"exchange-040"},{"speaker":"林委員","kind":"質問","question":"両方とも大明でしょう。仕事の質からいって、どうせこの会社がずっとやるんだろうというようなことが見えているのかな。周りの企業体も、まあ、こんなもんかという、別に譲ったわけではないだろうけれども、結果的に３社が辞退という事態が起きると、えっ、えっ、えっというような感じになっちゃうんだけれども、これからまだいろんな仕事が出てくると思うんだけれども、こういう状況は続くんですか。","respondent":"阿部経理課長","answer":"ですから、私どもとしては、こういう事態が続くということになれば非常に問題はあろうかとは思われますけれども、ただ、エントリーした会社が３社から４社を見まして、それの積算した結果としてそういう形になったというふうには聞いてありますし。","voiceIndex":128,"id":"exchange-041"}]},{"id":"topic-07","title":"８番目の第６投票区投票所の変更","agenda":"８番目の第６投票区投票所の変更","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"浅間台小学校、確かめていないんですけれども、記憶の範囲では、校門から入ると、校庭にずっと上がると、ちょっと坂になっているような気がするんですけれども、かなりの勾配のね。だから、投票に行かれる際には、もちろん環境整備はするんだろうと思うんですけれども、その辺と、あと、段差も結構あったと思うので、その辺はどういうふうに考えているかというのを教えていただきたい。","respondent":"早津選挙管理委員会事務局長","answer":"浅間台小学校の入り口は確かにスロープがあります。選挙当日には、そこに誘導をかねた職員を配置いたしまして、車いす等のサポートも行いたいと考えています。そのほか、体育館までの段差等については、段差解消にスロープ等を設置する予定です。","voiceIndex":135,"id":"exchange-042"},{"speaker":"林委員","kind":"質問","question":"無知で申しわけないと思うんだけれども、この浅間台と養学校というか、養護学校の決まり事として、浅間台にするならずっと浅間台でやればいいのになと思うんだけれども、浅間台でやっちゃいけない理由があるんですか。ゼームス坂のあの養護学校じゃないと、投票所には当てはらまないんだというような理由があるんですか。","respondent":"早津選挙管理委員会事務局長","answer":"これは特にございません。地形上、第６投票区の中のセンターに近いのがこの大塚ろう学校のほうで、したがいまして、第６区の有権者の利便を全体的に考えたときに、大塚ろう学校のほうがすぐれていると、こういう関係で選んでいるものです。","voiceIndex":137,"id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1816#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":63365,"voices":144}},{"id":"h21-20090415-14","meetingId":"h21-cm04","date":"2009年4月15日","dateIso":"2009-04-15","committee":"行財政改革特別委員会","time":"午後１時０２分～午後２時５３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"公有財産の有効活用に関すること","agenda":"公有財産の有効活用に関すること","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"具体的に言うと、無償でいただくのか、それとも貸与という形で借りるのか、そこら辺をちょっと確認しておきたいと思いまして、どういった感じになるんでしょうか。","respondent":"久保田行財政改革担当課長","answer":"大崎第二地域センター移転に当たりましては、再開発組合のほうから無償で譲渡されるというふうに聞いております。そして、その後の扱いですけれども、無償譲渡の後、行政財産ということで、地域センターとして活用して扱っていくと聞いております。","voiceIndex":10,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"わかりました。では、床をいただくということなんですね。じゃあ、その残りの跡地をどうするかということなんですけれども、今後、調査・研究を進めていくということでしたけれども、専門家の調査ということもありましたが、どういった専門家による、どういう調査をしていくつもりなのかということをお伺いしたいのと、あと、現時点で地域の方々の意見などは聴取したりとかしているのか、していないのか。","respondent":"久保田行財政改革担当課長","answer":"１点目です。調査の方法ですけれども、先ほどもご説明いたしましたように、位置指定道路というところが周辺にありますので、この辺の権利関係等もまずいろいろと調べていかなければならないかなと考えています。","voiceIndex":12,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"それで、そういった点で、この大崎第二地域センターの跡地をどう活用していくかという、調査をされるというお話は伺いましたけれども、調査した上でどういうものがつくれるかということをデータとしてそろえた上で、じゃあ、いよいよ地域の皆さんの意見をどうくんでいくかというところで、区として気をつけていかなくてはいけないこととかがあるのではないかと思うんですけれども、そこら辺のお考え。","respondent":"久保田行財政改革担当課長","answer":"私どもは、先ほどご説明しましたように、今後、この跡施設の活用について調査・研究をしていくといったところです。","voiceIndex":14,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういった点で計画段階、パブコメに出す前の区の素案をつくる上での意見聴取という点では、どのように区民の声を聞くようなお考えがおありでしょうか。","respondent":"久保田行財政改革担当課長","answer":"計画の前の段階でですけれども、私どもはこうした形で、本日、行財政改革特別委員会のほうにもご報告をしています。区民の方の代表です議員の方のご意見も伺いながら、幅広く区民の方の意見にも耳を傾けていかなければならないのかなと考えてはあります。","voiceIndex":16,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっとパブコメという制度に関して、今、お話があったんですが、基本的に一定の方向性がかたまってから進むものです、みたいなお話のニュアンスが聞こえたので、ちょっとそれでは、やはりこれまでの経緯を見ても不十分なのではないかなと考えています。そこら辺に関してはいろいろなあらゆる手で聴取するよう努めていただきたいなと私は思いますので、要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-005"},{"speaker":"井上委員","kind":"質問","question":"先ほど町会の方たちから、地域センターということで、地元に密着していた施設であるがために町会の専用にという声は当然だと思うんですけれども、やはり区の公有財産として、区民全体の財産であるという捉え方をした場合に、今までの流れで一番最初に町会のほうに情報が行って、ほとんど決まった中で区全体にパブリックコメントをかけるというような。","respondent":"久保田行財政改革担当課長","answer":"公有財産が発生した、そういう跡地が発生した場合の対応ですけれども、まずは私どものほうとしましては、こういった行革委員会なり、所管の委員会のほうに、今、昨年の６月のときもそうでしたけれども。","voiceIndex":19,"id":"exchange-006"},{"speaker":"井上委員","kind":"質問・要望","question":"区としての、もちろん財政も含めて長期的な、専門家である行政がその部分から取捨選択するということが当然だと思いますので、区民の声にあっちへ行ったりこっちへ行ったりというのではない、政策判断というのは当然あると思うので、そういう、区民から１回、ほんとうに区全体としてどういうところが足りないんだろうという、個々に意見が出ているのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-007"},{"speaker":"須藤委員","kind":"質問・要望","question":"我々なんかが見ると、もうこの地域だと貸事務所ではないけれども、そういう集会室的なものぐらいかなと思って、これが高齢者の施設になるんだというとなかなか難しいかなとかいう思いが出てしまうので、専門家の人にいろいろ判断をしてもらって、どういったことが可能だということを見せていただいて、また、それから皆さん方に、議会にでもこういう状況だというのを諮ってもらえれば。","respondent":"久保田行財政改革担当課長","answer":"近隣の方、生活している方もありますので、そういったところの中でどういった建物の活用が可能かということも踏まえながら、そうしたところの条件を整理した上で、できるだけ委員ご指摘のように、地域の方に限定するということではなく幅広く意見を聞きながら。","voiceIndex":22,"id":"exchange-008"},{"speaker":"阿部委員","kind":"質問","question":"２点お伺いします。この建物自体は、耐震の関係等々を含めて、このままであればどのくらい使えるものなのかというのを、もしかしたら前回伺ったかもしれませんけれども、もう１回教えてください。公有地がいつまでもこのような形であるというのは決して望ましい形ではないと思いますので、その可能性についてどうお考えなのか、教えてください。","respondent":"久保田行財政改革担当課長","answer":"耐震のお話ですけれども、先ほどもご説明いたしましたように、ここの建物が鉄骨造ということがありますので、また建築年が昭和４７年です。","voiceIndex":24,"id":"exchange-009"},{"speaker":"阿部委員","kind":"確認","question":"今のご答弁の内容のちょっと確認なんですけれども、これからの専門家の方々との１年間の調査の中では、シルバーセンターとあわせた活用についても検討の俎上に上るということですね。近隣の方との協議というのは、単に近隣だから協議するということではなくて、それもまた土地や権利関係も含めて一緒にやっていくというようなことも含めた検討になるのか、そこも教えてください。","respondent":"久保田行財政改革担当課長","answer":"そうした中で、どういった活用ができるかといったことを調査・研究しまして、そうした上で、近隣の方とのそういった協議とかが必要ということであれば、次のステップとしてそういうのも可能性としてはあるのではないかなという意味で、先ほどお答えさせていただいたところです。","voiceIndex":26,"id":"exchange-010"},{"speaker":"浅野委員","kind":"確認","question":"ちょっとそこら辺、確認のために教えていただければと思います。","respondent":"久保田行財政改革担当課長","answer":"集会室の数ですけれども、３室というところでは変更はございません。ただ、広さ的には一番広い部屋が約１２０m2になるです。２番目の広さのところが４２m2、次が３８m2程度になると伺っておりますので、そうした意味では現在よりも広さ的には広くなると考えております。","voiceIndex":28,"id":"exchange-011"},{"speaker":"浅野委員","kind":"質問","question":"広くなるということで、これは今まで使われていた方にとりましてはいい方向かなと思うんですけれども、今の利用の頻度というものは満杯なのか、あふれているのか、それとも少ないのかということがもしわかれば、その点も教えていただければと思います。","respondent":"久保田行財政改革担当課長","answer":"夜間につきましては５９.７％ということで、合計で５０.６％です。これは、今、平成１９年度ですけれども、平成２０年度は現在集計をしているところでございまして、２月末現在で全体としまして、時間帯の合計としましては５６.６％というふうになっております。","voiceIndex":30,"id":"exchange-012"},{"speaker":"浅野委員","kind":"質問","question":"平成２１年度は、今、専門家による調査とかいうような形で進めるですけれども、そこら辺の、ちょっと長期的になるかもしれませんけれども、目安というものはどのくらいに置かれているのか、お伺いします。","respondent":"久保田行財政改革担当課長","answer":"それで、もし早ければ、そういった形で容易な形での活用ということであれば、平成２２年度から工事とかそういったものはできるのかなと考えていますけれども、ただ、今、私どものほうでも考えておりますのは。","voiceIndex":32,"id":"exchange-013"},{"speaker":"浅野委員","kind":"質問","question":"先ほども委員から、ある意味ではもっと大規模な形でやったらという意見もあると思いますけれども、やはりしっかりとこの平成２１年度は調査・研究をしながら、また専門家の意見も伺いながら、また次なるステップに踏み出せるような形でやっていっていただければと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-014"},{"speaker":"菊地委員","kind":"質問","question":"ここで１,０００世帯からの新たな住民が生まれてきて、これからさらに南地区というふうになりますよね。ここでの需要も、多分、新しい地域センターに移ると生まれてくるのかと思うんです。その辺で、需要として今後どうなのかというところがちょっと。実際にそういう調査をされて今度の新しいところに移ろうとしているのか、その辺がよくわからないので、ちょっとそこを教えていただけますか。","respondent":"久保田行財政改革担当課長","answer":"大崎第二地域センターということではなくて、地域センターとか本庁舎の手続が必要になってくるといったところですので、大崎第二地域センターというものも含めて検討をする必要があるのかなとは考えているところです。","voiceIndex":35,"id":"exchange-015"},{"speaker":"菊地委員","kind":"質問","question":"だけど今のお話だと３室。これまでのセンターの３室と変わりがないと。この辺はやはりきっちり調査をすべき部分ではないかなと思うんです。活用について、専門家を入れて云々という話がありましたけれども、やはりセンターそのものの需要に対する調査というのを確実にすべきではないかなと思いますけれども、どうでしょうか。","respondent":"久保田行財政改革担当課長","answer":"この地域センター、新しいところに移るものはこの中地区の中でも地域貢献施設といったところに移りますので、今回のこの再開発に当たりまして、そういった意味での検討はしてきているところです。","voiceIndex":37,"id":"exchange-016"},{"speaker":"菊地委員","kind":"質問・要望","question":"単純にマンションだから集会室がありますよと、そこだけで活用できる話ではないですよね。だから、やはり区として、もし開発組合のところできっちり調査をしたんだよというのであれば、そうした資料も含めて私はやはり議会に示していただきたいなと思います。意見だけ、ちょっと言っておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-017"}]},{"id":"topic-02","title":"の特定事件調査のまとめ","agenda":"の特定事件調査のまとめ","exchanges":[{"speaker":"須藤委員","kind":"意見","question":"内容的にはこういう記載で結構だと思うんですけれども、ただ、文言の表現の仕方が、最初の「記」の前が「十分留意していただくよう」、それから「経緯を十分踏まえた」、２番目も「十分な対策」、その次３番も「経緯を十分踏まえて」、十分、十分と十分が何個も出てきてしまうので、ちょっと読んでいてもう少しまとめられないのかなと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":44,"id":"exchange-018"},{"speaker":"阿部委員","kind":"質問","question":"５番のところなんですけれども、最後いろいろとお伺いして検討されたいということなんですが、これは委員会の中でも意見として多分少し出たと思うんですけれども、この立地環境とか行政需要のほかに、全区的な公共施設の配置のバランスというようなことも少し出ていたかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-019"},{"speaker":"井上委員","kind":"質問・要望","question":"今のところにちょっと関連するかもしれないんですが、この５番目の「計画の策定過程についても検討されたい」というところの含んでいる内容というのを、少しこの部分がちょっと不明な部分なので、どういうふうなものを含めてこういう表現になっているのかということを確認をさせていただければなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-020"},{"speaker":"本多副委員長","kind":"質問","question":"前回の委員会で、各会派ごとに追加があれば意見を出してくださいということで、少数の会派から意見が出てきたものも含め、このようにまとめさせていただきまして、それ以前でも委員会のこの１年討議をしてきた中で、例えばパブリックコメントのことを取り上げても、私は区のやっているパブリックコメントは十分やっていると思うんですが、やったことに対して。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-021"},{"speaker":"井上委員","kind":"質問・要望","question":"それから３番のところで、これは言っていることもそのとおりということなんですが、この学校避難所については、今まで学校避難所であったものがもう更地になってしまったり、そういう部分では早急にとか、体制を整えるよう周知するとか、そういった明確な言葉がここには入るべきではないかなというふうに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5858#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":18782,"voices":58}},{"id":"h21-20090416-16","meetingId":"h21-cm04","date":"2009年4月16日","dateIso":"2009-04-16","committee":"街づくり特別委員会","time":"午後１時０２分～午後３時３６分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"品川区震災復興マニュアル","agenda":"品川区震災復興マニュアル","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"概要の説明があったので、いろいろ基本的な考え方といいますか、少し具体的にどんなふうに考えているのかご説明いただきたいと思うんですけれども、７ページのところに、震災復興計画の策定について触れられておりまして、地震発生後２週間以内に基本方針、その方針に基づいて復興計画とありますけれども、ここに「４カ月を目途に区報やホームページなどで原案を示し。","respondent":"中山防災課長","answer":"ですから、実際に被害が起きたときには復興対策本部を設置するわけですけれども、それに間に合うような形で平常時に事前にそういった準備として、下書きのような、下書きのようなというのはおかしいですけれども、そういったものをつくって対応していく必要があると思います。","voiceIndex":18,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"もちろん当時は被災者自身もまだ路頭に迷っている状態での都市計画決定で、神戸市だけでもたくさんの反対の声が沸騰したと。当然、通常の形でも問題はあると思っていますけれども、通常ではない状態がつくられるわけですから、ここで言っている住民参加のプロセスというのはどういうふうに構築していく必要があるのか、その考え方を教えていただけますか。","respondent":"中山防災課長","answer":"それで、おおむね６カ月以内と申しましても、先ほど申し上げましたように、事前に想定をしておかないと、６カ月以内に基本計画の策定は正直なところ難しいと考えています。","voiceIndex":20,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"今の説明ですと、今一つ、プロセスは大事だけれども、ただ、こういう場合に具体的にどうするのかというふうに事前に整理しておかないと、起きてからでは、逆に言えば、職員も含めて被災者ですから、その辺をしっかり押さえないといけないのではないかなと思うんですけれども、その点を伺わせていただきたい。金融機関も含めてみんな動かなくなっているわけですから。","respondent":"中山防災課長","answer":"２つ目の質問のほうからお答えしますけれども、要は、半壊・半焼の住宅の居住者は、実際にはどこにいるのかということです。","voiceIndex":22,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"地域コミュニティが大切だという指摘は載っていましたけれども、身近なところで、住宅の近くに住んで復興プロセスに参加することが重要だという指摘がありますけれども、それであれば、例えば自分の住宅の敷地内での仮設住宅の建設、いろいろと地震の経験で一部進んでいる話も伺いますけれども、場所が足りないという話であれば。","respondent":"岩田防災まちづくり事業部長、中山防災課長、片田建築課長","answer":"１つの形とすれば、熟度の高い地域の方々が、いざこのまちが壊滅したら、こういう道路をきちっと復元をして。仮設住宅の場所と軒数ですが、仮設住宅の担当は東京都になってあります。東京都が仮設住宅に関しては検討しています。その際に、建物の被害状況を想定、把握しまして、どの程度の仮設住宅の戸数が必要なのだろうかと。何世帯必要なのか、何軒必要なのか、そういう意味で、まだつかんでおりませんということです。予想はできかねるです。","voiceIndex":24,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういうときに、こういうところで地震が起きた後の実際の様子が浮かんできたときに、じゃあ、やっぱり自分の家も住宅の耐震化を進めてみる、こういう機運にもつながってくると私は思っているので、ぜひ補って進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-005"},{"speaker":"山路委員","kind":"意見","question":"この概要版はやっぱり全区民が読んでほしいし、知識を得てもらいたいんですけれども、どこら辺までどういう形で配布されていくかということと、このプロセスをある程度区民に周知をされるのが大きな目的だと思うんですが、それにはかなりの時間がかかると思うんです。","respondent":"中山防災課長","answer":"これは、３,０００部しかつくってございません。したがいまして、私どもで考えていたのは、主要な施設に何冊か置いてお読みいただくというようなことを考えておりましたけれども、全区民に配布することにつきましては、今後、検討課題とさせていただきたいと思います。","voiceIndex":30,"id":"exchange-006"},{"speaker":"南委員","kind":"意見","question":"特に先ほどの部長の答弁では、震災復興計画ができている地域から優先的にやっていくみたいな、そんな話も一部あったので、私は改めてそういうものを、そういうふうに国が構想しているのであれば、やっぱり自分のまちの状況とみんなのコミュニティをどういうふうにつくっていくかも含めて、まちをどうやって挙げて復興に当たっていくかというところは、本当にそういう計画があればあるだけに。","respondent":"中山防災課長","answer":"早急に周知の方法については検討してまいりますので、いましばらくお待ちいただきたいと思います。","voiceIndex":32,"id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、これからさらにこれを区民に提供し、３,０００部だから、そういう意味では、やっぱり私は十分ではない数だというふうに思うので、増刷も含めて、区民すべてに渡せるぐらいの気持ちで取り組んで、それぞれの地域での議論を巻き起こす、そういうことを率先してやっていただきたいということをちょっと改めて申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"それは庁舎内の中であれば、ある程度、庁内の中でのコミュニケーションがとれていると思うので、自分が来られなかったら、ほかの課の職員が協働していくとかができると思うんですが、関係団体というか、社会福祉協議会となると、出向の方はいらっしゃるにせよ、そこまで密な関係は今のところどうなんだろうというところがあって。","respondent":"岩田防災まちづくり事業部長","answer":"合理主義のアメリカですと、日本と同じように地震が非常に多い西海岸なんかでは、庁舎にレベル０からレベル９までの対応マニュアルが全部しまってありまして、実際に起きた地震の規模によって、例えばレベル４だと市長が発令すれば、レベル４で全部動くような。","voiceIndex":35,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、そこの部分の人たちをある程度利用ではないですけれども、助けていただきながら、初動体制も区の庁舎の中で足りないというのであれば、町会の方たち、自治会の人たちもとりあえずそこの部分の連絡体制をとってもらうとか、そういうところに踏み込んでいただいたほうが、多分ここが、庁舎が動かなければ全体が動かないというのではなくて。","respondent":"岩田防災まちづくり事業部長","answer":"あるいは、一般の方に対しては、もう少しやはりこれよりもリーフレット程度のものでわかりやすいもの、こういったものが必要だと思いますので、これは防災課長のほうで十分検討します。","voiceIndex":37,"id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6384#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":25075,"voices":46}},{"id":"h21-20090511-6","meetingId":"h21-cm05","date":"2009年5月11日","dateIso":"2009-05-11","committee":"区民委員会","time":"午後１時０２分～午後２時２５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の定額給付金の進捗状況","agenda":"の定額給付金の進捗状況","exchanges":[{"speaker":"稲川委員","kind":"質問","question":"そのトラブルをどうやって回避したのか、それを教えてもらいたいです。","respondent":"中山定額給付金担当課長","answer":"これは予算特別委員会でもいろいろとご報告し、ご審議いただいたわけですが、特に、当初はなかなか給付そのものが、法案が出てきても、実際、実務的なスキームというのでしょうか、その辺が少し実務的にだんだん波状に国から指示が出てきたということで、ある意味では。","voiceIndex":5,"id":"exchange-001"},{"speaker":"渡部委員","kind":"確認","question":"例えば、２月１日に横浜に住んでいました。その確認が１つ。あれ、まだなのかしら、申請を出したんだけれどもまだだわ、なんていう方がいる中で、コールセンターの問い合わせが１万５,０００件ということなんですけれども、まだ入ってこないのかしらというような問い合わせが実際にどれぐらいあったのか、その辺を質問。ちょっとまとめて幾つか言ってしまったんですが、お願いします。","respondent":"中山定額給付金担当課長","answer":"これが２月１日基準の若干の例外で、これも全部国からこういう取り扱い基準が出てきたです。それから、申請の７３％の見込みというのは、確かに可能な限り１００％お届けしたいという意味で事務はやっておりますというご説明は予算特別委員会でもしたところです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"渡部委員","kind":"質問","question":"それで、今、７３％の申請があって、残りがまだ９月まで時間があるわけですが、例えば、９月の間近になったときに、今、ホームページですとか、いろいろなところで申請書はお届きですかというようなアナウンスをかけられているのを見ているんですけれども、郵便を信じないわけではないんですけれども、例えば何かでどこかの輸送上の紛失とか、これもなきにしもあらずという部分がありまして、例えば。","respondent":"中山定額給付金担当課長","answer":"基本的にはそういう広報と合わせて、例えば、夏ぐらい過ぎてまだ出てきていないという場合に、その辺の捕捉をするような通知を、あまり多く今の段階でやっても逆の混乱もあるので、ある程度時期を絞って今のようなまだの方についての確認は何らかの形で。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"大きなトラブルはないということでご報告があったんですけれども、全国でも問題になっています詐欺的な、振り込め詐欺というか、そういう定額給付金で詐欺みたいなということはないのかということと、あと、現金給付ということで６月中旬からということなんですが、こちらに絡んでちょっと、現金を扱うということなので、何かちょっと恐れもあると思うので。","respondent":"中山定額給付金担当課長","answer":"したがって、通知をお送りしたご本人の意思確認、当然、代理の場合に委任状も含めて本人確認資料も必要書類として予定しておりますけれども、例えば、代理の方が受け取る場合、その代理の方の証明になるもの、そういうものもお出しいただこうかというふうに。","voiceIndex":11,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"関連して、同時に経済対策ということで、区内の経済も活性化するという意味で、プレミアム商品券ですとか、あるいは地域振興基金などの案内も送ったと思うんですが、そちらのほうの状況もどうなっているかということをちょっとお伺いしたいんですけれども。","respondent":"中山定額給付金担当課長、諸岡商業・観光課長、秋山協働・国際担当課長","answer":"事業の目的とそれに伴う成果というようなご質問がありましたけれども、基本的にはご案内のとおり、国が生活支援。主に郵便局が開局している平日が中心になりますが、先週金曜日、８日の販売状況ですけれども、郵便局と。平成２１年度になりましてから、地域振興基金の寄附の合計が、現在のところ、１３万３,８４４円という状況です。","voiceIndex":13,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"そういった点で、区として追加の根本的な営業と暮らしを支える対策がどうしてもこれだけではなくて、あわせて必要になってくると思うんですが、その点に関しての区の決意といいますか、お考えをお伺いしたいと思います。","respondent":"宮地地域振興事業部長","answer":"ご承知のとおり、実際には生活の支援、あるいは経済対策も十分１月１９日の臨時議会の中で、緊急経済対策の中でやっているわけですけれども、この定額給付金につきましては、３月に申請書を出し、今、バックしてきているところで、始まりまして２カ月という中で。","voiceIndex":17,"id":"exchange-006"},{"speaker":"安藤委員","kind":"意見","question":"これだけではなくてということなので、ぜひお願いしたいんですが、やっぱり将来不安が残っている状況ですと、せっかくもらった給付金も貯金せざるを得ない状況ですとか、あるいは将来の医療費のためにとっておかなくてはいけないということになることは当然だと思うので、やっぱり福祉といいますか、社会保障を充実させるという点でやるですとか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":19,"id":"exchange-007"},{"speaker":"若林委員","kind":"質問・要望","question":"何点か。それから、受け取って区に申請を出す場合に、たしか受け取りませんというような表記の欄があったと思うんですけれども、そこら辺の数があるのかないのか、わかれば教えていただきたいと思います。それから、ＤＶ関係、ここら辺、ちょっと他区の報道はちらほら聞くんですが、ちょっとその辺、品川の今の状況、取り組みといいますか、どういうふうに対応されているのか。","respondent":"中山定額給付金担当課長","answer":"それで、じゃあ、自治体として被害者の生活支援の給付については、現在、子ども未来事業部の所管の中で給付事業について対象を決めていく考えだということを検討しているところでございまして、これについては厚生委員会のほうで報告されているというふうに伺っているところです。","voiceIndex":20,"id":"exchange-008"},{"speaker":"若林委員","kind":"質問","question":"相談窓口のほうですけれども、そうすると、事務の終了というと、９月１６日まで。この間にあのフロアを使ってさまざまなイベント、行事が予定されて、環境情報活動センターの部分も含めて、そこら辺はどうなるんでしょうか。","respondent":"中山定額給付金担当課長","answer":"今のような申請がかなり、ある意味で落ち着いてきているというか、そういう状況ですと、ある意味では、イベントの状況にもよりますけれども、あそこのフロアを分けて、競合してやることも可能かというふうに思っておりますので、これは基本的にはあの一角については。","voiceIndex":22,"id":"exchange-009"},{"speaker":"若林委員","kind":"質問・要望","question":"ご答弁も既にありますけれども、着実にしっかり進めていただきたいと思っています。前の委員からばらまき批判がまた出ました。当然この定額給付金というのは、生活支援、経済対策、これの２点を重点的にやっていこうと。それを今、この７３％の方が実際に受けている中で、逆にそういう区民の方たちに対して、これはばらまきですよ、今さら辞退してと言えるのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"区民の率直な思いを私は、そう思っている方もいらっしゃるということを、この委員会の場で紹介したというか、そういう思いで質問いたしました。もう１つ別な質問なんですけれども、いいですか。というのは、やっぱり今のこれまでの大企業の利益最優先の中で規制緩和もされて使い捨て労働が報じられてきたわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"住民登録がない方は、改めて給付期間中に登録すれば受け取れるということなんですけれども、はるか遠くに住民票がある方というのは、その自治体に申請をするということになるということなんですか。","respondent":"中山定額給付金担当課長","answer":"そういうことです。地方に住民登録があれば、そこで受け取る形になります。","voiceIndex":29,"id":"exchange-012"},{"speaker":"宮崎副委員長","kind":"質問","question":"２点ほどなんですけれども、今の点に関してなんですけれども、そうすると、９月１６日までに住民票をとれば資格が発生するということなんですけれども、それであれば、当初からホームレス等の一番困っている人がもらえないのではないかとかと、いろいろマスコミなんかでも指摘されてきたところですけれども、そうすると、この９月１６日まで可能性があるということになると、要するに。","respondent":"中山定額給付金担当課長","answer":"ですから、これは何らかの理由があるかもしれませんけれども、住民登録が、これは居住ですから、居住の本拠としてそれなりに本拠が形成される、お住まいが持たれるという前提になりますけれども、その段階で対象になってくるということをご説明したわけです。","voiceIndex":31,"id":"exchange-013"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"後段のほうなんですけれども、要するに、区のほうから発送した。ちょっとそこを伺いたいのがもう１つ。もう１つは、申請率が今、７３％だったということなんですけれども、先ほど、いわゆるレアケース、困難ケース等をこれから調べていくんだということで、意思の確認をしていく、そういう必要性は区のほうで認識を持ってもらえるようなんですけれども、具体的に申請期限は９月１６日ですよね。","respondent":"中山定額給付金担当課長","answer":"ホームレスの対応については、これもご質問があったとおり、これは別の制度の検討ですので、ちょっとここではお答えする場面ではございませんけれども、基本的にはホームレス対策というか。","voiceIndex":33,"id":"exchange-014"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"そうなると、やっぱり文書でのやりとりというのは、私は今、非常に、とりわけ高齢者のところでは、今ははっきり言って読むのが大変みたいなんです。ですから、それが単純に返ってこないから辞退だというふうな説明になると、やっぱり私はまずいのではないのかなということで、訪問調査なんかも含めてやったほうがいいなというふうに思ったところなんですけれども、ぜひ検討していただきたいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-015"}]},{"id":"topic-02","title":"の区民活動交流施設（旧八潮南小学校跡）の整備","agenda":"の区民活動交流施設（旧八潮南小学校跡）の整備","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"プールの関係なんですけれども、こちらはどうなるのかなというのがわからなかったので質問したいのと、あと、これまで学校施設ということで避難所で９０６人分の避難所機能ということがあったんですが、これはどうなるのかということをお伺いしたいと思います。","respondent":"堀越文化スポーツ振興課長","answer":"それと、済みません、ご質問いただいてあれなんですが、あわせて１点、説明が漏れておりました。グラウンドと多目的スポーツ室につきましては、これまで地域の方々にご利用いただいていたと同様に、基本的にはご使用いただくという形で考えているところです。","voiceIndex":41,"id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"プールは使用しないということでとりあえずは暫定的には考えるんだけれども、これから調整していくということなので、とりあえずここには置いておくということでいいのかということと、あと、体育館とグラウンドなんですが、従来の地域利用はこれまでどおり進めていくということなんですが、これからそれ以外に全区からの利用希望とかというのがあった場合は。","respondent":"堀越文化スポーツ振興課長","answer":"ただ、今のところ、基本的には利用しないという、それが考え方です。それと、利用希望の調整、全区からということですが、３点目の管理の部分も含めて、運営管理についてはこれから検討していきます。","voiceIndex":43,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"運営の話なんですが、１２月ぐらいからずっと検討ということで答弁なんですけれども、実際どの辺まで進んでいるのかとか、あるいは、一定どれぐらいまでにめどを、運営の形態をどうするかということをめどをつけていきたいと区としては考えているのか、お伺いできればと思います。","respondent":"堀越文化スポーツ振興課長","answer":"時期については、実施設計がこれから秋に入ってきますので、それと並行して、大枠につきましては、このような時期と合わせて、秋、それぐらいか、年内ぐらいには一定の方向性をつけていきたいと考えているところです。","voiceIndex":45,"id":"exchange-018"},{"speaker":"安藤委員","kind":"意見","question":"学校跡地を活動交流施設にということで、先行例の旧原小の跡があるんですけれども、運用してから時間も経過しておりますけれども、いろいろ課題とかが出ているかと思うので、そういったこともぜひいろいろ踏まえた上で、あと、地域の皆さんの声を聞きながらということもありましたけれども、納得のいくといいますか、なおかつきちんと運営できる、区が責任を持てるようなところ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-019"},{"speaker":"宮崎副委員長","kind":"質問","question":"１点だけなんですけれども、駐車場とか駐輪場とか、そういうスペースというのはつくる計画なんでしょうか。","respondent":"堀越文化スポーツ振興課長","answer":"給食室についても現状のままで使用しないという形になります。その裏に、駐輪場ですとか、駐車スペースがありまして、そういうところの利用について、全体の実施設計を含めて検討していきたいと考えております。","voiceIndex":48,"id":"exchange-020"},{"speaker":"宮崎副委員長","kind":"質問","question":"さっきもしかしたら説明があったのかもしれないですけれども、もう１回聞きたいのと、まず、ここら辺のところだと会議室がなかなかとれないとかがあって、こういうところができると、それなりに利用もできるのかなと思うんですけれども、やっぱり現実にちょっと遠いとかという問題があるかなと思うんですけれども、そこら辺の利用が、さっき駐輪場、駐車場もそうなんですけれども。","respondent":"堀越文化スポーツ振興課長","answer":"それと、ほかのところ、地域センター、近隣ですと、例えば八潮地域センターですとか、それから南大井文化センターですとか、そういったところの利用率なんかを見ていますと、音楽室なんかですと、やっぱり８割を超えるような利用率がありますし。","voiceIndex":50,"id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2548#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":26339,"voices":60}},{"id":"h21-20090511-7","meetingId":"h21-cm05","date":"2009年5月11日","dateIso":"2009-05-11","committee":"厚生委員会","time":"午後１時０２分～午後３時４７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"今後の予定のところを、もうちょっとお伺いしたいんです。それから、平成２３年度初めから開設というご説明だったのですが、プレス発表のときは、平成２２年度工事竣工で開設となっていたので、この辺がおくれるということなのか、なぜ先になったのかというあたりも、ご説明をよろしくお願いします。","respondent":"冨岡高齢者福祉課長","answer":"その後に実施設計に入っていくです。それから、さまざまな躯体のほうの耐震の問題とかが出てまいりまして、契約関係につきましては、今の段階では、まだ具体的なものは出ておりませんけれども、平成２２年の早い時期になるかなという予定です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"いろいろ東京都との調整があるということなんですけれども、工事そのものは、１年以上かかるととらえればいいんでしょうか、ちょっとその辺をもう一つ。それから、補助金のことについても、ちょっとお伺いしてもいいでしょうか。この間、ユニット型の個室の場合と、従来型の個室の場合、多分、１部屋の広さが違ってくると思うんですが、その辺の考え方がどうなっているのか教えてください。","respondent":"冨岡高齢者福祉課長","answer":"そうしますと、通常の４３０万円とかというのよりは、逆に低くなってくるというところでございまして、どのぐらいの数になるかというのは、最終的には、今の段階では詰めの段階でありますので、申しわけありませんが、金額的に、改修型だと若干下がってくるです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"居室の面積を、今、教えていただいたんですが、従来型の１０.６５m2を確保するという受けとめ方でよろしいんでしょうか。ちょっとそこのところを具体的に伺いたい。","respondent":"冨岡高齢者福祉課長","answer":"改築はもともとユニット型も促進係数はございません。それから、最初のほうの質問ですけれども、従来型の個室を基本に考えて、多面的に検討を、今、しています。","voiceIndex":9,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"居室のところは多面的にと、東京都の補助金の絡みとかの折衝で、いつまでに決まるとか、その辺の時期的なものがわかったら教えてください。","respondent":"冨岡高齢者福祉課長","answer":"東京都の補助金の内示は、たしか６月にありますので、今、基本設計を詰めているというのは、今月ぐらいまでには、ある程度固めをしまして、その最終的なもので決まっていくということで、それで東京都の内示に向けて動いていくです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"浅野委員","kind":"質問","question":"今後、当然、国としては新型個室のユニット型ということで進めていると思うんですけれども、それと今回の方針の違いというのでしょうか、方針はあるんですけれども、今回、こういう形で従来個室になったということと、ここにある合理的な理由というのは、どのようなことが、今、認められつつあるのかということを、わかる範囲で教えていただければと思います。","respondent":"冨岡高齢者福祉課長","answer":"細長い校舎、廊下が片方で、しかもそういう形で教室が区切ってあるという形を、一番合理的に、適切に活かして改修するとなると、やはり従来型個室、ユニット型の、各単位ごとで、そこを通っては行けないというか、一つの独立した部分でとらえていくというのは。","voiceIndex":13,"id":"exchange-005"},{"speaker":"浅野委員","kind":"意見","question":"わかりました。特別養護老人ホームを創設する場合には、例えば８０名の定員ですと、その１０％はショートステイの部屋を設けるというような規定があったと思うんですけれども、今回は２５％ぐらいになっているんですけれども、こちらのバランスは、そういうことも含めて考えられて、今後、ショートステイが増えるというような考え方でされているのかどうか、そこら辺をお願いいたします。","respondent":"冨岡高齢者福祉課長","answer":"もう一つ、いわゆるゾーンの問題でありますけれども、ここを一つショートステイのエリアとすることで、人員配置の問題とか、運営上の問題もありますので、大体２０人ぐらいということになりますと、そういう意味も含めまして、ショートステイ２０人としたところです。","voiceIndex":15,"id":"exchange-006"},{"speaker":"浅野委員","kind":"質問","question":"これで最後にしますけれども、国のほうで推進している新型特別養護老人ホーム、個室というような部分で、平成２６年に個室化７０％に参酌標準があると思うんですけれども、今回、この個室も、そのパーセントの中に入れられるものなのかどうか。ここら辺の今後の計画に大きく影響する部分があるかと思いますけれども、こちらの将来的な計画等、考え方がありましたら、教えていただければと思います。","respondent":"冨岡高齢者福祉課長","answer":"これからどれだけつくっていくかにつきましては、当然、具体的な立地条件とか、補助金の動向等がありますので、その中で決めてまいりますが、そういう形で、前々から申したとおり進めてまいりたいと思っているところです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"確認","question":"この完成が、年度ではなく日付で言うと、平成２３年の初め、３月ぐらいに工事が終わるということは、スタートがいつごろなのか。さっきの話ですと、１年ぐらいで終わるんですか。そこら辺がちょっと、工事の日程とか、確認をしておきたいと思ったのが１点です。それから、そのとき、どのようなご意見があったのか。出していいものがあったら教えてください。","respondent":"冨岡高齢者福祉課長","answer":"工事の時期は、大体１年ちょっとということで考えているところです。それから、このペーパーを出した説明会ということは、私の言い方があれだったら、訂正しますが、今までの経緯がありますので、検討会の中で経過報告をさせていただいたです。","voiceIndex":19,"id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"特別養護老人ホームが、いよいよできるということになって、平成２３年度に開設となると、１１年ぶりということになると思うんですけれども、ずっと特別養護老人ホームをつくっていと求めてまいりましたので、ほんとうによかったなと思っています。基本設計、実施設計、そこら辺のところの設計をどこが行っていくのかということもお聞かせいただきたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"設計ですけれども、簡易プロポーザルの基本設計ということで実施をして、結果、大建設計というところが、八潮南小学校も含めて実施をしておりまして、こちらも、基本設計、実施設計の流れの中で、契約はなるかなというところです。","voiceIndex":21,"id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"新型特別養護老人ホームと同じような形で進めていくということで、よかったなと思うんですけれども、ということは、この一つのエリアで、特別養護老人ホーム２０人ぐらいずつになると思うんですけれども、ここごとに共有スペースが大体２カ所ぐらい設けられる、１０人に一つぐらいの共有スペースという感じになるということでいいのでしょうか。そこら辺が一つ。","respondent":"冨岡高齢者福祉課長","answer":"これはまだ詳細は詰めておりませんけれども、そういう状況です。それから、説明会につきましては、当然、法律どおり、工事説明会等を、スケジュールに従いまして実施していくという予定です。","voiceIndex":23,"id":"exchange-010"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"区のさまざまの部署で対応、ご苦労さまです。そういった面では、何でも受けつけてくれているのかどうかということ。この号外は、すごく大きな字で読みやすいんですけれども、これがどこまで届いているのかということでは、やたらに心配しないで冷静にきちんと対応してほしいという意味では、これがいかに皆さんのところに届くかということで、どういうふうに配布されるのか、もう１回、お願いします。","respondent":"山岡健康課長","answer":"保健所、保健センターの保健師が、場合によっては電話で対応しますので、状況をお聞きして、ほんとうに深刻な状況なのか、それとも従来からの普通の風邪程度なのかということを、わかる限りで判断して、場合によっては医療機関を紹介するということをしておりますので。","voiceIndex":29,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ、一人でも多くというか、ほんとうだったら、全戸配布ぐらいしていただきたいという思いはあるんですけれども、今まで置いていないところでも、目につくところに置いていただけたらと思います。その辺の判断は、どういうふうに行われて、どういうふうに伝達されるのかというところを教えてください。","respondent":"山岡健康課長","answer":"最初に、配布ですけれども、５月１１日の通常号と同じ形ですので、ほとんどの家庭、新聞を取っていらっしゃる家庭には配布されていると思います。それから、各種イベントですけれども、判断はそれぞれの所管ということではなくて、危機管理対策本部で。","voiceIndex":31,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私も、今日、新聞折り込みで見せていただきまして、すごく目立っていいなと思ったんですけれども、新聞を取っていらっしゃらない方はかなりいらっしゃるのと、私は今、町会の回覧板を回す役なんですけれども、まだ今回は入っていない。ぜひ回覧板でも回していただきたい。何とか、その辺工夫をしていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"確認","question":"いろいろ区のほうで対策を取っていただいたこと、ありがとうあります。変な周りの状況にあおられないで、冷静な対応をしていってもらいたいと思うんです。その中で確認だけ。もちろん、全国で言うと、たしか４,０００万人分ぐらいの対応ができているという話も聞いているんですけれども、その中で、どのぐらい対応していただいているのか、一応安心のために。","respondent":"吉田品川区保健所保健予防課長","answer":"タミフルとリレンザの在庫につきましては、区備蓄分が３,０００人分、それから東京都からもタミフルが１００人分、リレンザが１００人分ほどきております。区が持っているものとしては、合わせて３,２００人分ぐらいです。","voiceIndex":34,"id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"意見","question":"万が一のことがあったら、区のほうも大変ですし、今の段階でも、いろいろ人的にも大変ご苦労なさっていると思いますが、これからも何もないことを望みながら、対応のほうをよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":36,"id":"exchange-015"},{"speaker":"阿部委員","kind":"質問","question":"１点だけ教えてください。発熱相談センターなんですけれども、今、どのぐらいの人数、体制でやっているのかということ。そのときに、完全に素人では多分対応できないと思いますので、急に相談が増えたときなどに、どういった体制をすぐに組めるのか、その辺のお考えを教えてください。","respondent":"山岡健康課長","answer":"ただし、増えた場合は、微妙な症状を発症しているような相談でしたら、直ちに保健師のほうの対応ということで、発熱相談センターから保健所のほうに電話をすぐに回してもらって、保健所のほうはかなりの数の保健師が詰めますので、そこで対応するということになろうかと思います。","voiceIndex":37,"id":"exchange-016"},{"speaker":"阿部委員","kind":"確認","question":"すみません、確認です。保健所って、今は保健師が何人いらっしゃるのですか、基本的な質問ですみません。つまり、このセンターは、最終的に区内だけで対応していくのかどうかということをお伺いします。","respondent":"山岡健康課長","answer":"基本的には、区の保健師、要するに専門職で対応することを考えております。","voiceIndex":39,"id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3234#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":14620,"voices":45}},{"id":"h21-20090511-8","meetingId":"h21-cm05","date":"2009年5月11日","dateIso":"2009-05-11","committee":"建設委員会","time":"午後１時０３分～午後１時５０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"井上委員","kind":"意見","question":"今回のしながわＥＣＯフェスティバルは、今までと違って大分大きな規模になっているのかなと思うんです。私はちょっと認識不足ですけれども、毎年、同時開催だったのかということも含めて。それから、今年、わんぱく相撲が入ってきましたが、そういう変更が何点かあると思うんですけれども、どういう経過でこういう形になっているのかという２点をお願いいたします。","respondent":"工藤環境課長","answer":"３年前までは品川シーサイドフォレスト内でやっていたということでありますけれども、ＥＣＯフェスティバルは２万人規模の参加者ですので、やはり多くの方にきていただくために、同時に開催したほうが、イベントとしての相乗効果が期待できるということで。","voiceIndex":5,"id":"exchange-001"},{"speaker":"井上委員","kind":"質問","question":"来年に向けて、もっと地域で活動している小さな活動団体もできるようになるほうが望ましいと思うんですが、そういったところの計画もあるのかどうか。参加団体として申し込んだけれども、参加できなかった人たちがいるのかどうか、その辺の参加団体についての様子を、ちょっと教えてください。","respondent":"工藤環境課長","answer":"参加団体に関しましてのお尋ねです。１点目、どのような形で、地域、さまざまな団体に投げかけしたかですけれども、２月１１日の広報で、しながわＥＣＯフェスティバルに参加しませんかという募集の記事を出しています。それがまず１点目です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"先ほど、募集と、実行委員会の方たちの口コミということだったんですけれども、広報の募集に対する申込みの件数の状況はどうだったのでしょうか。","respondent":"工藤環境課長","answer":"広報から何件とか、口コミというか、いろいろなつての比率は、ちょっと手元に資料はございませんけれども、大体、８対２ぐらいの割合だと考えています。","voiceIndex":9,"id":"exchange-003"},{"speaker":"井上委員","kind":"質問・要望","question":"これから、品川区も含めて、環境への取り組みというのは拡大をしていく流れになっていると思いますので、いろいろなところで小さな団体もアピールできるような広報の仕方を、ただ参加してみませんかというのではなかなか難しいのですが、そういう形での周知がされるように、ぜひ工夫をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"石田（慎）委員","kind":"質問","question":"ほかは大体、エコの紹介であったり、区がこういう取り組みをしていますよという紹介だったり、広げていこうということだと思うんですが、自転車タクシーはどういうようなお考えなんですか、教えてください。","respondent":"工藤環境課長","answer":"これが区の施策とどう連動するかという部分につきましては、大きな意味での環境の一つだということですので、別の部分と考えております。","voiceIndex":12,"id":"exchange-005"},{"speaker":"菊地委員","kind":"質問","question":"一つ、図面のところを教えてもらいたいんですけれども、４ページにある全体的な絵で、今回は橋脚の工事を主体にしているということなんですけれども、この図面で橋脚は青く塗られていて、太い線が引かれているのは、これは全部中央環状線から入ってきた車が湾岸へ抜ける路線ですよね。逆に、湾岸のほうから入ってくる路線は、これからまた別に説明会をやったりしていくということなんですか。","respondent":"松代都市計画課長","answer":"これは両方に高速湾岸線につながっていますけれども、これはイン、アウト、両方の工事ですので、左側のほうがアウト、右側のほうがインという形で、料金所１カ所で出入りができるという形になるかと思います。","voiceIndex":19,"id":"exchange-006"},{"speaker":"菊地委員","kind":"意見","question":"住民の皆さんも、仕事との関係で、平日の７時からやるということそのものがすごく難しいのではないのかという気がするんです。団地の皆さんの声は、それなりに聞いていらっしゃるんだとは思うんですけれども、その辺のことを、東京都のほうはどういうふうに考えて、こういう平日の設定をしているのかなと。","respondent":"松代都市計画課長","answer":"日程の設定につきましては、細かなところまでは、私は把握してございませんが、東京都のスタンスとして、平日であろうと、土曜日であろうと、日曜日であろうと、地元で求められる説明会等にはきちんと対応するという姿勢で臨んでおります。","voiceIndex":21,"id":"exchange-007"},{"speaker":"菊地委員","kind":"質問","question":"そうすると、自治会連合会ですか、そういうところとの話もしているのだとすると、今回のジャクションの場合、とりわけ直接上部の工事になりますから、住民の皆さんにとってみれば、工事を進める上での騒音の問題とか、開通した後の問題とか直接いろいろ出てくると思うんですけれども、その辺、東京都が自治会とどの程度きちんと議論をして、そういう話をしているのかというのは、区としては。","respondent":"松代都市計画課長","answer":"個々具体的に、いついつ、どういう形でやるかというのはとらえておりませんけれども、この自治会の主立った方々、また自治会を中心としての意見聴取、個別の説明等に当たっている中で、今回は大きな工事ですので、その日程等の調整は十分に図られた上で。","voiceIndex":23,"id":"exchange-008"},{"speaker":"菊地委員","kind":"質問","question":"そうすると、またその点についての説明会が開かれるということになるんですか。","respondent":"松代都市計画課長","answer":"申しわけございません、今回は、今言いましたように、このジャンクション、アウトの部分の橋脚下部工事の説明です。今後、上部工、それから、今申し上げました周辺の付帯工事といったものは別途、発注され、かつ説明会がなされると聞いております。","voiceIndex":25,"id":"exchange-009"},{"speaker":"三上委員","kind":"質問","question":"今の説明の中で、区民住宅は１,０５６戸ということでしたが、その中で、今回、募集するのは傾斜型の４２６戸。要するにファミーユ関係は除くということなんでしょうか。","respondent":"柏原住宅担当課長","answer":"建設型の住宅でファミーユと言っているものがありまして、そのうちの５団地はこの中に入っております。ですので、下神明、西五反田西館、西五反田東館は抜いてあります。","voiceIndex":32,"id":"exchange-010"},{"speaker":"三上委員","kind":"質問","question":"傾斜型の中で、当初、この制度が始まったときは、毎年５％上がってきたという形できているんですけれども、もうそろそろ上限にきているところも出ているのではないのか。上限まで来た段階で、家賃を最高額に設定するときに、近隣との絡みから言って、現在、そのあたりはどんな感じになっているんですか。","respondent":"柏原住宅担当課長","answer":"一番古いところは最高額に近いところに、既にきておりまして、近傍と比べますと、やはりちょっと若干高い状況になっている。同じような間取りの、同程度のところまできていると認識しております。","voiceIndex":34,"id":"exchange-011"},{"speaker":"三上委員","kind":"意見","question":"そうすると、募集したって、そんな高いところだったら、公的住宅だといったって意味が何もないという話になりかねないですよね。そこらあたり、国の制度そのものを、それを改善しようという意見は、全く各自治体から出されてきていないものなのか、どうか。","respondent":"柏原住宅担当課長","answer":"今年度も、東京都、それから国等に強く要望を出していったり、この制度で何かもう少し工夫ができないかとか、それは鋭意、現在も検討しています。","voiceIndex":36,"id":"exchange-012"},{"speaker":"三上委員","kind":"質問","question":"戸数的に、品川区の場合はそんなに多くはないということであれば、問題は表面的には出てきていない。だけれども、いずれは大騒ぎになりますよね。所管は国土交通省なのかわからないけれども、そこに対して直におかしいと、こういう制度については、もう先が見えているものだけに、今からどうするんですかということについて意見をどんどん言っていく必要があると思うんです、そこらあたりはどうなんでしょう。","respondent":"柏原住宅担当課長","answer":"２３区でも同じような悩みを持っているところがありますし、そういったところで、ほかの区との連携も図りながら、確かに、家賃が高くなってきて入れないという状況は、幾つかのところは見えつつありますので、そういうことを踏まえて、ほかの区とも連携しながら。","voiceIndex":38,"id":"exchange-013"},{"speaker":"三上委員","kind":"質問","question":"借上型で、全く埋まりませんということで、前から問題提起されているところがいっぱいあるわけですよ。そういう状況が見えてくるわけですから、これはやっぱりどこかでやっぱりきちっとやらなければ、空き家ばっかり増やしていく。何のメリットもなければ、みんな出ていくだけですよね。もう先が見えているわけだから、そこのところはやっぱりきちっと、何らかの形で言っていってもらいたいと思うんです。","respondent":"岩田防災まちづくり事業部長","answer":"住宅局長は、こういった問題が全国で自治体の重石になっているということは、十分にご理解をしていただいておりまして、今後、要綱改正に向けて検討するというふうに明言をされておりましたので、私ども、引き続き国には要望をしてまいりたいと思っています。","voiceIndex":40,"id":"exchange-014"},{"speaker":"三上委員","kind":"質問・要望","question":"その要綱改正ということが、今、出たので、とにかく実現できるように、またさらに一生懸命努力していただきたいということを、お願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3942#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":13063,"voices":50}},{"id":"h21-20090511-9","meetingId":"h21-cm05","date":"2009年5月11日","dateIso":"2009-05-11","committee":"文教委員会","time":"午後１時０４分～午後３時２３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を53件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２１年度新入学学校別増減要因一覧","agenda":"平成２１年度新入学学校別増減要因一覧","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"増減要因一覧の説明があって、それぞれ小学校と中学校の傾向についてお話があったと思いますけれども、それぞれ、そういう傾向が生まれている背景といいますか、教育委員会がどういうふうに評価しているというのか、そういうところの見解を教えていただきたいなと思います。","respondent":"富田学務課長","answer":"転入や転出等につきましては社会的な要因でありますので、コメントは差し控えします。中学校につきましては指定校変更、区域外就学は減少しておりますが、小学校ほどの大きな開きではないと考えているところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"この増減要因一覧というものは、学校選択制が始まってから毎年出されているんでしょうか。何か目的があってこういう傾向を追っているわけでしょうから、小学校に限って言うなら、この傾向が生まれていることをどういうふうに検証し、課題を抽出して次につなげていくのかと、そういう視点というものはお持ちでないのか、そこがよく見えてこないので、ご説明いただけますか。","respondent":"富田学務課長","answer":"新入学児童生徒につきましては、学校選択制を実施しておりますけれども、学校選択は希望申請だけで入学者が決定しているわけではないということで、ご覧いただきましたように、指定校変更もあり、転入・転出もあり、また、国立・私立等への進学ということもあり。","voiceIndex":7,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"地域と学校との関係を希薄にすること、学校自身を教師と僕らで、地域でつくっていくという、そういった弱める作用もある、通学距離も延びているし、ＰＴＡの方とか、町会の方とかから伺うと、みんな言うのが、子どもを地域で育てるという視点が学校選択制によって崩されているのではないかということをよく伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"川西委員","kind":"質問","question":"すいません、ちょっと基礎的なことでまだ理解していない部分があるんですが、伺いたいと思います。ご了承ください。登録者数というものが左端に、今の説明がよく理解できないという意味なのですが、登録者数と希望申請との関係というのはどういうことなのか。ですから、区域外就学というのはそういう人たちのことをいうのか。","respondent":"富田学務課長","answer":"それで、区域外就学というのは、その通学区域とは別に、品川区以外から入ってくる方々が増の区域外で、減の区域外の方は品川区以外の公立学校に行かれた方です。区内で通学区域以外の学校の希望で移られた方は、指定校変更ということで取り扱いをしております。","voiceIndex":10,"id":"exchange-004"},{"speaker":"川西委員","kind":"質問","question":"そうしますと、通学区域というものは、基本的な通学区域のことをいっているんですね。わかりました。わかりました。そうしますと、以前、１１月ごろでしたか、学校が書いてありまして、受け入れ予定数というものがこの委員会で発表されたように思います。それとこの数字との関係というのは、結果としてどうなっているんでしょうか。","respondent":"富田学務課長","answer":"例えば１番の品川小学校ですとか、あるいは１２番の大井第一小学校も１名オーバーしておりますけれども、そういったところですとか、あるいは２３番の延山小学校、２８番大間窪小学校といった学校も、当初の予定を若干オーバーするけれども、できるだけ意向に沿ってということで。","voiceIndex":12,"id":"exchange-005"},{"speaker":"川西委員","kind":"質問","question":"抽選後の戻りという中で、さっき説明されたんですけれども、抽選をした学校というのはどこでしたか。もう一回教えてください。","respondent":"富田学務課長","answer":"抽選をしましたのは、６番の城南第二小学校、８番、第二日野小学校、こちらは日野学園です。１０番、第三日野小学校、１５番、原小学校、伊藤学園です。","voiceIndex":14,"id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１点だけお伺いしたいと思います。具体的に言おうか。だけど、台場あたりはそんなことないと書いちゃったらというんだけれども、なかなか６年後を見据えると書けないとか、そういう個々の事情ってあるはずなんです。","respondent":"市川教育次長","answer":"その対策ということで、教育委員会としてどうなのかということ、これは基本的に学校がどう対応するかということは考えるわけですけれども、教育委員会もこれに対して必要な体制はとっていくということはまず１つあります。","voiceIndex":16,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"そこで、抽選をしたと、抽選をして戻ってきたのが１１人、この１１人というのは、これは第二日野小学校の子どもさんなんですか。ここにあらわす数字というのがわからないんですが、それで繰上という隣が１１人なんです。希望申請と指定校変更という関係性がどうなのかなということを教えてください。","respondent":"富田学務課長","answer":"指定校変更と希望申請の関係ですが、希望申請は日にちを区切りまして、また小学校については一貫校以外はブロック内で希望申請できることとしております。","voiceIndex":18,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"大体わかったんですが、待機後繰り上げという１１人、これは結局、１１人の戻りが、全員が希望どおり行きましたよという理解でよろしいんでしょうか。","respondent":"富田学務課長","answer":"この数としては、待機後繰り上げが１１人されたということです。","voiceIndex":20,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問・要望","question":"数字であらわすのが難しい部分だと思うんですけれども、もうちょっと全体の動きが、今までの報告の中では、多分、増減だけであって、多分、今回、これを出されたというのが、その要因が何なのかという分析のために出されているということは重々わかるんですけれども、ちょっとこれは見づらいなということがあって、もうちょっと工夫していただきたいなという要望をしたいと思うんですが、あと最後に１点。","respondent":"富田学務課長","answer":"こういった状況を受けまして、今後、区域外につきましては緩和する方向というよりも、現状維持になるかなということで検討はしてまいりたいと考えております。","voiceIndex":24,"id":"exchange-010"},{"speaker":"山元委員","kind":"質問・要望","question":"１つだけ教えていただきたいんですが、小学校も中学校も私立なんですけれども、特に中学校の５４０名が私立の学校に行っている、この不景気のご時世でこんなにも行っているんだと、すいません、すごくびっくりすることで、１つは、少ないのか多いのかを教えていただきたいということと、また、もし何かそういう私立に行かれる、またはエレベーター式とか、いろいろあるとは思いますけれども。","respondent":"富田学務課長","answer":"その他の方々が今年度、４０人弱ぐらい減少しておりますので、相殺しますと、それほど大きな差異はないのではないかと考えております。","voiceIndex":26,"id":"exchange-011"},{"speaker":"川西委員","kind":"質問","question":"先ほどの続きで、最後にわからないこと、実際に抽選の対象になった人数はどこなのか、抽選後戻りの９０名で見ていいんですか、一般の方から今後質問を受けるものですから。","respondent":"富田学務課長","answer":"結果として、抽選後待機になった方々はそれぞれの学区に戻しましたのですけれども、私学等への進学による辞退を受け、第三日野小学校以外については、皆さん希望の学校に入れたということです。","voiceIndex":28,"id":"exchange-012"},{"speaker":"川西委員","kind":"質問","question":"中身はわかりましたが、そうしますと、この抽選の対象になった人数は９０名でいいんですね。それからもう１つは、実際に抽選をしますよというお知らせというものは行くんですか。今回ですけれども、抽選会場へ来られた方というのは何人ぐらいいらっしゃいましたか。","respondent":"富田学務課長","answer":"すいません、まず最初に、抽選になった方々というのは、９０名よりもちょっと多い数でありまして、９０名というのは抽選で待機になった方々の数です。","voiceIndex":30,"id":"exchange-013"},{"speaker":"川西委員","kind":"質問","question":"わかりました。そうすると、そのぐらいの人数は実際に抽選会場に来られたということで理解してよろしいですね。９０よりは多いという、数字が。わかりました。ですから、百幾つなのか、１２０なのか、３０なのかわかりませんが、その半数ぐらいの人が、実際に自分の子どもがどこに入学できるかということで抽選会場まで足を運んだと理解しておいていいですか。","respondent":"富田学務課長","answer":"実際、抽選をした方の数というのは、例えば城南第二小学校で言えば１５人、第三日野小学校で言えば５７人という方々を抽選したわけですけれども、実際にその場に来られた方々は、学校によりますが、半分に満たないということなので、少ないところはかなり、ちょっとすいません。","voiceIndex":32,"id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"意見","question":"すいません、１点だけ。それはどうしてかというと、私の記憶が間違っていたらごめんなさい。ここの学年、今度、特に中学校へ入った新１年生は若干多かったんじゃないのかなと、ここ二、三年の中では、二、三年というか、ずっと。それだけお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":34,"id":"exchange-015"}]},{"id":"topic-02","title":"の子育て応援特別手当の進捗状況","agenda":"の子育て応援特別手当の進捗状況","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"今、冒頭の説明で少し触れられていたんですけれども、この特別手当の目的を教えていただきたいのと、説明の中で、聞き間違いだったらごめんなさい。対象年齢が３歳から６歳ぐらいと言っていたんですけれども、そんなあいまいではなかったと思うので、改めて対象年齢がどこかと、あと何人目の子どもなのかという対象のところを教えていただけますか。","respondent":"安井子育て支援課長","answer":"目的です。こちらは多子世帯の方の、経済情勢での、幼児教育期における子育ての支援ということを目的として、幼児教育期にあたる第２子以降の子がいる世帯の世帯主に対して支給することによって、こちらを支援するという目的となっております。","voiceIndex":39,"id":"exchange-016"},{"speaker":"中塚委員","kind":"意見","question":"多子世帯の経済的支援ということなんですが、例えばその設定だと、要は３人のお子さんがいて、４歳、２歳、０歳の場合だと、これは対象になるのか、あと、別に言うと、６歳と、あと双子の方、仮に２歳の双子、この３人のお子さんのところは対象になるのか、今の説明ではならないと思うので、ご説明いただけますか。","respondent":"安井子育て支援課長","answer":"今の例のケースですけれども、対象にはなりません。","voiceIndex":41,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"多子家庭のお子さんの経済的支援ということは当然だと思いますけれども、実際に、例えば今の例みたいに３人兄弟であっても対象にならない家庭というのも生まれるわけですよね。このことを区はどんなふうに考えているのか、支給されない家庭をどうするのか、そこのお考えを伺いたい。でも、これでは形ばかりではないのかなと思うんですけれども、ご見解を伺えますか。","respondent":"古川子ども未来事業部長","answer":"基本的なことですけれども、既にこの制度についてのご認識については、私どもと各委員の方々は共通の認識に立っていらっしゃると思っています。","voiceIndex":43,"id":"exchange-018"},{"speaker":"川西委員","kind":"質問","question":"そうしますと、本来は２子とかの条件を別にすれば、３歳から５歳の子どもというのは、区で把握していらっしゃるのは何人ぐらいいらっしゃるんでしょうか。参考に聞いておきたいと思います。","respondent":"小林青少年育成課長","answer":"乳幼児人口ですけれども、３歳、４歳、５歳、平成２１年１月１日が直近の数字です。３歳が２,３３８人、４歳が２,４１８人、５歳は２,２９５人で登録しています。","voiceIndex":45,"id":"exchange-019"}]},{"id":"topic-03","title":"平成２１年４月の入園状況","agenda":"平成２１年４月の入園状況","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"教えていただきたいのは、南大井保育園と伊藤保育園で新たに短時間保育という説明がありましたけれども、この２園で、この資料では定員のところが示されていないんですけれども、その理由を教えていただきたい。","respondent":"吉岡保育課長","answer":"というのは、ここは短時間でないところでも定員の弾力化という形で、定員の枠を超えて一定、希望の方を入れているわけですけれども、短時間保育の枠につきましても、その弾力化の中で対応している部分ですので、定員の枠の中には記載してございません。","voiceIndex":51,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"短時間のほう、具体的に伊藤保育園のことをもう少し、どういう運営なのかがよくわからないので、教えていただければ、今の説明ですと一体的にやっているということですけれども、ということは、短時間保育の子どものためというんですか、別に保育室をつくったり、増やしたりとか、あと職員の配置が加配というのか、言葉はよくわからないんですけれども、そういうものはないということなんですか。","respondent":"吉岡保育課長","answer":"短時間保育の関係ですけれども、この短時間保育というものはパート就労の方ですとか、自営業を営んでいるご家庭で、短時間の保育を継続的に必要とするお子さんを対象に開設をしているところでございまして、利用の日時も月曜から土曜の午前９時から午後５時ということで。","voiceIndex":53,"id":"exchange-021"},{"speaker":"中塚委員","kind":"意見","question":"今の保育園に入れないお子さんが増えている中で、私は認証保育園の増設ということが当然必要だと思うんですけれども、そこをどう区は考えているのかということと、この保育園に入れないお子さんをどういうふうに解決していくのかをご説明いただけますか。","respondent":"吉岡保育課長","answer":"いろいろなお考えがあろうかと存じますけれども、区としては一貫して委員会、予算委員会も含めまして、ご説明をさせていただきましたとおり、直ちに認可保育園を増設するというようなことで対応するというよりも、むしろ現在あります保育園を最大限活用いたしまして。","voiceIndex":55,"id":"exchange-022"},{"speaker":"中塚委員","kind":"意見","question":"認可保育園をつくる計画を持たない理由がいまいちよくわからないんですけれども、弾力化と認証保育所の話がありましたけれども、それで、今年の４月で言えば４８８人の人がかなうのかと……。〔「何で４８８人。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":57,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"区の計画は区の計画であると、それと保育園入園がそれでかなうのかと、そういうふうに思っているのかどうかを伺いたい。私は認可保育園の増設を進めなければ、今年、来年に限って言えば、緊急対策でもしっかり打たなければいけないと思うんですけれども、ご説明いただけますか。","respondent":"古川子ども未来事業部長","answer":"子どもを育てる場所は保育園だけではありませんので、保育園あるいは幼稚園、さらには児童センター、あるいは家庭も含めて、すべての対応をとりながら、多くの方々が必要な子育ての需要を満たせるように私ども考えておりますので。","voiceIndex":58,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"認証というお話もありました。繰り返しになりますけれども、今の幼保の話、認証の話、それで解消されるという見通しなのか、それが５年も１０年もお母さん方は待てませんから、時間が限られているわけですから、そういう意味で解消されるという見通しなのか、そこを伺いたい。私は、最後になりますけれども、認可保育園の増設をしっかり位置づけるべきだと思っていますけれども、いかがでしょうか。","respondent":"古川子ども未来事業部長","answer":"しかしながら、実際に実施した中では、そこまでは必要ないというような方々もいらっしゃいましたので、１２３名の中には当然フルタイムの方もいらっしゃいますけれども、さまざまな子育ての状況の中で、例えば育児休業の制度を活用して、育児休業期間を少し先延ばしするだとか。","voiceIndex":60,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"今お話の中で、一時保育のお話が出ました。これはオアシスルーム……、違うのか。ごめんなさい、その一時保育というものがどういうものかわからなかったので、一時保育での受け入れの方法が変わったのか、何かその辺の説明がよくわからなかったので、そこだけ補足してご説明をお願いします。","respondent":"吉岡保育課長","answer":"それから一時保育は、こちらは区立の３０園で実施しているものですけれども、こちらは保護者の方が病気ですとか、出産など、そのような事情で保育ができない場合につきまして、一時的にお預かりする制度ということで、ちょっとその位置づけが違うということです。","voiceIndex":62,"id":"exchange-026"},{"speaker":"川西委員","kind":"質問","question":"定員の弾力化のことについて１つだけ伺います。かなりいろいろ定員外の人数を抱えていらっしゃると思いますが、１７番の二葉、１９番八ツ山、あとは八潮北、八潮西、八潮南、二葉つぼみ、その辺についてはどんな状況で弾力化を抱えていらっしゃるんですか。定員とあまり差がない。","respondent":"吉岡保育課長","answer":"八ツ山も同様です。その他の定数と在園児が一致しているもの、あるいは若干在園児のほうが少ないものというところもございまして、一定、地域の特性によって応募の状況に差がありますので、地区によってはそのような状況も生じているものと理解しています。","voiceIndex":64,"id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"幾つかお尋ねします。そこの絡みと、それは保育のところで、例えば一本橋はゼロ歳が４人になるんですよね。何m2という計算があると思うんですけれども、それを考えると、もっとどうなのか、あとは、これにプラス、多分、予約制度のお子さんたちが入ってくると思うので、それを入れちゃうとどんなになっちゃうのかなということがあって、現状がどうなっているのかなということをお聞きしたいんですが。","respondent":"吉岡保育課長","answer":"１２３人の方の現況ということなんですけれども、詳細に追跡調査をして把握をしているという状況ではございませんけれども、個人的な工夫の中でお預けなさって、知人の方ですとか、あるいはご家族の方ですとか、そういう対応をなさっている方もいらっしゃるでしょうし。","voiceIndex":66,"id":"exchange-028"},{"speaker":"西本委員","kind":"質問","question":"先ほど国の制度の中で、１５％、年度途中だと２５％という話がありますが、ということは、現在１０６％で、まだまだ弾力化は図れますねと思ってしまっていいんでしょうか。それからご答弁のなかったのが、ゼロ、１、２歳児のところでの定員枠というものをどう考えているのか、保育士さんの配置も大分変わってしまう部分があると思うんですが、その考え方をお聞きします。","respondent":"吉岡保育課長","answer":"それから１２３人の方に対して何らか対応が必要ではないかというお話ですが、すいません、そのとおりで、窓口におきましてご相談をする中で、いろいろな、認可保育園だけではなくて、認証のご案内をしたり、あるいは今もおっしゃった一時保育を活用できるようであれば。","voiceIndex":68,"id":"exchange-029"},{"speaker":"西本委員","kind":"質問・要望","question":"ほんとうは３人はそのまま３人を見るわけではなくて、多分、全体の中で見ていくという形が当然保育園の中であると思うので、その１人２人もなくなってしまうということによってのほかのクラスへの影響というんですか、お互いに保育士さんたちが何とかやれていた部分がやりにくくなるという部分も出てくるんじゃないかなという危惧はしていたので、そこら辺の保育の状況を確認していただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"何点か教えてください。全体でいくと、４月１日の状況で６園が定数割れ、ここら辺の状況を、これはみんな満員になっていますよというお話なのかどうなのか、そこら辺を教えていただきたいのと、先ほど来、言っているように、認証保育園と無認可とあるというんですけれども、認証保育園までの定数、それから認可保育園の定数、これを足し込んでいくと、ゼロ、１、２歳児は足りないような気がするんだよね。","respondent":"吉岡保育課長","answer":"ゼロ、１、２歳児と３、４、５歳児ですけれども、全体に言えますのは、ゼロ、１、２歳児に対する需要が高くて、３、４、５歳児はそれほどでもないという傾向が見られている中で、こういうゼロ、１、２歳児につきまして。","voiceIndex":71,"id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問","question":"私の質問の仕方が悪かったのかもしれないんですが、今、多分、このゼロ、１、２歳児の定数減は、２園しかないし、１名とか２名なので５月で埋まるだろう。３、４、５歳児の１５園定数割れの園があるわけです。","respondent":"吉岡保育課長、古川子ども未来事業部長","answer":"定数の割れている部分について、ゼロ、１、２歳児、それから３、４、５歳児について、５月で埋まる見込みなのかどうかですけれども、３、４、５歳児につきましては、先ほど申し上げたように、３、４。もう１つつけ加えますと、定数をどのように考えるかということなんですが、定数だけで１年間運営していきますと、４月の定数ですべてが決まってしまいまして、５月、６月、１０月、年度途中の受け入れはすべてできなくなりますので。","voiceIndex":73,"id":"exchange-032"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そういうことだと思っているんです。私立幼稚園だって、定数割れのところだっていっぱいあるんだよ、まだ。そこまでやる必要はないんだから、と私は思っているんだけれども、だから必ずそこの部分は何かしらの方法を、私は私立幼稚園を含めて３、４、５歳児の部分をあけていくぐらいの、行政側としてやったって、私はいいと思っているので、これは見解は求めない。要望だけにしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-033"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"教育委員会と子ども未来事業部一緒にというお話だったと思うんですけれども、この検討委員会を設置するのはだれと聞いていいのか、教育長が決定するのか、区長が決定するのか、両方という形になるのか、今までこういう両方というものはあまり経験がなかったので、そこを教えていただきたいのと、きっとあした決めることなのかもしれませんけれども、ぜひ原則公開でやっていただきたいと思うんですけれども。","respondent":"市川教育次長","answer":"設置主体につきましては、教育委員会で設置をいたしまして、教育委員会事務局と子ども未来事業部に事務局を置くと、事務局を共管するです。会議の取り扱い方については、明後日の会合の席上、決定されると思いますが、基本的に公開を原則とすると、このように考えております。","voiceIndex":81,"id":"exchange-034"},{"speaker":"西本委員","kind":"質問","question":"２つほどあります。その場合、子どもを引き取っているのはお母さんのほうでということになると、必要なのはお母さんのほうであって、理性がある方であれば、その分だけ、調停中であっても母親のほうにとされる方がいればいいんですけれども、そうじゃない方も多々あるかと、場合もあると思うんです。そういうケースなんかはどういう処置をするのか、何か今、検討されていることがあれば教えてください。","respondent":"安井子育て支援課長","answer":"自治体調整については、当然、各自治体でいろいろ最近、取り組みを始めるというようなところもありますので、相手方の自治体とも確認をとりながら、重複支給のないような形でやっていきたいと考えております。","voiceIndex":86,"id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"それは国がこういう方向で決めたということの理解ですか。そこの状況において、品川区としては何か考えていることはないのかということなんですが、いかがでしょうか。","respondent":"安井子育て支援課長","answer":"そういった事情があるかと思いますけれども、あくまでもＤＶ被害者という場合は、あくまでも身を隠さざるを得ないというところで、申請が全然できないというふうなことで、自主的に受給ができないと考えておりますので、そういったことで……。","voiceIndex":88,"id":"exchange-036"},{"speaker":"西本委員","kind":"質問","question":"ですから品川区でやっている事業であるならば、そういう人たちも含めて何かできないのかということは調整できるのではないかと思うんですが、そこを考えていくということはいただけないんでしょうか。","respondent":"古川子ども未来事業部長","answer":"なぜＤＶ被害者だけかということなんですが、それぞれの個々の状況をとらえますと、必ずしも通常どおりいっていないご家庭、環境はあろうかと思いますが、特にＤＶ被害者の場合は、先ほど所管課長が申し上げましたように、なかなか本人が名乗りを上げたり。","voiceIndex":90,"id":"exchange-037"},{"speaker":"西本委員","kind":"質問・要望","question":"ですからなかなか難しいということで対応というのは非常にすばらしいことだと思うんですが、ただ、同じような、深さはどうかなと思いますけれども、離婚調停中の方たちも一緒で、もっと必要な人たちがもらえないという部分もあるので、そこはいろいろなケースがあると思うので、それについては何か手だてができるような方法があるならば、手だてを考えていただきたいなというふうに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-038"},{"speaker":"中塚委員","kind":"意見","question":"ＤＶ被害の方のわかっている状況を見ると、いろいろな支えが必要だなと思うんですけれども、区独自ということですけれども、ということは、１００％一般財源ということなんですが、ここでは対象約５０人とありますけれども、どれぐらいの総額、相手とどう連絡をとるかということもあると思うけれども……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":93,"id":"exchange-039"},{"speaker":"中塚委員","kind":"質問・要望","question":"相手とどう連絡をとれるかということだけれども、どんな見込みなのかを教えてほしいのと、あと、実施要綱でやるのかなと思うんですけれども、要綱を決めたのはいつかということと、あと、もう少し検討の経過というか、検討の過程の議論の経過を少し教えていただきたいと思います。１つ、世帯主に振り込まれる、国の定額給付金は世帯主に振り込まれるわけですよね。","respondent":"安井子育て支援課長","answer":"そういったことでございまして、さまざまな議論はあるところなんですけれども、まだ細かいところは決まっておりませんけれども、あとは定額給付金等は世帯という、把握が住民票とか、混合世帯とか、そういうものはとれるんですけれども、これの場合は。","voiceIndex":94,"id":"exchange-040"},{"speaker":"西本委員","kind":"質問","question":"今回で多分、この委員会のメンバーは終わりだと思うんですけれども、一応、継続審議になっている案件があると思うんです。その扱いをどうされるのか、もう２回議題となっていないんですけれども、どういう考え方で渡されるのかで、いろいろ進展があるのならば、その進展のぐあいをお聞きしたいということもありますし、どうなっているんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-041"},{"speaker":"西本委員","kind":"質問","question":"やっていただかないといけないということは、３月の初めに聞かされたときの審議の中で議論、大体皆さんそういう感触を持たれたと思うんです。そこがわからないと、私たちも責任を持った形で次の委員会の方たちにお願いするということもなかなか難しいかなと思っているんですが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":101,"id":"exchange-042"},{"speaker":"西本委員","kind":"確認","question":"今、委員長のお話で状況が大体わかりましたけれども、教育委員会としてどういう認識が、スケジュール的にどういう形をとっていこうとしているのかを確認で。","respondent":"冠木指導課長","answer":"今後ですけれども、次回につきましては、今、５月２９日で調整をしているところでございまして、前回の話し合いの中で、私どもからは計画どおり２年後に移設するということで。","voiceIndex":103,"id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"ということは、移設ということを前提に、これから個々の対応をしていくような話し合いに進んでいるという認識でよろしいんでしょうか。それとも、あくまでも存続をさせたいんだという思いが強い皆さんの、もともとそれが強いということはわかっているんですけれども、ある程度の理解をして、そういう前向きな形に今、変わってきているという理解でよろしいんでしょうか。","respondent":"市川教育次長","answer":"私どもは、皆さん方の心情に反するかもしれないけれども、私どもは計画は予定どおりに実施させていただきたい、ただ、計画の実施にあたっては、その移転の前後に子どもたち、在校生に対するとれる配慮はあろうかと、それについて保護者の皆さん、あるいは学校の事情を聞きながら。","voiceIndex":105,"id":"exchange-044"},{"speaker":"西本委員","kind":"意見","question":"やはり次回の委員会の方たちに、全員が同じ委員会になれれば、このまま今の状況を踏まえた形で審議ができると思うんですが、多分、かわってしまう、委員長さんがかわってしまったりとかすると、せっかくここまで私たちを含めて議論をしてやってきたことが、ゼロから始まっちゃうということもあり得ないわけではないので、そこは引き継ぎをきちんとしていただくとか、今、こういう形でやっているので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":107,"id":"exchange-045"},{"speaker":"石田（秀）委員","kind":"質問","question":"委員長に１つだけお願いです。それは、委員会は委員会で、継続は継続、請願が継続ですから、それについての委員長のご配慮があって継続をしていきます。だけれども、あまり委員がかわる、委員長がかわる、議会の中で委員会がかわるわけですから、あまりこれを細かく全部やっていくと、次期の方々の考え方も拘束をするという部分にもなる。それぐらいまでだと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-046"},{"speaker":"川西委員","kind":"質問","question":"１つ伺っておきたいと思います。話し合いの中のメンバーですけれども、請願代表者の方も入っておられるんですか、保護者、代表者だけなのかということを１つ伺います。それから新１年生が入られているように承っているんですが、この新１年生の保護者に対しては、事前に計画についてお話ししてあるのかどうかを伺っておきます。","respondent":"冠木指導課長","answer":"その保護者の中には新しく１年生で入られたお子様の保護者の方も入ってあります。１年生に入られたお子様の保護者についての説明は、事前にさせていただいておるところです。","voiceIndex":110,"id":"exchange-047"},{"speaker":"西本委員","kind":"質問","question":"当然、継続という形で話し合う、継続審議をするのは次の委員会になりますので、そのメンバーの中でやっていただければいいと思っています。私が言いたいのは、こういう経過があるよということの流れはある程度知っていただいた上で、それぞれの考え方でやってくださいということですので、細かいところまでのこうあるべきだとか、そういうことでは決してありませんので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-048"},{"speaker":"山元委員","kind":"質問・要望","question":"申しわけありません。そのとらえ方を、まだ必要はないんですが、どのようにとらえたらいいのかを教えていただきたいなと思います。例えばその地域で感染者が出て、その地域だけが休校になるのか、それとも全部が休校になってしまうのか、その辺の休校ということに関してのとらえ方をどういうふうにとらえたらいいのかなと思いまして、教えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":114,"id":"exchange-049"},{"speaker":"石田（秀）委員","kind":"意見","question":"私もそれを聞こうと思っていたんだけれども、そういう聞き方をするのは大変委員長に対して失礼だと。今日、この報告に何もなかった。だからそれで、どうしてということをまずこっちを私は聞きたい。なぜということ、なぜから入って、具体的なことを聞く。これは総務委員会で全部やるという話になっているということなら、委員長と話がそうついていますということなら、それで終わり。","respondent":"市川教育次長","answer":"今回の新型インフルエンザのこの間の取り組みの報告および説明については、常任委員会につきましては総務委員会ならびに厚生委員会で総括的な報告をするということで調整を図ったと聞いてあります。","voiceIndex":115,"id":"exchange-050"},{"speaker":"石田（秀）委員","kind":"質問","question":"それがまずおかしいんだよ。それは総務、厚生でやってもいい。だけれども、今言ったように、具体的なことが質問があったらお答えしますというお話だと、だけど、総務、厚生でやるというからには、具体的な話が出たときに、総務、厚生に説明員がいなくちゃいけない。具体的に保育園のことでどうなっているんですかといったら、総務、厚生に人が行っていない、答弁する人が行っていないでしょう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-051"},{"speaker":"山元委員","kind":"質問・要望","question":"改めて聞きたいところを質問します。国内で感染者が出た場合の対応というか、学校はどのような、臨時休校があるというふうになっていましたけれども、実際、感染者が出た地域だけが休みになるのか、それとも全部がお休みになってしまうのか、その辺の、まだ出ていないのであれなんですが、なった場合のときのことを教えていただきたいと思います。","respondent":"富田学務課長","answer":"区といたしましても、今後そういった区内に患者が発生するような状況がもしも出てくるような場合には、その時々の状況をよくよく見定めて、区としての、学校の臨時休校等を決定するのは学校設置者、区長ということになりますので、区の危機対策本部の判断。","voiceIndex":118,"id":"exchange-052"},{"speaker":"中塚委員","kind":"質問・要望","question":"それと、今後の動きについては、区民に対して正確な情報を知らせることや冷静な行動、予防対策を知らせることは必要だと思いますけれども、状況としては世界的大流行というんですか、フェーズ６の段階を認めるかどうか、この検討も進んでいる中ですから、あまり仮定の話だけで今から決めるということは難しいとは思いますけれども、フェーズ６に上がったときに、対応がどういうふうに、機能として変わるのか。","respondent":"冠木指導課長、小林青少年育成課長","answer":"学校における取り組みについてですけれども、危機管理対策本部と十分に私どもと状況の意見交換、それから状況の報告等をさせていただきまして。それともう１つ、各施設に対しまして、今後の可能性として、もし状況が悪化しましたとき等、あらかじめ事業の縮小等の可能性もありますと。補足になりますが、教職員、児童・生徒に、特段今のところ体調が悪いとかというような報告は受けてございません。","voiceIndex":120,"id":"exchange-053"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4666#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":41728,"voices":126}},{"id":"h21-20090511-5","meetingId":"h21-cm05","date":"2009年5月11日","dateIso":"2009-05-11","committee":"総務委員会","time":"午後１時０２分～午後２時０７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の新型インフルエンザ対策","agenda":"の新型インフルエンザ対策","exchanges":[{"speaker":"土井委員","kind":"質問","question":"今お伺いしていくと、いわゆる相当な感染力がある新型のものというんですかね。今の実務級という話に進んだのかどうしたのかわかりませんけれども、その辺をちょっと。","respondent":"伊勢危機管理室長","answer":"この場合は課長級の、特に関係する課長が集まってやりますけれども、大きな状況の変化だとか、それに伴う事務の変更、拡大等がございましたら、やはり区長を本部長にする危機管理対策本部を開催して決めなければいけないと考えております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"林委員","kind":"意見","question":"この号外がけさの新聞に入っていた。早速ＮＨＫだとか１０チャンネルが取り上げて、品川区がこういうことをやって、いち早く危機管理をやっていると。これは品川区の発想でつくったものなのか、それとも例えば２３区の区長会とか、そういうところでつくっていこうよということでいったのか、その辺をまず聞かせてください。","respondent":"伊勢危機管理室長、中川原広報広聴課長","answer":"この広報の内容ですけれども、表側は主に感染に関するもので、各発熱相談センターなどは２３区で設置されておりますので、基本的な内容は、内容といいますか、広報で出したかどうかというのは把握しておりませんけれども。私どものほうで４月２６日に第１回の感染症対策本部の席で、区長のほうから速やかに必要な情報について発信の体制をとるようにというご指示がありまして、ホームページもかなり情報を出していたんですが。","voiceIndex":7,"id":"exchange-002"},{"speaker":"林委員","kind":"質問","question":"ちょっとややこしいんだけれども、区独自の内容を書いてあるのか。倍ぐらいの字で病院へ行かないでくださいと。最初の白黒の。これこれ。品川区が病院をあてにしないようになっちゃったら、おれらはどうすればいいんだという、非常にこっち側のお知らせが出たときはみんなびっくりした。この病院に行かないでくださいという文節というか、これはどういう意味を持っているんですか。厚生委員会でやるのかな。","respondent":"吉田保健予防課長","answer":"発熱外来といいまして、感染の疑いがある方を専門に診療していただく医療機関が区内に数カ所あります。そちらの病院にご案内するということで、このような説明をしています。","voiceIndex":10,"id":"exchange-003"},{"speaker":"林委員","kind":"意見","question":"でもこれのつくり方ね。多分出来がいいと思っていらっしゃるんでしょう、保健所関係の方とか広報の関係の方は。でも相当、病院に行かないでくださいというのは、効き目があるというか、区民にとってはプレッシャーがあった。こういう場合は品川区の施設は閉鎖しますというのを、早く知らせなきゃいけないというのは、これからもこれをやれますか。","respondent":"中川原広報広聴課長","answer":"その間、連休の間に、早く治療すれば大丈夫らしいというふうに１週間のうちに状況が変わってまいりましたので、ちょっと広報紙の一番弱いところは、ホームページと違いまして、時間差がなかなか反映しづらいところがありますので、今。","voiceIndex":12,"id":"exchange-004"},{"speaker":"林委員","kind":"質問","question":"ある教育委員会の人と話をしていて、学校の場合は休みますよと。そういう訓練にはなるのかなという、そういうことを話されている人もいたけれども、でもこれを１つの考え方とすると、何のときと言わないけれども、先見性を持って区民の人たちに、こういう役所としてもとらざるを得ないことが起きる可能性がありますよというのは、やっていけるということと僕らはとらえていいわけですか。","respondent":"市岡総務部長","answer":"できる限りこういう迅速な対応を今後もいろいろな機会にやっていきたいと思っています。","voiceIndex":14,"id":"exchange-005"},{"speaker":"林委員","kind":"質問","question":"一連の流れはよくわかりました。最後にお聞きしておくんだけれども、品川区には、正直なところ、感染している人はいないんですね。だれが答えられるのかわからないけれども。","respondent":"吉田保健予防課長","answer":"現在のところそういうご相談はございません。発熱等がございまして、病院をご案内したケースもありますが、すべて陰性でございました。","voiceIndex":16,"id":"exchange-006"},{"speaker":"土井委員","kind":"質問","question":"重ねて今の話で、飛行機に同乗していたりという形で、全国のそれぞれのところに連絡をして経過を見てもらう。地域で経過を見てもらうという対処、対応がされているのかなんですが、そういう方々はいらっしゃるんですか。先ほどいらっしゃるようにも聞こえたんだけれども。","respondent":"吉田保健予防課長","answer":"現在、検疫所のほうから約５００名超の方を追跡するようにという依頼がございまして、その方には電話連絡等で対応しております。","voiceIndex":18,"id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"だからその時点での認識なのかなと思っていたんですけれども、でもいつの時期であっても、ある程度区民のところにはきちんと情報としてお知らせすることが必要だと思うので、その辺の考え方を、やっていたらやっていたで結構なんですけれども、ちょっと教えていただきたいというのが１つと、それから、よくテレビで、例えば先ほど出ていたように。","respondent":"中川原広報広聴課長、吉田保健予防課長","answer":"今後の周知につきましても、今日もテレビ局とか新聞社の取材がございましたが、いろいろなメディアを通じまして、あらゆる手段をとって、必要な情報の提供に努めていきたいと考えています。検疫所からの依頼、あるいは発症者ですが、先ほどもお答えさせていただきましたように、検疫所からは現在までに約５００名超の健康調査の依頼があります。","voiceIndex":20,"id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"先ほどの発熱相談センターということなんですけれども、この発熱相談センターというのはあまり日常生活の中にないので、改めて確認したいんですけれども、これは各自治体、保健所のあるそういう自治体の規模のところで、それぞれ設置をしているものなのかどうかをちょっと確認したいんですけれども、それと先ほどのほかの方の質疑の中では、都内に５カ所あるという説明も。","respondent":"市岡総務部長","answer":"２９日の休日ですね。この日にこの発熱相談センターを開設したんですが、ここでは電話を１０本特設で引きまして、発熱の相談以外に多分いろいろな相談、あるいはお問い合わせがあるだろうと思って、話中にならないような対応をとりました。","voiceIndex":25,"id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"区役所の３７７７－１１１１にかけたんです。整理されました。ありがとうございました。いち早いこういう部分での対応というのは、いち早い対応をされているという認識は持っておりますし、それはそれとして区民は安心だと思うんですけれども、ちょっと１つだけさっき質問したつもりなんですけれども、紙ベースで早い時期に周知をする。イベントで配ると。","respondent":"中川原広報広聴課長","answer":"なので、これは非常に速やかにという中で、ふだんは１カ月かかっている仕事を１週間でやるというのはかなり、連休もかかっている中で、区としては最大限のスピードでやりまして、新聞折り込みも業者に、１１日号の発行とともにということで。","voiceIndex":27,"id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"命にかかわるということで、全世界がこれだけ波及していた。行けばそこで感染するというのは目に見えているわけで、それが弱っている方が行くわけですから、それが相当の数、また病院がさらに病人を生むという状況があるということは私は避けるべきだと思うし、本当にその対応で私はよかったんじゃないかと考えています。そうなったら取り返しがつかないですから、そういうところの対応というんですか。","respondent":"伊勢危機管理室長、市岡総務部長","answer":"ですから、そういう面ではこれから企業に対しても、事業の継続についての啓発、それから、イベントについてはどうするかというのを事前に啓発していくことが、区としての大事な役割になってくると思います。今回はもちろんそういう事態ではありませんので発動することはないと思いますけれども。","voiceIndex":30,"id":"exchange-011"},{"speaker":"金野委員","kind":"質問","question":"１点だけ。気になったんですけれども、これは庁舎で配ってくださっているこの入り口のところで、この中に豚インフルエンザの後、最初の感染予防のためにはという一文が載っていて、最近は豚インフルエンザという表現は極力しない、言わないというのがあるんですが、これはどうなんでしょうか。配っているので、ちょっと心配になったんですけれども。","respondent":"伊勢危機管理室長","answer":"当初は豚インフルエンザと言っていたんですけれども、今は新型インフルエンザ、ＡのＨ１Ｎ１とかという表現を使っておりますので、この辺を含めて、この段階ですと豚というのはおかしいですので、訂正していきたいと考えています。","voiceIndex":33,"id":"exchange-012"}]},{"id":"topic-02","title":"の平成２１年７月１２日執行、東京都議会議員選挙執行要領","agenda":"の平成２１年７月１２日執行、東京都議会議員選挙執行要領","exchanges":[{"speaker":"土井委員","kind":"質問","question":"投票所が変わったのがあるんじゃないかなと思うんですけれども。投票所で今までと変更があったところはあるんですか。あったと思うんですが、その辺を。","respondent":"早津選挙管理委員会事務局長","answer":"前回の委員会でも申しましたが、投票所一覧表中、第６投票所が都立大塚ろう学校だったものが浅間台小学校に変更です。ついでながら、記載の方法でちょっと変更したものがあります。第９は日野学園、従来は第二日野小学校となっておりましたが、そういうふうになっております。","voiceIndex":40,"id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"国会のほうからも余談として話が出ているんですが、仮に国内で先ほどのインフルエンザが流行した場合、その場合には日程の変更とか調整とかはあるんですか。一応それをお聞かせください。","respondent":"早津選挙管理委員会事務局長","answer":"現在の状況ではこのまま進むものと見込んではありますが、状況によっては、変更も検討ということになります。","voiceIndex":42,"id":"exchange-014"},{"speaker":"須貝委員","kind":"質問","question":"変更することも、それは検討はするんだろうけれども、可能性としてはいろいろあるという認識でいいですか。","respondent":"早津選挙管理委員会事務局長","answer":"ある選挙会場が火災のために投票ができなくなったという場合の対応というのはあるんですが、選挙日全体を変えるということはありませんで、その場合、法的にはどうなるのかということを含めて、検討すべきことが多々あるということで。","voiceIndex":44,"id":"exchange-015"},{"speaker":"南委員","kind":"確認","question":"それがどういうふうに改修されるかわからないけれども、当然そういうふうに施設改修されて、行った先でも投票できるような、そういうスペース的なところというのは当然確保されるんだと思うんですけれども、ちゃんと確認しておきたいのと、あと案外こういう選挙の関係で議論できる場面に遭遇しないので、この際伺っておきたいんですけれども、例えば不在者投票というか。","respondent":"早津選挙管理委員会事務局長","answer":"一定規模以上のところですと、入院していても、あるいは病院以外にも特別養護老人ホームですとか、そういうところでは投票が可能なんですが、規模によっては、スタッフ体制等の関係で、公正な選挙とかという観点から、規模があまり小さいと。","voiceIndex":46,"id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"その規模というのはどのくらいか知りたいのと、そういう場合は体制がとれないからというので、しようがないというふうに、しようがないという言葉あれですけれども、やむを得ないというふうに選管としては考えているんですか。","respondent":"早津選挙管理委員会事務局長","answer":"それ以下の場合も、なるべく体制がとれたならば、指定施設をおうけしてくださいという呼びかけはしておりますが、これはスタッフ等の体制によってなかなかできること、できないことがありますので、その段階に現在はあるです。","voiceIndex":48,"id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1818#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":19859,"voices":58}},{"id":"h21-20090512-14","meetingId":"h21-cm05","date":"2009年5月12日","dateIso":"2009-05-12","committee":"行財政改革特別委員会","time":"午後１時０２分～午後２時０５分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"公有財産の有効活用に関すること","agenda":"公有財産の有効活用に関すること","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"非常にいい場所なので、区が直接でやってもよし、民間の力を活用してあの場所を使うというような方法もいろいろと考えられると思うので、何とかあそこの活用をしっかりできるように、今の状況をもう少し拡大して考えてもらいたいと思いますが、いかがでしょうか。","respondent":"日下部企画部長","answer":"できるだけ早く区の直接活用、それから、今ご指摘のありました民間での活用、いろいろな選択肢があるわけですが、区としても都との協議を一生懸命進めてまいりたいと考えているところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"資料の３番目の第一日野小学校のところなんですが、活用計画の中で、ＴＯＣビル建て替えに伴う貸し付けについて協議中とあるんですけれども、どんな協議が行われていて、どこまで進んでいるのか、中身を紹介していただきたいのと、あと、改めて第一日野小学校がＴＯＣの建て替えに伴う貸し付けになったということで、どうしてそうなったのかという経緯も簡単に説明していただきたい。","respondent":"久保田行財政改革担当課長","answer":"そうした中で、ＴＯＣビルの建て替え計画といったものもございまして、協議の中でそうした活用もというところで協議を進めさせていただいたです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"この例のように、公共施設とか公有財産を、民間団体ですとか企業に貸し付けるという例というのが、過去に他にあればどのようなものがあるのか教えていただきたいのと、あと、具体的な協議には至っていないということだったんですが、貸し付ける際の、区としての基本的な考え方というのがあるのかということと、具体的な話ですと、貸し付け料などがどうなるのかというのがあると思うんですが。","respondent":"久保田行財政改革担当課長","answer":"それに加えまして、あとは両者での協議を行いまして貸し付け料を決めていくといったところが実態です。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤委員","kind":"確認","question":"その前の説明では、ちょっとＴＯＣの建て替えに伴い貸し付けになったという経緯がよくわからなかった点があるんですが、今回、ＴＯＣの方の貸し付け料というのも、今言った説明の基本的な考えにのっとって行われるというふうに考えてよろしいのかどうかというのをちょっと確認したいんですけれども。","respondent":"久保田行財政改革担当課長","answer":"ＴＯＣへの貸し付け料の考え方ですけれども、ＴＯＣの方から申し出がありまして、営業活動を維持しながらＴＯＣビルの改修工事を進めたいということで、第一日野小学校を駐車場の代替地として活用させてもらえないかという話がございました。","voiceIndex":11,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"同じ質問になっちゃうかもしれないんですが、これから、こういった公有財産が発生した時に、ＴＯＣの場合は割と突然決まってしまったという印象が強いんですが、貸し付けるときの区としての考え方というんですか、わからなかったのでもう一度、どういう基準でどういうふうに決めていくのかというところの区の考え、姿勢というのをお伺いしたいんですけれども。","respondent":"久保田行財政改革担当課長","answer":"それ以外にも、品川区としての政策判断といったところも重要な要素の一つですので、そういったところを総合的に判断しながら、公有財産を民間の方に貸し付けるということ、いわゆる、その財産としての活用を考えているところです。","voiceIndex":13,"id":"exchange-005"},{"speaker":"原委員","kind":"質問","question":"３点ほどありまして、一つは単純な話で、この一覧表の７と８の間に境が入っているんですけれども、何か特別な意味があるのか、教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-006"},{"speaker":"原委員","kind":"質問・要望","question":"３のところの第一日野小学校、ＴＯＣですか、これはいろいろと協議しているということなんですけれども、多分、品川区全体を考えたときに、これは国道だったり都道だったりというものがあるので、これはＴＯＣだけではなくて、東京都との関係も出てくるのかこないのか、話せるところまでというか、わかっているところまで。品川区の考え方がわかれば教えていただきたいんですが。","respondent":"久保田行財政改革担当課長","answer":"私どもの方で伺っておりますのは、東京都の関係というところでは、都市計画の関係と、あとはアセスの問題。それと建築計画といったところで東京都との関係があると伺っております。","voiceIndex":17,"id":"exchange-007"},{"speaker":"原委員","kind":"意見","question":"そうすると、もうちょっとあれですけれども、よりその先の具体的なところということまでは入り込んでいるのか、これは品川区としてなんですけれども、その辺、もしお話しいただければと。まだないということであれば、その返答だけいただければ。","respondent":"久保田行財政改革担当課長","answer":"今後、具体的にこの事業計画等が固まってきた段階で、事業者と区としての間の関係で協議をしながら、地元の方にもご説明ということも出てくると思いますので、そうしたところで協議をしながら詰めていくことになろうかと思います。","voiceIndex":19,"id":"exchange-008"},{"speaker":"原委員","kind":"質問・要望","question":"そういった意味合いにおきまして、区の考え方を。一言で言ってしまえば、公共性があればお金を取らないで貸すよということなんでしょうけれども、今後において、あくまでも区の財産ですので、その辺のところのお考えをお持ちでしたらお聞かせいただきたいんですけれども。","respondent":"日下部企画部長","answer":"大きくその二つの点があろうかと思いますが、ただ、これにつきましては、ある意味で私ども、今申し上げましたような点で、財政負担の軽減とか、あるいは地域の産業の活性化という面で、それは一つの意味を持っていると思いますけれども、ただ、だからといって。","voiceIndex":21,"id":"exchange-009"},{"speaker":"原委員","kind":"質問","question":"そうしたらもう少し踏み込んで、民間ではなくて、社会福祉法人ですとか医療法人、この辺がやる場合には、それこそ最高裁判例で、要するに有償じゃなくて無償でやるよという形の展開の可能性が品川区として出てくるのかどうか、その辺を教えていただけますか。","respondent":"日下部企画部長","answer":"そこからこうほうえんを選ばせていただいて、そこに無償貸し付けをしたわけでありますし、そういった意味では、今後ともそういうケースが出てくればそのような方法をとることもあり得るのではないかと考えております。","voiceIndex":23,"id":"exchange-010"},{"speaker":"原委員","kind":"質問・要望","question":"そうしますと、判例があるから行政は何をやってもいいよという方向ではなくて、要望としまして、今後においてその都度いろいろ出てくると思いますので、非常に大事な財産ですので、その都度チェック機能を生かしていただいて、我々委員の方にもその辺のところを。ということは、具体的には区民に対して説明がつくような形でお願いできればと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-011"},{"speaker":"阿部委員","kind":"質問","question":"３点ほどお伺いします。先ほどの質問にありました東品川の清掃作業所、本当にもったいないなと皆が思う話なんですけれども、その協議なんですが、もうちょっと具体的に教えていただけないでしょうか。今までどんな形で協議されていて、あとどのぐらい協議が続きそうなのか。１０年かけて協議をしてもしようがないので、その見通しと、それから感触ですね。その辺の考え方を教えてください。","respondent":"久保田行財政改革担当課長","answer":"ただこの場所でそういうことをやるかということではなくて、考え方としてはそういう考え方もあるという認識は持っているところです。","voiceIndex":26,"id":"exchange-012"},{"speaker":"阿部委員","kind":"質問・要望","question":"どこを押せば動きそうなのか、もしあれば教えていただきたいと思ったんですけれども、今のところまったく話せるものがないということなら、それで結構です。あればご答弁ください。ある程度検討委員会みたいなことを内部でなさっているのか、それとも何か思いついたら挙げましょうというレベルの話なのか、体制としてどのようにやっているか、ちょっと確認させてください。ご答弁いただけるものですか。","respondent":"久保田行財政改革担当課長","answer":"土木事務所の件ですけれども、具体的に何か組織を立ち上げて検討するといったところではございませんけれども、こうした場合、跡地活用する場合に、私どもの方で基本的に考えておりますのは、こうした立地条件ですとどういったものができるのかという。","voiceIndex":28,"id":"exchange-013"},{"speaker":"菊地委員","kind":"質問","question":"これは先ほど言っていた公共性があるかとか、公益性があるかとか、政策判断の中でやるんだということなんですけれども、当然、線引きとして、先ほど部長がおっしゃっていた、一民間企業なのかどうかということも一つの線引きなのかもしれないですけれども、何かその辺の線引きというのは必ずあるんだと思うんですけれども、その辺を教えていただけますか。","respondent":"久保田行財政改革担当課長","answer":"貸し付けに当たりまして、有償というところを原則といたしながらも、区としての政策的な判断等があれば、無償としても貸し付ける場合があるといったご説明をさせていただいたところです。","voiceIndex":30,"id":"exchange-014"},{"speaker":"菊地委員","kind":"質問","question":"そのことをどういう形で確定をしていくのか。一体だれがどうやって、どういう形でその確定をしていくのかというのが、今のお話だとよく見えてこないんですよね。その辺をもう少し具体的に教えていただけますか。","respondent":"阿部経理課長","answer":"それで、貸し付けをどうするかということは、公有財産の運営の委員会がありますので、その中で貸し付けをどうするかというのを決めています。","voiceIndex":32,"id":"exchange-015"},{"speaker":"菊地委員","kind":"質問","question":"そうすると、公益性、そこでは当然、もし区が活用していない施設、あるいは土地があれば、それをどこかに貸し付けて、その料金を得て、それを何かの財源していくということは、考え方としてはあり得るんだと思うんですけれども、じゃあ、その公益性を判断するというのも、今、課長がおっしゃっていた委員会での判断ということになるんでしょうか。","respondent":"阿部経理課長","answer":"貸し付ける場合には、また別に使用料の条例があります。行政財産の貸し付けの使用料の条例がありますので、それにのっとって、行政財産の場合には貸し付け金額を決めて、貸し付けるです。","voiceIndex":34,"id":"exchange-016"},{"speaker":"菊地委員","kind":"質問","question":"最後に、今の委員会、担当される方は部長さんたちなのかなと思いますけれども、それは全庁縦断的につくられる委員会という意味合いでしょうか。それとも、例えばまちづくり事業部だったたらまちづくり事業部というような、その事業部での委員会ということなのか、そこだけ最後に教えてください。","respondent":"阿部経理課長","answer":"財産を所管するのは総務部ですので、総務部を中心に企画部、あるいは教育部門であれば教育委員会とか、そういう部を中心にした委員会で定めています。","voiceIndex":36,"id":"exchange-017"},{"speaker":"石田委員","kind":"質問","question":"１点だけ質問したいんですが、区内にある国有地が、今は国の方も大分スリム化を図っていて、売却を考えることが多いと思うんですが、その関係で、ここ数年の間に、区が実際に国有地を取得した例があるのか、また今後近々に取得の考えがあるのかというのを、わかっている範囲でよろしいのでお願いします。","respondent":"阿部経理課長","answer":"近々で国有地の取得の予定があるのかということですけれども、現在のところ、私どもの関知しているところでは、具体的にいつどこを取得するかという予定はございません。","voiceIndex":38,"id":"exchange-018"},{"speaker":"石田委員","kind":"質問・要望","question":"これは要望ですので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-019"},{"speaker":"井上委員","kind":"確認","question":"先ほどの議論の中で２点確認をしたいんですけれども、ＴＯＣのところの件ですが、一番最初に平成１７年、平成１８年のときから具体的な協議はしていないということでしたけれども、それからもう２年たっていて、そこの社会状況というのが随分変わっているので、そこから何か、そのままの状況であるということはちょっと思えないので、その辺で何か、先ほど地域の商業のインフラ整備というところでも。","respondent":"久保田行財政改革担当課長","answer":"私どもで聞いているのは、１０年間の暫定的な活用をさせてもらいたいですので、ＴＯＣの改築、建て替え計画も含めまして、その開始の時期がいつになるかということはあると思いますけれども、予定としましては平成２２年度から。","voiceIndex":41,"id":"exchange-020"},{"speaker":"井上委員","kind":"質問","question":"そうすると、建て替えの１０年間の賃貸のところで、あとはそれをどういう形で金額とかいろいろと詰めたものを行政として区民に対する説明を、どういう場を使って公表していこうとされているのか、教えてください。","respondent":"久保田行財政改革担当課長","answer":"私どもで聞いていますのは、まずＴＯＣの方から改築建物計画に関しますアセスメント調査という形が地元に行われる、地元の方に開発計画を明らかにされるといったところがあると聞いておりますので、それを受けまして、私どもとしましては、第一日野小学校の跡地等につきましても。","voiceIndex":43,"id":"exchange-021"},{"speaker":"井上委員","kind":"質問・要望","question":"あるいは委員会とかといったところで報告をされるのか、どういう場で区民が知り得るのかということをお聞きしたので、その辺をお答えいただきたいと思います。","respondent":"久保田行財政改革担当課長","answer":"その後は、いろいろな開発の住民説明会とかがありますので、そうした中で、区としても第一日野小学校の跡地の活用といったところでかかわりがありますので、ＴＯＣ側と連携・協議をしながらそういったことを進めていかなければならないのではないかと考えているところです。","voiceIndex":45,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"建て替えには１０年間もかからないんじゃないかと単純に思ってしまうんですが、そこら辺で、なぜ１０年間なのかというのがわからなかったので、教えていただきたいと思います。","respondent":"久保田行財政改革担当課長","answer":"それで、ＴＯＣ側がなぜ１０年間か、長期にわたっての工事かですけれども、ＴＯＣ側の方としましては、営業を継続しながら、周辺のビルの建て替え工事を行いたいという考えを持っておりますので、そうしますと。","voiceIndex":47,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"１０年間かけてやるということですか。わかりました。公有財産をどういう考え方で民間団体に貸し付けるのかという点では、透明性がすごく大事になってくるのかなと思うんですけれども、ちょっとはみ出しちゃうかもしれないんですが、先ほども菊地委員から質問がありましたけれども、そこら辺、どういう考えで貸し付けていくかというところをよく明らかにしていくというか、知りたい点がすごくあるんですね。","respondent":"日下部企画部長、阿部経理課長","answer":"総合体育館の跡地につきましては、これはご案内のように再開発の計画がありますので、そういうものを前提にしまして、日野学園の下層部分に総合体育館を移転したという中で、跡地が生じたわけでありますけれども。もう１点は、地域の方からもいろいろなお話、騒音とかそういうのがありますけれども、それは私どもから、今、お貸ししている会社に申し上げて、十分な対応をしていただいておりますので。","voiceIndex":49,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"というか、どういう経緯で貸したのかという、その透明性がすごく大事なんじゃないかなということで聞いたんです。それと、今のご答弁の中で、募集をしたという話もちらっとあったんですが、そういうことがあったのかということと、今回の総合体育館の場合は、ちょっと例外的なものなのか、それとも基本的な考えにのっとって進んだものなのかということをお伺いします。","respondent":"日下部企画部長","answer":"こういう扱いが例外なのかどうかということでありますけれども、冒頭の全体説明もさせていただきましたけれども、基本的には、短期とか長期とか、いろいろ活用のケースというのはありますけれども、基本的にはある程度中長期的な視点に立って活用計画というのを。","voiceIndex":52,"id":"exchange-025"}]},{"id":"topic-02","title":"の特定事件調査のまとめ","agenda":"の特定事件調査のまとめ","exchanges":[{"speaker":"須藤委員","kind":"提案","question":"それから５番目は直していただいてよくなったと思うんですけれども、最後の文がまた「立地環境や」云々で、「策定過程においても検討されたい」というのが後ろに来ているんですが、逆に、「また策定過程においても立地環境や長期的な行政需要、地域住民の意見等が計画に反映されるよう検討されたい」と言ったほうが、文章としてすっと流れるんじゃないかと思うので、ご提案します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":58,"id":"exchange-026"},{"speaker":"井上委員","kind":"質問・要望","question":"区民はそのときに必要なもの、地域の身近なところにそういうところがあれば意見を出したい、こうしてほしいというのは当然な意思表示だと思います。そこのところで暫定活用、改築とか解体とか、そういうところにない部分のところでも視野を持っていただきたいということを、ぜひこの委員会での議論も踏まえて考えていただきたいというのを一言伝えたいなと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5860#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":18535,"voices":67}},{"id":"h21-20090514-16","meetingId":"h21-cm05","date":"2009年5月14日","dateIso":"2009-05-14","committee":"街づくり特別委員会","time":"午後１時０３分～午後４時０５分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6386#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":2265,"voices":10}},{"id":"h21-20090522-8","meetingId":"h21-cm05","date":"2009年5月22日","dateIso":"2009-05-22","committee":"建設委員会","time":"午前１０時０２分～午後４時２１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3944#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":1887,"voices":10}},{"id":"h21-20090528-9","meetingId":"h21-cm05","date":"2009年5月28日","dateIso":"2009-05-28","committee":"文教委員会","time":"午後１時１２分～午後１時４８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"私は、今回の人事院勧告が、今までのルールを破って前倒して減額するものだというのは、前代未聞のことだと思いますし、伺いたいのは、通常の勧告は、８月ぐらいですか、民間給与調査がありますけれども、通常の勧告までの調査と、今回の勧告と、何がどのように違いがあったのか、これをちょっとご説明いただきたいと思います。この３点を教えてください。","respondent":"田村庶務課長、冠木指導課長","answer":"人事院勧告の受けとめ方と、また今回の条例改正と、経済的な波及という問題とは、もともと人事院勧告の制度そのもの、特別区の人事委員会もそうですが、労働基本権が、公務員として一定制約がある、そのかわりに民間との国民感情。学校教育職員、いわゆる区独自採用の教員等ということになりますが、８名です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"暫定的な措置、特例措置と言いますけれども、今回の勧告のルール破りを正しいと思っているのか、そこについてはどう思っているのか、教えていただきたい。それから、先ほどちょっと伺ったんですけれども、地域経済の民間給与への影響について、教育委員会所管分の人数は、今出ましたけれども、全体の変更がありますので、地域経済への影響をどんなふうに考えているのか、ご説明いただけますか。","respondent":"市川教育次長","answer":"昨年来の動きを見ていれば、これが１年前と比べて、どういう月数になっているかということは、まさに一目瞭然のことです。したがって、この秋に予定される本勧告の内容も、かなり厳しいものになるということが見込まれてあります。","voiceIndex":8,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"例えば、通常であれば、１万１,０００企業、対面で調査するんですけれども、今回は２,７００社の郵送による調査、回答が２,１０７社で、実際に夏のボーナスを決めたと回答したところは３４０社しかない。ここをどうお考えなのか伺いたい。私は、この負の連鎖は断ち切らなきゃいけないと思うんですけれども、どんなふうにお考えでしょうか。","respondent":"市川教育次長","answer":"２点目の負の連鎖が心配されるということですけれども、負の連鎖が心配されるから、公務員給与を抑制すべきではないという論理は成り立たない、これは、私は断言いたします。負の連鎖を断ち切るのは、他の政策的な措置で考えるべきだと、このように受けとめてあります。","voiceIndex":10,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"ずさんな調査、地域経済や地域賃金への影響、直接答弁はありませんでしたけれども、区の非常勤や委託先の職員、これは委託料にも反映するんでしょうか、そういった影響もどう考えているのかお伺いしたいですけれども、私は、この勧告はやっぱり間違っていると思うんですよ。先ほどの区の非常勤と委託先、委託料についてだけ、教えてください。","respondent":"市川教育次長","answer":"ということは、これまでもそうでしたけれども、公務員給与が下がったからといって、役所からの発注の際に、そのことを盾に一方的に発注単価を下げるとか、そういうことは、これまでもしてきておりませんし、今回も、特にそういう話は聞いてございません。","voiceIndex":12,"id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"要は、世の中が下がっていっているから、当然、公務員給与も下げなきゃいけないという考え方なのか、そうではなくて、もともとの税金の原資がなくなってくるので、下げるしかないという考え方なのか、その辺がどういう考え方なのかと、ちょっと不思議に思っているので教えていただきたい。やっぱり、当面はこの形でやらざるを得ないというふうに考えているのか、そのお考えをお聞きしたいと思います。","respondent":"田村庶務課長、冠木指導課長","answer":"公務員の給与の考え方なんですが、先ほど教育次長のほうからも説明がありましたが、そもそも私たち地方公務員は、地方公務員法第１４条によって、情勢適用の原則というのが適用されます。ということは、区には、教育職だけではなくて、いろいろな職がありますので、その方々とのバランス等を考えながら、区独自の教員の期末手当、勤勉手当については規定されているとご理解いただければと思います。","voiceIndex":14,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問・要望","question":"最後のほうですが、現状はわかります。当然、ほかの職がありますので、そのバランスを見ながらということかもしれませんが、しかし、せっかく独自採用しているということにおいては、そういう仕方をすることも一つあってもいいのではないかなという形で、今後の検討課題ということで検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-006"},{"speaker":"川西委員","kind":"意見","question":"ちょっと基礎的なことを、この際に聞いておきたいんですが、世間一般的な夏のボーナスのところで、期末手当と勤勉手当となぜ分かれているのか。そういうところのことを、ちょっと承知しておきたいんです。","respondent":"冠木指導課長","answer":"期末手当につきましては、基本的に、在職期間、このぐらいを勤めたということからの算出でございまして、勤勉手当のほうは、人事考課等々を反映した形でのものというふうにご理解いただければと思います。","voiceIndex":18,"id":"exchange-007"},{"speaker":"川西委員","kind":"質問・要望","question":"そうしますと、期末手続、勤勉手続それぞれ規則のようなものが定められていて、在職期間とか、人事考課とかいう判定基準というのが別にあるわけですね。それはまた別の機会に教えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"凍結月数、凍結という言葉をあえて使っている。だけれども、凍結という言葉が生きてくるわけですね。ところが人事委員会で０.３月とか、０.４月と出たら、冬からその分を合わせて引くのか、そういう意味合いの凍結なのかということを、ちょっと再度確認をしたいと思っているんです。だから、あえて凍結という言葉をつかっているのかということを、再度、確認をしておきたいと思います。","respondent":"田村庶務課長","answer":"ということは、今回は０.２月ですが、経済情勢によっては、今の段階では、どういう形になるかは見えませんが、それで足りないということも出てくる可能性もあるし、景気の情勢と調査の結果次第ということになります。","voiceIndex":21,"id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問","question":"執行されるんですけれども、今回の場合は暫定だから、さっきも言ったように、０.２月とか０.１５月なんですけれども、それが０.４月と出てきたら、その精算行為というのは、今度まだ議案で精算行為が出てくるわけですか。そうではなくて、相差が０.３月とか０.４月とかいうのが後で出てきたら、精算行為というのは自動的に、例えば冬の賞与とかでもっと引かれちゃうわけではないですか。","respondent":"市川教育次長","answer":"プラスになることはまずないと思いますけれども、見込みで申し上げますと、今回は、一応０.２月と。この一応という意味は、夏の期末手当と勤勉手当については、とにかくトータルで０.２月分はマイナスにしておきますと。","voiceIndex":23,"id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"意見","question":"そうしたら、逆に、人事委員会は人事委員会として、やろうと思えばやれるんですけれども、議案のもとの部分を直せば、こういう出し方ではなくて、人事委員会に追随する出し方ではなくて、品川区として、最初から０.５月でいこうとかやれば、組合との問題もあるけれども、それぐらいのことを打ち出せるような、後々こういう変な出方がするのであれば。","respondent":"市川教育次長","answer":"前段の精算に関しては、先ほど、同様のことを申し上げましたけれども、仮に今回の措置を抜きにして、秋の勧告を待って、今年の１２月と来年の３月の支給分から精算することになると、かなりの削減額が出てしまいますので、給与を受ける側の立場に立っても。","voiceIndex":25,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"当事者間の合意を尊重する立場で、あえて反対はしませんけれども、しっかり地域経済を自治体が支えていっていただきたいと思います。賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4668#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":10257,"voices":39}},{"id":"h21-20090528-5","meetingId":"h21-cm05","date":"2009年5月28日","dateIso":"2009-05-28","committee":"総務委員会","time":"午後１時０８分～午後１時４１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"する条例、(2) 第５２号議案、品川区教育委員会教育長の給与および旅費ならびに勤務時間その他の勤務条件に関する条例の一部を改正する条例、(3) 第５３号議案","agenda":"する条例、(2) 第５２号議案、品川区教育委員会教育長の給与および旅費ならびに勤務時間その他の勤務条件に関する条例の一部を改正する条例、(3) 第５３号議案","exchanges":[{"speaker":"林委員","kind":"質問","question":"頭がおくれてきたのか、ちょっと内容についてではなくて、今日の本会議からここまでの流れについてお聞きをしたいんですけれども、一つは、副区長が説明をしたときに、第５３号議案から入りましたよね。それから、人事委員会の意見聴取についてというのを添付していただいているんですけれども、再任用については、ここには入らなくていいんですか。その二つを教えてください。","respondent":"伊勢総務課長、榎本人事課長","answer":"副区長が説明しました第５１号議案から第５５号議案ですが、一括して説明しておりまして、人事委員会の勧告、これらがベースになってきているという関係もありますので、説明とましては、そのほうがわかりやすいということで。意見聴取の部分につきましては、再任用職員分は、普通の職員のところで含んでおりますので、条例としては、職員の給与条例の中に再任用部分も含んで、給料表もすべて入っておりますので、職員と一緒というものです。","voiceIndex":6,"id":"exchange-001"},{"speaker":"林委員","kind":"質問","question":"すみません、それは失礼しました。区長、副区長、教育長ときて、区議会議員だと思うんですけれども、これも何か決まりがあって、こういうふうに並べてあるんですか。","respondent":"伊勢総務課長、市岡総務部長","answer":"常勤監査委員も区長の条例がかかっておりまして、それで変わるということで、こういう順番でやらせていただいております。したがって、言ってみれば、議案ではないけれども、連動して同じように凍結するという意味で一番最後につけたです。","voiceIndex":9,"id":"exchange-002"},{"speaker":"林委員","kind":"質問","question":"最後にします。別に僕は不足があって言うのではないですけれども、区長、副区長、区議会議員とくるのは、区長、区議会議員、副区長とくるのが、議員の言い方に直すと、そういう並びにならないんですか。","respondent":"伊勢総務課長","answer":"第５１号議案を見ていただくとわかるように、これはあくまでも、区長と副区長の給与等の関係の条例ということで、一つのまとまりということでご理解いただければと思います。","voiceIndex":12,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"今回、このように臨時の特例措置ということで出たんですが、こういうことは今までもあったのでしょうか。臨時勧告ということは、どの時点においてもこういうふうに、常に人事委員会のほうで出せるのか。ちょっとその辺を教えてください。","respondent":"榎本人事課長","answer":"特別区人事委員会の特例措置の勧告というのは、今回初めてです。特別区人事委員会は昭和５３年にできまして、それ以来初めてのものです。同じく、国のほうの国家公務員の人事院の勧告の特例措置も、今回初めてです。","voiceIndex":15,"id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"もう１点。これは結局、臨時ですから、別に時期はこだわらずにいつでも、特別区人事委員会からの臨時勧告が出せるのかどうか、その辺をお聞かせください。","respondent":"榎本人事課長","answer":"権限的には、いつでも出せるという形になります。ただし、今回、この５月の時期に出したのは、夏の賞与に間に合わせるのには、この時期には勧告をしておかないと、手続的に間に合わないという意味でのぎりぎりの時期での臨時的な勧告と理解しております。","voiceIndex":17,"id":"exchange-005"},{"speaker":"土井委員","kind":"意見","question":"今、その話が出たので、人事院で勧告をする場合、民間給料等を一定の数調査をして、それに基づいて出てくるという形になるんですね。今回のものは、同じように調査をされたのかどうかということだけ聞かせてください。","respondent":"榎本人事課長","answer":"今回は、人事院は緊急調査をしましたけれども、特別区人事委員会については独自の調査はしておりません。実際には、情勢適用と、国の人事院勧告と、他団体との均衡というものを考えまして、臨時的な勧告をしたものです。","voiceIndex":19,"id":"exchange-006"},{"speaker":"土井委員","kind":"質問","question":"いずれにしても、それを、労働組合も含めて納得をしたというか、合意をしたということですから、よろしいのではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"同じような質問を、私も用意していたんですけれども、サンプル調査という言い方はあれですけれども、ふだんは実際に企業を訪問して、どういう状況にあるのか、給料の状況とか、そういうものも実地調査というんですか、そういうことをしていると聞いているんですけれども、通常の調査の状況がどういうものなのか、そして今回はどうなのかということを、ちょっと改めて教えていただきたいと思います。","respondent":"榎本人事課長","answer":"ただし、今回につきましては調査を実施しない形で、あくまでも凍結ということで、平成２１年度の本調査を待って、年間トータルとしては調整を図るという形になっていますので、あくまでも臨時的措置として、今回の部分が出ているというものです。","voiceIndex":22,"id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"そういう論調の新聞報道も結構あると思うんですけれども、その辺についての認識は、区はどういうふうにとらえているんでしょうか。","respondent":"榎本人事課長","answer":"そのときのマイナスが余りにも大きいと、年度末手当だけではカバーできなくて、１、２、３月分の生活給のほうにまでマイナスを入れなきゃいけないという部分もありまして、その辺を想定しますと、やはり夏季賞与で。","voiceIndex":26,"id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"やっぱりきちんと言うべきことは言う、しかし、当該のところが妥結しているわけですから、それはそれで、こちらが乗り込んで、おかしいとか、反対だとか、そういう性格のものではないから、そこは言えないけれども、しかし、今後のことを考えたときには、そういうふうに思って、そういう考え方もしっかり受けとめておいていただきたいということを言っておきたいと思います。","respondent":"須藤委員長","answer":"今の態度表明的なものも少し含んでいるので、委員長としては、その辺を判断しなくてはいけないんですが、反対はしませんという考えでの態度表明ですね。","voiceIndex":28,"id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1820#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":8918,"voices":37}},{"id":"h21-20090601-6","meetingId":"h21-cm06","date":"2009年6月1日","dateIso":"2009-06-01","committee":"区民委員会","time":"午後１時０２分～午後２時５５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を8件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の２番目、事務事業概要","agenda":"の２番目、事務事業概要","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ボランティアの方がなかなか見つからないために、配食サービスを希望しても受けられないということを聞いているんですけれど、そういう実態についてと、それからこのボランティアの方には１回当たり１００円というのが出ているとお聞きしたんですけれど、１回１００円というと１週間に２回で４週やったとしても８００円ということになるのかなと思うんですけれど、ここら辺のところをもっと改善をして。","respondent":"中山地域活動課長、秋山協働・国際担当課長","answer":"もしくは、大崎第二のような明らかに移転が決まっているものについては、そういう形での対応になっておりますので、耐震化が図られるですので、基本的にはきちんと耐震診断をやっていき、しかるべき対処をしていくという考え方です。それからボランティアの方へは１００円というお話でしたけれども、１食当たり１５０円ということでお渡ししておりまして、ボランティアの数につきましても個人の登録の方も増えておりますし。","voiceIndex":41,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それから配食サービスは、私はちょっと介護の関係の方からこういうお話を伺ったので、どういうことなのかなと思ったんですけれど、担当課としては、ボランティアの人がいないために受けられないということはないので、希望すれば受けられるということでいいんですね。はい、わかりました。","respondent":"中山地域活動課長、福島ものづくり・経営支援課長","answer":"先ほどちょっと説明が漏れましたけれども、すべての地域センターをやるのかというと、たしか昭和５７年度以降だと思います。今年になってからは１月が４件、２月が１１件と、ここまでの報告は来ております。","voiceIndex":44,"id":"exchange-002"},{"speaker":"南副委員長","kind":"質問・要望","question":"あそこはもともと学校で、避難場所にもなっていると思うんですけれども、これから学校の空き施設がいろいろな活用をされていくという方向になっていかざるを得ない部分はあると思うんですけれど、基本的な考え方として、防災避難場所になっているわけで、そこがどの程度避難場所というものを確保していくか基本的な考え方を伺いたいのと。","respondent":"堀越文化スポーツ振興課長、諸岡商業・観光課長","answer":"これは防災課のほうと連携して当たっていく形になりまして、八潮の件に関しましても防災の協議会の会長さんと、防災課、区全体でいろいろ課題について検討を始めていると聞いておりますので。これを年４回ほど予定しておりまして、主な予算の内容といたしましては、その飾りつけの横断幕でありますとかリーフレット、チラシ、個店ののぼり旗等、それに参加する店を商店街連合会のほうで募集しますので。","voiceIndex":48,"id":"exchange-003"},{"speaker":"南副委員長","kind":"質問・要望","question":"どうしても私たちは、大型店のほうに行っちゃえば、あれもこれもと全部チョイスしてかごの中にバッとまとめて、レジを通れば終わっちゃうみたいな、そういう簡易なところがあるので行きがちなんですけれども、不況のときだからこそ、とりわけそういうところに心を下すみたいな、行政側での配慮というものをもう少し大型店に求めるみたいなことがあっていいんじゃないかと。","respondent":"諸岡商業・観光課長","answer":"大型店との連携等ですけれども、これは先ほど協働研究というものを申し上げましたけれども、そのほかにも産業振興懇談会の中で大型店の代表の方、商店街の代表の方々が一堂に会して、情報交換、意見交換等を行う場もありますので、こういった中で大型店との連携を新たに考えて。","voiceIndex":51,"id":"exchange-004"},{"speaker":"三上委員","kind":"確認","question":"１つ確認させてもらいたいんですが、臨海斎場の件で、今申込みをして何日ぐらい待つような状況にあるんでしょうか。あそこは炉を設置できる場所はまだあるはずだけれども、そのあたりの活用について検討しているのかどうか、あわせてお伺いしたいんですが。","respondent":"梶戸籍住民課長","answer":"ちなみに斎場の式場のほうですが、式場も大体平均すると５日から、ひどいところでは７日待ちという形で聞いてあります。","voiceIndex":57,"id":"exchange-005"},{"speaker":"三上委員","kind":"質問・要望","question":"私のほう、武蔵小山のほうに住んでいると臨海斎場というのはなかなか使いづらい、距離的にもすごくあるものですから、どちらかというと桐ヶ谷斎場のほうに行くケースが多いわけですが。そういうことを考えて、今こういう状況にあるということですから、当然それを想定してスペースをつくってきているだけに、やはり早急に検討すべきだと私は思います。","respondent":"梶戸籍住民課長","answer":"私どものほうも火葬の混み合いの状況とか、品川区民の方が使われている状況等を把握しながら、一部事務組合の５区の中の１つの区ではありますけれども、使われ方の比率は大田区に次いで高うありますので、そういった形できちっとした意見を申し上げていきたいと考えております。","voiceIndex":59,"id":"exchange-006"},{"speaker":"川西委員長","kind":"提案","question":"自由に出入りできますし、どんなふうにしていらっしゃるか伺いたいと思います。それだけ伺えればいいです。それからもう１つですけれど、歩行喫煙防止のことに関連して、長いこと対象地域でないところの区民の方から、のぼり旗だけでも配給してもらえないかという話を承っておりまして、１年も忘れていまして今思い出したんですけれども、そういうことはできるのかどうか伺いたいと思います。","respondent":"中山地域活動課長、秋山協働・国際担当課長、矢部生活安全担当課長","answer":"売れ行きがどうであるとか、イベントをやったときの参加資料とかを含めて、例年との比較も含めた参加人数の報告をいただいておりますが。配食の件ですが、夏休みの件に関しましては区民委員会で３月にご報告させていただいているところですけれども、商店街を活用してということで。のぼり旗につきましてはどうしても風とかの問題もありますので、キャンペーンをやるときにはのぼり旗をそれぞれ持っていただくか。","voiceIndex":61,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今日、こういうことについて調査をしていきたいということで決めるということでしょうか。今日、事務事業概要を伺ったところですので、これを受けてちょっと検討して、次回に意見を出させていただけたらいいなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-008"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2550#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":35223,"voices":69}},{"id":"h21-20090601-7","meetingId":"h21-cm06","date":"2009年6月1日","dateIso":"2009-06-01","committee":"厚生委員会","time":"午後１時０２分～午後３時３９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要を行います。 この事務事業概要につきましては、改選後の初めての委員会で、各所管の事業概要","agenda":"事務事業概要を行います。 この事務事業概要につきましては、改選後の初めての委員会で、各所管の事業概要","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"膨大な量なのでちょっと大変なんですけれども、高齢者福祉の方の冊子からちょっと質問したいんですけれども、最初の５ページの、施策の考え方と課題というところの全体の中に書いてあることなんですが、７ページですか、施設介護のことが書いてあるんですが、団塊の世代が高齢期を迎える平成２６年度を見すえて、施設介護の件で、セーフティーネットとしての特別養護老人ホームの整備ということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回の委員会なんですけれども、新人の方も多いですし、かなり大きな厚い冊子が配られておりますので、これから深めていくためにも、本日の質疑の中で、もう少し率直に、もちろん質問の仕方などは資料の概要にかかわるということは意識してやりますけれども、例えばこの冊子を四つに分けて、それぞれ報告していただいてから、この１冊について質疑を受け付けてというような形でやっていただけると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"それで、年度が変わったところで、例の派遣切りや非正規切りということもありまして、かなりの方、２１万人でしたか、職を失ったという報道も出ておりますが、現在、年度が変わってから生活保護を受けている人が多くなったのかどうか、年度変わりのところの状況がどう変化したのかというのをお伺いしたいのと、あとは説明でありましたけれども、こちらで言うところの１ページですか。","respondent":"平澤生活福祉課長","answer":"大体５点ぐらいかなと思うんですけれども、まず初めに保護の実施状況なんですが、先ほどの事務事業概要の５ページのところでご説明させていただきましたのは、年間を平均しての被保護世帯の動きということになっております。","voiceIndex":45,"id":"exchange-003"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"そういった面で、５７ページの養護老人ホーム、こういうところがたくさんあると経済的な理由の人は入れるのかなと思っているんですが、多分ここでは入り切らないということで、そういった有料老人ホーム、所得の低い人でも入れるというあたりが、どう把握をされているのかなというのをちょっとお伺いしたいのが１点。たまゆらの事件以降、いろいろな方がかかわっているなというところで、教えていただきたい。","respondent":"平澤生活福祉課長、冨岡高齢者福祉課長、本城国保医療年金課長","answer":"今年の４月１４日、厚生委員会で、私の方から無届けと思われる都外施設の数、それから入所されている人数、それぞれ１０カ所。施設の一覧のわかりにくさですが、このまとめ方につきましては、ご指摘の。今回の国保医療年金課の事務事業概要のつくり方の関係で、どうしても国民健康保険、年金、それから後期高齢と、かなり幅が広いところになっておりますので。","voiceIndex":47,"id":"exchange-004"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"高齢者福祉課長に伺ったらいいんでしょうか。もしわかったら教えていただきたい。私はその一言がものすごくショックだったんですけれども、そういった意味の現状把握と、ただ区の施設だけで受けとめるだけじゃなくて、区民の置かれている状況がどうなっているのかという把握がどのぐらいできているのかという意味で、２回になってしまったんですが、お答えいただけたらと思います。","respondent":"木下健康福祉事業部長","answer":"そのときに、一般の有料老人ホームと同じような規制では、多分現実的ではないだろうということで、このようなことも踏まえながら、これはまさに国、都道府県段階で十分検討していただきたいと私どもの方も思っているところです。","voiceIndex":51,"id":"exchange-005"},{"speaker":"飯沼副委員長","kind":"質問","question":"５７ページの養護老人ホームというのは、これはもうつくらないということですか。今の部長のお話では、今後はつくられるものではないと。これはどこに該当するものですか。ちょっとそこだけ教えてください。","respondent":"冨岡高齢者福祉課長","answer":"これは都の方でつくっているところでございまして、福祉法人ですね。申請された方は、区として措置をするという流れになっておりまして、傾向としては減っている状況です。","voiceIndex":53,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"先ほど、違う質問の答弁の中で、品川区がなぜ捕捉率が低いのでしょうかということの中で、今年は派遣村などで千代田区で大きな申請もあったからというような話もあったんですが、前の年から比べても、経年的に見ても、東京都の平均に比べると、昨年も同じような状況なので、それは品川区が低い理由にはならないんじゃないかなと思いますので、そこら辺、どうして品川区で捕捉率が低い原因というか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-007"},{"speaker":"金野委員","kind":"確認","question":"新型インフルエンザに関してご説明いただいた件で、ちょっと確認をさせてください。今後の対策としてどこまでするよう、その働きかけの仕方というのでしょうか、そこの確認をさせてください。","respondent":"吉田品川区保健所保健予防課長","answer":"必要な方に必要な診断、あるいは治療をといったことに基づきますと、ある一定の、発熱外来を開設している医療機関では実施ができるわけですが、その他の医療機関につきましては、発熱相談センターでご相談を受けても大丈夫ですということでお伝えしていますので。","voiceIndex":65,"id":"exchange-008"},{"speaker":"金野委員","kind":"質問","question":"妊婦さん、それから特別な内臓疾患のある方がこれにかかると非常に重症になるということですが、その方々に対してはどのような。いわゆる発熱センターで症状を聞いて、そして必要であればというところなんでしょうけれども、その方の近くに高熱を出されている方がいて、心配だ、熱が上がってきそうだというようなところでの事前の対応というのはどうなんでしょうか。","respondent":"吉田品川区保健所保健予防課長","answer":"今後、地域等で流行が広がってきた場合どうかといったことになりますが、地域の医療機関と検討を進めて、妊婦の方、あるいは各種疾患をお持ちの方につきましては、比較的早期に投薬していただくといったことも含めて相談を進めてまいりたいと考えています。","voiceIndex":67,"id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"発熱相談センターには保健師がかなり集まっているということなんですけれども、そこの体制がかなり厚くなっていると思うんですけれども、保健師の体制として大丈夫だったのかなというか、数の面で足りているのかということをお伺いしたいのと、学校の休校ですとか、あるいは修学旅行の中止ですとかがあったと思いますし、区の方でも国際友好事業の。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-010"},{"speaker":"安藤委員","kind":"確認","question":"ではちょっと確認なんですが、そういった新型インフルエンザの拡大を防ぐ上で、休校ですとかイベント中止という様々な措置が実際にとられたし、全国でもとられたわけですけれども、そういったところで、特に区が主催するイベントを中止するか、中止しないかという判断は、保健センターで出すわけじゃないということなんですか。それに関しては保健センター、保健所の管轄外ということなんでしょうか。","respondent":"吉田品川区保健所保健予防課長","answer":"ご指摘の内容につきましては、すべて、新型インフルエンザ対策危機管理対策本部の会議で、区長以下ですべて検討して決定しているとこです。決して保健部門だけで決定していることではございません。全庁的に対応していることです。","voiceIndex":74,"id":"exchange-011"},{"speaker":"飯沼副委員長","kind":"質問","question":"発熱センターは庁内に１か所設置をされているわけなんですけれども、発熱外来を受けとめている病院が幾つあるのかというところと、入院設備が何床ぐらいあるのか。今は微増ですよね。早く終息してほしいなと願っていますが、もし広がっていったときのそれぞれの対応というのは、さっき言ったように指示がおりてくるまでというか、区独自の体制がとれるのか、その辺もちょっと教えてください。","respondent":"吉田品川区保健所保健予防課長","answer":"発熱外来のベッド数、あるいは開設医院数ですが、実は、今公開してしまいますと、患者様がそこに集中するといったことで、場所も含めてすべて非公開といった形になっております。ただ、現状では十分そこで対応できるという形になっています。何カ所かも非公開になっております。","voiceIndex":77,"id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3236#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":46171,"voices":80}},{"id":"h21-20090601-8","meetingId":"h21-cm06","date":"2009年6月1日","dateIso":"2009-06-01","committee":"建設委員会","time":"午後１時０２分～午後２時４０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を7件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１番目、幹部職員紹介","agenda":"の１番目、幹部職員紹介","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"都市環境事業部のほうでの景観行政団体のところで、景観行政団体として都に申請しますというのは、随分以前にお聞きしたんですけれども、ここで出されているのを見ると、平成２１年度以降に、例えばパブリックコメントをやりますとか書かれているんですけれども、かなり以前の段階で申請が行われたということではなくて、これからという問題になっているんですか。ちょっとそこだけ教えていただきたいんです。","respondent":"藤田水とみどりの課長","answer":"同意を取るためには、正式に協議書を提出する前に、事前協議ですとか、いろいろ手続があります。今、その手続をしているところで、この経過の中で読みにくいんですが、一応、平成２１年度、行政団体になりたいということで、今、進めているところです。","voiceIndex":47,"id":"exchange-001"},{"speaker":"藤原委員","kind":"質問","question":"簡単にお伺いしますが、せっかく組織改正したのに、と思うことがあるんですけれども、公園に関してお伺いしたいんです。聞いていると、公園のことが、改めて土木管理課にも出て、道路公園課にも出て、都市整備下水道課にも出てきますが、もっと簡単な仕切りというか、何課が公園の何をするとか、まず、教えてくれますか。","respondent":"松代都市計画課長","answer":"そういったものを、今回、二つに分けた大きな分け方で言いますと、防災まちづくり事業部のほうで担うのは、主に公園を計画し、つくるほうのハードの部分。都市環境事業部のほうでは、その財産を管理し、日常の維持管理をする、そういう大きな分けを、今回、しております。","voiceIndex":49,"id":"exchange-002"},{"speaker":"藤原委員","kind":"質問","question":"今度の組織改正は、区民にわかりやすくということが入っているわけですよね。せっかく道路公園課というものがあるのに、わざわざ分けなくて、道路公園課が設計もし、管理もしという形で一本でやっていったほうがいいのではないか。わざわざ部を越えて変える必要が何であるんですか。せっかく道路公園課というのがあって一本にしていたのに、分ける必要って全くないと思うんですけれども。","respondent":"岩田防災まちづくり事業部長","answer":"これが一つの課長の中に存在しますと、あいまいに、もめないようにということで、妥協のものしかできないということで、東京都も、私どもも、つくるほうと、維持管理するほうは、基本的には分けるという考え方で組織を維持しております。","voiceIndex":51,"id":"exchange-003"},{"speaker":"武内委員","kind":"提案","question":"今のとちょっと関連するかもしれないんですけれども、今回、組織改正で、維持と設計を分けたことによって、妥協性というか、そういういい面もあると。我々も、正直言って、今まで何かを提案するときにも、実際に戸惑っているんですね。","respondent":"家壽田都市整備下水道課長、岩田防災まちづくり事業部長","answer":"これはすべて大きなメリットと考えておりまして、それぞれ道路が持っていたもの、公園が持っていたもの、下水道が持っていたもの、これを今、融合させまして、それぞれブラッシュアップするという意味では大変大きな効果があると。そういう面では、区民のからの直接の陳情というのは、下手をしますと、一つの課だけではなかなか解決しないようなケースも最近は多いものですから、委員からの陳情は、部の庶務担当のほうで一通り受けさせていただいて。","voiceIndex":53,"id":"exchange-004"},{"speaker":"武内委員","kind":"質問・要望","question":"きのう、すごい雨だったですね。私も、たまたま外に出ていたので、３０分ぐらいの間にびしょびしょになってしまったんです。あれでどの程度で水の被害が出たのか、被害が出るまでに至らなかったような気はするんですけれども、それでもかなりひどかったんです。その辺のことが、もし何か被害が出ているとかあれば、教えていただきたいんですが。","respondent":"中山防災課長","answer":"特に被害は出ておりません。","voiceIndex":58,"id":"exchange-005"},{"speaker":"菊地委員","kind":"提案","question":"先日の初めての委員会のときに、委員長から、なるべく早い時期に、視察先について、ということがあって、今の委員長の提案は、そのことと密接に関連をしているのかなと思うんですけれども。今の委員長の提案は、例えば、次回の委員会で、そういう話をしますということなのか、それとも、文章でということなのか、ちょっとその辺を。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":62,"id":"exchange-006"},{"speaker":"伊藤委員長","kind":"提案","question":"提出されたテーマにつきましては、資料等の準備なども含めまして、当然、調査可能であるか、その内容については、正副委員長と理事者で十分に調整をさせていただいて、今期の建設委員会の限られた日程と、委員と理事者の関係の中で、非常に有効な委員会運営として導いていくための課題を設定していきたいと考えていますので、まずは材料となるものを、皆様からご提案していただきたいと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-007"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3946#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":33090,"voices":64}},{"id":"h21-20090601-9","meetingId":"h21-cm06","date":"2009年6月1日","dateIso":"2009-06-01","committee":"文教委員会","time":"午後１時０４分～午後３時５０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"本間委員","kind":"意見","question":"民主品川の本間隆です。どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"意見","question":"共産党の中塚亮です。どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":8,"id":"exchange-002"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"井上委員","kind":"提案","question":"それから２１ページのすまいるスクールのところで、今年度、ちょっと内容になってしまうかもしれないんですが、新規で市民提案事業のところで、放課後の障害児の方々の提案をされたと思うんですけれども、それがちょっとご報告がわからないので、どういうところでそれをしてきて、どこかの団体になったようなうわさを聞いたので。","respondent":"和氣小中一貫教育担当課長、田村庶務課長、冠木指導課長","answer":"１点目の学力定着度調査の件ですが、連携グループの中で、指導がうまくやれているのかということで、連携グループ独自で問題をつくって。私のほうからすまいるスクールに関係するご質問にお答えします。委員ご質問の四つ目の教育センターの予算の件ですけれども、ここに書いてある３,７５７万９,０００円につきましては、教育センターの運営費。","voiceIndex":32,"id":"exchange-003"},{"speaker":"井上委員","kind":"意見","question":"すまいるスクールのところで、３８校のところで、ぴゅあ・さぽーとが１校受け持つということは、ほかの委託と同じ形でぴゅあ・さぽーとが委託事業者として契約がされたという意味なのか、ちょっとそこがよくわからない。","respondent":"田村庶務課長","answer":"残りの学校、ぴゅあ・さぽーとを除いた学校は、総合評価として順位付をして委託をしました。ぴゅあ・さぽーとについては先ほど実績や体制等も既に実績があるということで、特命随契ということで委託した、そのようなことです。","voiceIndex":36,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"グループと一言で言って、いろんなグループの種類があると思うんですけど、そういったところでイメージがつかみにくかったので、その目的とどういう事業なのか、もう少し中身を教えてください。それと、今年の事務事業概要の教育目標とそして基本方針とありますけれども、今年、今回というか、変更した点というか、考え方といいますか、そこを教えていただけますか。","respondent":"市川教育次長、和氣小中一貫教育担当課長","answer":"私のほうから教育目標と基本方針についての変更点ですけれども、大きな変更点は、先ほど冒頭に申し上げましたが、従来の生涯学習課で所管しておりました多くの事業が区長部局のほうに移管されたことに伴いまして。連携グループ、確かにおっしゃるようにさまざまな形態がありますので、そこに応じてその連携の中でどう学力を伸ばすことができているかどうかということを確認するためのテストを独自につくって実施するです。","voiceIndex":38,"id":"exchange-005"},{"speaker":"中塚委員","kind":"意見","question":"教育目標、基本方針のほうについてですけども、区長部局への移管のところが変わったということと、学校教育は従来と大きな変更がないというご説明だったと思うんですけれども、今までというか、去年の基本方針を見ていますと、冒頭、人権尊重の推進と社会貢献の精神の育成についてというところで、「教育は、日本国憲法および教育基本法の精神に基づき。","respondent":"市川教育次長","answer":"先ほどご指摘になった点は、当然の前提と言えばそれまでのことですけども、特に品川区教育委員会の教育目標であり、基本方針であるということを意識して表現に手を入れた経過があります。","voiceIndex":41,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"正直、説明がわからないんですけれども、過去の事務事業をずっと見ておりましても、日本国憲法の精神に基づき尊重云々と記述されていて、今回からなくなったものですから、その理由が、今の説明じゃよくわからなかったので教えていただきたい。それと、今までずっと掲げられていたと思うんですけれども、その辺はどうなんでしょうか。全部の資料をひっくり返したわけじゃないんで教えていただけますか。","respondent":"市川教育次長","answer":"当然我々にとっては法令遵守義務というのは課せられているわけです。それよりも、この基本方針の中で、品川区の教育委員会がどういうことを述べ、それを伝えたいか、そこのところに考えを至らせたものだということは先ほど申し上げたとおりです。","voiceIndex":43,"id":"exchange-007"},{"speaker":"中塚委員","kind":"確認","question":"特段の意図はないというお話でしたけども、品川区の人権尊重宣言もそうですし、権利だったり人権だったり、基本的人権について、憲法でも平和のうちに生存する権利を有することを確認すると。もちろん公務員の方々ですから、入区の際に日本国憲法の尊重の宣言をしていると思うんですけれども、その辺をどんなふうに理解しているのか。","respondent":"市川教育次長","answer":"それに向けて、私どもの姿勢をこの基本方針の中でうたったわけでございまして、それが私どもは何を踏まえて、何に基づいてというよりは、私どもが伝えるべきことは、私どもは何を行うということを伝えることが先ほどから申し上げているとおり私どもの姿勢であり。","voiceIndex":45,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"連携を図っていくということだと思うんですけれども、ここの位置づけというのは今後どういうふうになっていくのでしょうか。例えば子どもに関係することというのは、多分私たち委員が議論していかなければならないのかなと思うんですが、そのすみ分けをどういうふうにとらえていっていいのか、その考え方を少し整理させていただきたいなと考えています。いかがでしょうか。","respondent":"冠木指導課長、田村庶務課長","answer":"今後いろいろと検討していく中で、入学時の小学校教育の充実に関することであるとか、あるいは保育園、幼稚園、それから小学校の先生方がともに研修していく場の検討とか、いろんなこれから検討してまいりますので。先ほど事務事業概要で庶務課の事務事業をお話ししましたが、ＰＴＡの関連事業にしても、あるいは校庭開放の事業にしても、やはり文化とスポーツとの関連というのは、必要不可欠で切れる関係ではありませんので、所管は決まりましたが。","voiceIndex":47,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"検討の中で、他の所管に踏み込んでしまうかもしれないんですが、よろしくお願いします。それから、保・幼・小になったんですね。幼・保・小とずっと聞いていたような気がするんですけど、保・幼・小というふうにしたのは何か意味があるんでしょうか。","respondent":"冠木指導課長","answer":"０歳児から保育園のほうがありますので、年齢順です。","voiceIndex":50,"id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"それは年齢順ということなんですね。公立幼稚園よりは、圧倒的に私立幼稚園のほうが多いわけですから、そういう場合に今度どういうふうになっていってしまうのかなというふうに思うんですが、私たちの感覚として幼稚園というくくりになったときは、公立プラス私立ということのとらえ方でいいのか、それは別々に考えていったほうがいいのか、ここはいかがでしょうか。","respondent":"冠木指導課長","answer":"今回の検討委員会の考え方としまして、区立の幼稚園、保育園、公立のですね、それから私立の幼稚園、保育園、それぞれの園長先生方の代表の方に委員会に入っていただいて、品川区全体として検討していきましょうという趣旨ですので。","voiceIndex":52,"id":"exchange-011"},{"speaker":"浅野委員","kind":"質問","question":"指導課のほうにちょっと記載がなかったので、指導課のどこの部署と連携されるのかなということと、あと、学校の教育自体にそのＩＣＴを活用されるということを今後検討されると、たしか予算特別委員会のときにお答えいただいたかと思うんですけれども、こちちのほうは具体的にどこの部署がそういうことを検討していくのかなということをお伺いします。","respondent":"富田学務課長","answer":"平成２３年７月ですか、地デジの問題等々もありますので、こういったところをあわせてどのように整理をしていくかということについて、指導課、学校と学務課と調整を図りながら計画をまとめてまいりたいと考えています。","voiceIndex":54,"id":"exchange-012"},{"speaker":"林副委員長","kind":"質問","question":"我々の耳に入ってくる部分では。ですから、品川で誇るべき小中一貫を世に問うているわけだから、それはそれで謙虚に考えるところは持つべきだろう、それは指摘をしておきます。品川区からヘッドハンティングをされた教育長の幼保小中一体型、１５歳までの子どもの健全教育を品川区の教育長の向こうを張ってやっているわけですから、そういうところの部分も品川区の教育委員会は私は見るべきだと思います。","respondent":"若月教育長","answer":"今、副委員長のほうから幾つかご指摘がありました。ご指摘はもちろん我々謙虚に受けとめようと思うわけでありますが、まず小中一貫教育というのは平成１８年から始まったものでありまして、今始まって４年目をいよいよ迎える段階であります。","voiceIndex":56,"id":"exchange-013"},{"speaker":"井上委員","kind":"質問","question":"一番最初に、子ども未来事業部長からお話がありました、９ページの地区別施設というような考え方なんですけれども、縦割ではなく横串を刺された、そういうところでは今後の課題も出てくる、進めながらということで、どういうふうに考えているのかちょっとよくわからないんですが、こういう計画をされた中で、メリットとデメリットが。","respondent":"古川子ども未来事業部長","answer":"なかなか説明だけでは十分でなかったかもしれませんけれども、従前から保育園、幼稚園施設は区内を６ブロックに分けまして、課長は保育課長１人でありましたけれども、６ブロックにそれぞれ担当する園長を示しながら、かなり地域に展開した保育園。","voiceIndex":65,"id":"exchange-014"},{"speaker":"井上委員","kind":"意見","question":"一つに、子どもたちが公立、区立の保育園、幼稚園ではなく、品川区の場合は私立の幼稚園が相当な数、ここで過ごされて、結局公立の小学校に上がるという部分では、連携をされていくべきで、この表の中にそういう考え方が暗に示されているとは思いますけれども、そういう意味で、こういう図の中に連携を、もちろんとるということはわかるけれども。","respondent":"古川子ども未来事業部長","answer":"そういった意味では、地域の資源としては多様なものがありますので、これはあくまでも公立、そして子ども未来事業部が所管する施設ということで限定的な表というふうにご理解いただければ大変ありがたいなと考えております。","voiceIndex":67,"id":"exchange-015"},{"speaker":"井上委員","kind":"質問","question":"もう一点は、６７ページの次世代育成支援対策事業のところなんですけれども、区がこれから後期行動計画を立てるに当たりまして、年齢ですね、何歳までの次世代の子どもたちというふうに考えてとらえていらっしゃるのかということが１点と、本来ここ２年で後期行動計画は来年には策定されなければいけないので、本来であれば。","respondent":"小林青少年育成課長","answer":"任期等の関係ですが、これは委員の任期を２年間と定め、必要に応じて更新をかけていくということで、少なくとも５年すべての任期を一律カバーするというふうには考えておりませんので、適宜人材の適材適所、登用という点で更新を含めて対応してまいりたいと考えております。","voiceIndex":69,"id":"exchange-016"},{"speaker":"井上委員","kind":"質問・要望","question":"そういうことであれば、今回前期行動計画の進捗状況のチェックをしている同じ方たちが、そのまま充て職といわれる方たちは替わっていますけれども、そういう意味で同じ方でしたので、そこが本当に機能したかどうかということを評価しながら今後のことですのでぜひ検討していっていただきたいということは要望させていただいて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"子ども未来事業部の事務事業概要について教えていただきたいんですけど、基本構想、長期基本計画、総合実施計画となってきて、その１年目ということですか。今後１０年間の区政運営を示した長期基本計画と平成２１年度の事務事業概要との関係、位置づけについて教えていただけますか。","respondent":"古川子ども未来事業部長","answer":"長期的な計画展望あるいは短期的にやっていくものについては当然のことながら、この事務事業概要にお示しした各事業の中にそれぞれの実施時期、実施内容については毎年度事務事業の検討そして予算の編成、そういう中で明らかにしていく、このように考えております。","voiceIndex":72,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"伺いたいのは、保育園待機児童の解消とは、まずこの１０年間で何を目指す計画なのか、それを教えていただきたいのと、あと具体的に今年度、平成２１年度の事務事業にどんなふうに具体化されているのか、ご説明いただけますか。","respondent":"吉岡保育課長","answer":"待機児童の解消のご質問ですけれども、従来からお答えを何回かさせてきていただいておりますけれども、待機児の解消につきましては、さまざまな方策に基づきまして、例えば幼保一体施設の開設、あるいはまた認証保育所の誘致。","voiceIndex":74,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"私が伺ったのは、まず長期基本計画の中で保育園待機児の解消とあるんですけれども、ではこの１０年間で何を目指すということなのかを聞いているんです。単刀直入に言えば、減らすのかゼロにするのか、どう考えているのか。何を目指しているのか。それと、この事務事業概要の中に、それはどう具体化されているのかというのも伺いたい。それがなぜかということです。ご説明いただきたい。","respondent":"吉岡保育課長","answer":"それで、１０年間の計画ですけれども、長期基本計画あるいは実施計画につきましては、一定の計画スパンを持って、この計画の中に計画期間内においての目標を示しているものですけれども、事務事業概要につきましては、単年度。","voiceIndex":76,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"待機児解消に向けて、この１０年間で一定のスパンを持って何を目指しているのかという、そこを伺いたい。２３区の中でも幾つかの自治体で緊急に保育園整備が始まっていると伺っている。形はいろいろあるそうですけれども。保育園の待機児解消に向けた緊急対策、今何か考えているのか、いないのか教えていただきたい。","respondent":"古川子ども未来事業部長","answer":"事務事業概要にどこまでどういう内容を織り込むかということに関連してくると思うんですが、私どもの上位計画としての長期基本計画、そして複数年次の実施計画をさらに定め、具体的な事務事業概要の中で一定の事業のご説明をするですので、それぞれ個別に足りている。","voiceIndex":78,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に部長に伺いたいのは、この子どもに関する施策の考え方というのは、今の子どもたちがどういう状況に置かれているのかというのを全体の考え方を示しているわけですよね。今の不景気の中で家庭が置かれている現状をどんなふうに見ているのか、今後何が必要だと思っているのか、何を検討すべきなのか、そこはしっかりお考えを聞かせていただきたいと思いますけど、いかがでしょう。","respondent":"古川子ども未来事業部長","answer":"つまり、就労のために保育園を必要とする方もいらっしゃいますが、そうではない環境の中での就労支援というのも当然ありますので、認可保育園だけではない、さまざまな多様な手法を講じながらそれぞれの需要にこたえていきたい、こういうことです。","voiceIndex":80,"id":"exchange-022"},{"speaker":"西本委員","kind":"質問・要望","question":"多分この広がりで言うと、地域センターであるとかというところをひっくるめて関係が出てくるような事業なのかなというのがありますが、将来像、今年はそこまで行かないとは思いますけれども、地域をそういう形で見ていきたいというふうなお考えでのことなのか、それから今年は児童センター、幼稚園、保育園、児童センターということがありますけれども。","respondent":"古川子ども未来事業部長、安井子育て支援課長、吉岡保育課長","answer":"したがいまして、地域センターにその根拠を持ったわけでございまして、今回、青少年対策地区委員会につきましては。父子福祉の問題ですけれども、なかなか母子福祉のほうについては。緊急一時保育についてのご質問ですけれども、こちらは１７ページの一番上の段にもお伝えしていますとおり。","voiceIndex":82,"id":"exchange-023"},{"speaker":"西本委員","kind":"質問・要望","question":"これからおいおい委員会のほうでご要望していきたいと思いますけれども、緊急一時保育については非常にいい制度だと思っていますし、地域の人材にお願いするという意味では、やはり品川区も以前やっていたこともありますので、そういうのも見ていただきたいなというふうに思っております。それから、父子家庭なんですけれども、お父さんだからいいだろうということではないと思うんですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-024"},{"speaker":"林副委員長","kind":"質問・要望","question":"さっきもちょっと言ったように確認だけさせていただきたい。教育委員会としては、おこがましい名前じゃない。そういうことについては、まるっきりこれには書かれていないんだけど、やってくれるんだろうねという念押しを、どっちの、教育委員会でも子ども未来事業部でもいいんだけど、そういうことはやっていくんだろうねということを確認しておきたいんですけれども、どちらからでも結構です。","respondent":"吉岡保育課長、市川教育次長","answer":"しかしながら、品川区の保育士として品川区の子どもたちによりよい保育を目指していくという立場では全員一致しておりますので、考え方は考え方といたしまして。副委員長からお尋ねのあった件は、先ほど教育委員会の事務事業の説明の中で保・幼・小の連携、その一たんを申し上げましたけれども、片やただいま子ども未来事業部のほうからも説明がございました。","voiceIndex":87,"id":"exchange-025"},{"speaker":"井上委員","kind":"質問","question":"中学校１０校のその延期に対する今後の対応と、この期間で関西方面ではない修学旅行の実施校というのはあったんでしょうか。","respondent":"冠木指導課長","answer":"今後ですけれども、今１０校の校長には延期ということを前提にして代理店等との調整に入っていただいているところです。今のところ、延期できないという報告は入っておりませんで、１０校とも延期で実施できる見込みです。","voiceIndex":95,"id":"exchange-026"},{"speaker":"井上委員","kind":"質問","question":"もう一つ、この間に修学旅行をこの時期実施した学校というのは、中学校、延期の中のほうじゃなくて、実施した学校があるんでしょうかというのが一つと、今の延期ということで対応していただけるということは、別に子どもたちの負担とか学校の負担とか、そういうものに対する、国もそういった補助を出すようにというような働きかけもあるようですが、財政的なもので区が支援しなければいけない状況なのか。","respondent":"冠木指導課長","answer":"今委員のほうからお話がありました国のほうの対応策を報道の中で聞いておりますけれども、まだ今のところ具体的な通知が来ておりませんので、それをまた見ながら検討してまいりたいというふうに考えてあります。","voiceIndex":97,"id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"今、６月１２日までということなんですが、７月もありますよね。多分このままいくと、７月実施予定の学校も延期というふうにせざるを得ないのかなという部分もあると思うんですね。延期といいましても、状況によりますから、ただ大体９年生ですよね。９年生というのは受験が絡んでくるんですよね。そうなると、教育委員会の中でもそういう検討の時間も必要なんじゃないかと思いますが、いかがでしょうか。","respondent":"市川教育次長","answer":"こうしたことも含めて、子ども自身もそうですけども、子どもを送り出す保護者の心情ということ、それを考えて延期という決定をしたものですので。","voiceIndex":99,"id":"exchange-028"},{"speaker":"中塚委員","kind":"質問","question":"新型インフルエンザ、私自身もこういう広がりというか事態というのは、正直はじめてでありまして、何をどういうふうに対応していったらいいのかわからない中でのかなりのこわさという感じなんですけども、今後まだどうなるかなかなかわかりませんけど、この間の取り組みの中で、どこかの時期を見て、国の対応、都の対応、品川区の対応、それぞれやっぱり問題点の抽出だったり、課題の整理だったり。","respondent":"市川教育次長","answer":"いわゆる危機管理については、区としての危機管理ということでこの間臨んできておりまして、その中では、個々の行政分野を預かっている私どもなり、あるいはそれぞれの事業部が対応してきておりますけども、ここはやはり。","voiceIndex":101,"id":"exchange-029"},{"speaker":"西本委員","kind":"質問・要望","question":"後ほど委員長のほうからお話があるかわからないんですが、前回の文教委員会の中で継続審議が決まっている請願があると思うんですね。いつになるかは、正副委員長で考えていただきたいと思うんですけど、私と中塚委員はいますから大体わかっているんですけど、ほかの委員はそういう形になっていると思っていない部分があると思うので、そういう案件もありますよということはご紹介いただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-030"},{"speaker":"堺委員長","kind":"提案","question":"はい、わかりました。今、西本委員からお話がございました継続となっている請願についてどうするのかという件ですが、この件につきましては、今年の２月１９日請願として受理いたしました、区立城南第二小学校特別支援学級の存続を求める請願、この件だと思います。特にほかにないようですので、今後の委員会の運営について、私のほうからご提案をさせていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":105,"id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4670#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":51417,"voices":106}},{"id":"h21-20090601-5","meetingId":"h21-cm06","date":"2009年6月1日","dateIso":"2009-06-01","committee":"総務委員会","time":"午後 １時０４分～午後 ３時１９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"まとめてからと思ったんですけれども、とりあえずちょっと１点聞きたいんですけれども、会計管理室のところの金融機関調査会は、昨年度は２回開催と伺ったんですけれども、これは定例で行っているんでしょうか。今、かなり世界的な状況も変わってきているので、開催の考え方というんですか、どういう考え方で行われているのでしょうか。","respondent":"福田会計管理者","answer":"年２回といいますのは、一昨年を振り返りますと、一昨年は年に１回でございました。昨年度はああいう世界状況もございましたので、定例ではございませんでしたけれども、２回、念のために、できるだけ直近のデータに基づきまして、金融機関の状況を分析したというものです。","voiceIndex":56,"id":"exchange-001"},{"speaker":"宮崎委員","kind":"質問","question":"金融機関の指定のところでは、現在、みずほ銀行を指定しているんですけれども、仮に例えば変更等の必要があるとなった場合、その手続だとかというのはどういうふうにしていくのか、どこで判断していくのか、どういう手続があるのかということについてはいかがでしょうか。","respondent":"福田会計管理者","answer":"手続といたしましては、まず形式的には公募をするということになってまいります。これは法律に基づくものではありますけれども、一種の契約ですので、当該指定金融機関と当該区とが一定の合意をする。その上で議会にお諮りをしてご議決をいただき、さらには告示をする。","voiceIndex":58,"id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問","question":"その公募する前の段階での、これは公募しなければいけないなという判断というか、それはさっきの金融機関調査会というところがやっていくのか、どうなんでしょうか。","respondent":"福田会計管理者","answer":"金融機関調査会で指定金融機関がどうかということにつきまして、これは判断することはおそらく必要ないだろうと考えております。これは先ほど申しましたように法に基づく制度です。","voiceIndex":60,"id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１点、もう１点は中に入っちゃいますのでやめますけれども、１点だけ教えていただきたいんですが、組織改正がありました。それは変わったんだけれども、あれはあくまで内部的なことであって、我々は内部的だからそういうふうになったよというだけを理解しろというのか、これで見る限り何もそういうものがないわけで、議会はどういうふうに改めて我々は理解しておけばいいのかというところだけ教えてください。","respondent":"本間副区長","answer":"そういう意味で、内部での位置づけ等の重要性に鑑みて、会計管理室をいろいろな部分でトップに持ってきて、この４月１日から対応しているです。","voiceIndex":64,"id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問","question":"それはこれを読んでいて何となくわかるんですね。それは事業部が、例えば事業部長、企画部長、各部長の、例えば取りまとめというか、トップクラスとしてご意見を伺ってもいいのか、我々だけにね。そういうところの位置づけがわからないと、内部、内部と言われていても、我々にわかるようにご説明していただかないと、どういうふうにしたらいいのかなというのがわからないなと思って。","respondent":"本間副区長","answer":"それを一般職の事務職に置きかえるという法改正がなされましてそのようにしたわけですが、運営していく中で、この公金管理等々の先ほど言ったような意味から、会計管理室の重要性に鑑みて今回のような位置づけになったですので、非常にすっきりしない、身分も一般職ですし。","voiceIndex":66,"id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問","question":"この話はやめておきます。そのいろいろな問題というのは何ととらえられているのか、我々もいろいろさまざまな問題があると思っているんだけれども、それがあまりに認識の違いがあると、我々も応援をするときに違う方向の応援をしてもしようがないなと思ったので、それがわかれば教えてほしい。","respondent":"日下部企画部長","answer":"これはどちらかというとちょっと部分的な課題になろうかと思いますけれども、いずれにしろそういう形で大きい問題、ちょっと小さめの問題とありますが、このような形で今後とも財調をめぐる課題というのは横たわっておりますし。","voiceIndex":68,"id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問","question":"全部ただ上げた中で、先行だけさせちゃおうなんていうことになってくると、何でもいいからとりあえず配分を先に取っちゃおうというと、そこの換算が本当にできるのかなというすごい心配をしているんだけれども、そういうことも起きてきちゃうんじゃないのかなとすごく不安を感じているんだけれども、そこら辺の感覚がもし違うとか、思いがあるなら教えてもらいたいなと思います。","respondent":"金子企画財政課長","answer":"そういう状況になったという経緯がありまして、都区間で協議をいたしまして、これが本当にそれでいけるのかどうかというなかなか難しい面がありますが、逆に最後にお金の問題をきちんと整理をしようじゃないかという形になったという経緯があります。","voiceIndex":70,"id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"意見だけ。今の１２年の反省で財源を最後にしようというのはすごくわかっていて始まったんだけれども、現実２年間であまりにもそこが進まなかったわけじゃないですか。それが必ず今年中にはそこはやる話になっちゃうような気がしてならないので、ぜひそれをしっかり注視していただきたいなと、これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-008"},{"speaker":"宮崎委員","kind":"質問・要望","question":"１点だけ聞かせていただきたいんですけれども、同和のところで１点だけ伺いたいんですけれども、総務部の事業概要では差別解消に向けた啓発ということで位置づけられているんですよね。前は１人同和相談員を配置しているということを聞いていたんですけれども、同じような体制なのか、そこら辺のところはどうでしょうか。","respondent":"中山人権啓発課長","answer":"同和生活相談についてのお尋ねですが、現在は同和生活相談員１名ということで運営をしているところです。年間２５０件ぐらいのご相談を受け付けております。","voiceIndex":73,"id":"exchange-009"},{"speaker":"宮崎委員","kind":"質問","question":"もう１つは先ほど言ったんですが、基本的には総務部のところでは啓発活動なんだということなのかな。それで相談がある。もう一方では、企画部のほうでは区民相談というのを持っているわけですね。ですから、啓発を全部やるのか、それとも何でもやるよというのかどうなのか。","respondent":"中山人権啓発課長","answer":"男女のほうはうちのほうで持っておりますので、男女のことに関する相談は人権啓発課のほうでやっているところです。","voiceIndex":75,"id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問","question":"それとあと今、年間２５０件という話だったんですけれども、人権というのはある意味では同和も全部オールマイティーでやれるよというふうになるんじゃないかなと思うんですけれども、あえて分けるというんですか、その意味がよくわからないのと、啓発というふうになっていて、いろいろな行事のときに合わせて相談もやりますよというのは。","respondent":"中山人権啓発課長","answer":"相談というのは心を開いて話せるようになるまでが大変だと思うんですが、そういう意味では、中身をわかってくださっている、理解をよくしてくださっている人に相談をしたいということで、実際、件数としても上がっておりますし。","voiceIndex":77,"id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問・要望","question":"実際問題、この２５０件と言われるんですけれども、中身はなかなか見えないんですね。具体的に品川区として本当にやらなければいけないのかどうかというところは、私どもによく見えないんですね。見に行くこともなかなかできないということで。今の説明だと本当にこの品川でどれだけ必要なのか。私は今までも言ってきていますけれども、見直しということを求めていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-012"}]},{"id":"topic-02","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ちょっとこれだけ教えていただきたいんですけれども、今、危機管理の会議の中で、中学校の修学旅行の延期等もしたと。延期したところもあると。基本的に延期はいいんだけれども、ゴーを出すのは、どこがゴーを出すんですか。危機管理室、連絡会議、学校、そういう決まりって、ゴーを出すほうね。延期はいいんだけれども、ゴーを出すというのはどこと我々は理解すればいいんですか。","respondent":"市岡総務部長","answer":"これを解除する場合には、まず危機管理体制を一たん解除した上で、その判断に基づいて、学校の修学旅行の実施ということは教育委員会の権限ですので、前提となる危機管理体制についての本部の判断をもとにして、教育委員会が判断するということになろうかと思います。","voiceIndex":85,"id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"意見","question":"今の話だと危機管理対策本部の考え方だという。だけどあくまでも判断するのは学校ということで、どうしてこういうことを聞くかというと、延期になったところがもう１回予約をしようといって動いているんです。９月ごろからやろうと。非常にいいんだけれども、それでまた９月ごろを予定しているから予約が取れないとか、かわいそうな面もあるんだけれども、そういうことを考えると、とめたのはいいんだね。","respondent":"市岡総務部長","answer":"そういう事態になりましたら、そういう段階になりましたら、全庁挙げてきちんと責任を持って、児童・生徒、学校、保護者の方々にご理解いただけるような、安心していけるような体制にぜひとも進めていきたいと考えております。","voiceIndex":87,"id":"exchange-014"},{"speaker":"須貝委員","kind":"質問","question":"その中でこの教訓はいろいろなところを発見できた、もっとこういうところをやっておいたほうがよかったんじゃないかとか、そういうところも多々あらわれたと思いますので、ぜひ今後それを生かして、よりよい危機管理対策をやってほしいと願っています。そうしたら、中で今度一つの密室ですから。役所、学校、それぞれ区の施設は密室ですから、その辺に対して、やはりできるだけの対応策も必要なのかなと。","respondent":"伊勢総務課長","answer":"啓発活動をいろいろやっておりまして、今でも動いているわけですけれども、一定の時期にこれがよかった、これが悪かったと、事態がどんどん進んでいる中ですけれども、我々もこれから検証して、秋に変化するかわかりませんけれども、それに備えて考えていきたいと考えています。","voiceIndex":89,"id":"exchange-015"},{"speaker":"宮崎委員","kind":"質問","question":"今回は弱毒性だったということで、こちらのほうも安心というか、そんな感じだったんですけれども。そういうところだと思います。そういうところで、実際問題、例えば区としてやるのか、あるいは東京都、あるいは国でやるにしても、品川区の場所でどういう体制をとっていくのかというのが何かあったのかなというのがちょっと心配なんですけれども、そういうのは実際にあるんでしょうか。あったんでしょうか。","respondent":"市岡総務部長","answer":"当然感染の広がりとか感染のルートという点で考えますと、一品川区とか一何々区の問題ではなくて、どういう人の動線があるかということを考えなければいけませんので、実は平成１８年に保健所のほうで品川区としての行動計画、それからこの春。","voiceIndex":91,"id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"質問","question":"この点線がなくなることで、既存不適格が解消されるという理解でいいのかということが１点、それから、これは工事の請負なので、この残された既存の建物で、よくわからないで見ているのかもしれないけれども、何m2になるのかな。残されたところは地上３階建てと書いてあるんだけれども、実際何m2の建物になるのかなということを教えていただければ。","respondent":"宍戸施設整備課長","answer":"既存不適格についてです。道路から２ｍ後退するという意味での既存不適格につきましては、解体をすることによって解消されるんですが、日影規制については解消されないということだったと思います。それと既存の面積ですが、延べ床面積で６７５m2です。","voiceIndex":98,"id":"exchange-017"},{"speaker":"本多委員","kind":"質問・要望","question":"それぞれ６本の報告、６校なんですけれども、これを見ると工期が４カ月から６カ月ぐらいだと思うんですけれども、もちろん工事の内容ですとか規模によって違うから、大体このぐらいの工程なのかなと思うんですけれども、なるべく学校側の活動に支障を来さないように進めるのであれば、夏休みに重点的に工事が進められるのがやりやすいんだと思うんですけれども。","respondent":"宍戸施設整備課長","answer":"それとあと残りの２校ですが、実際の学校名を申し上げますと、規模が大きいために今、設計を行っておりまして、平成２２年度、平成２３年度の工事になる清水台小学校、荏原第四中学校、その２校が今年の夏休みではない工事となってしまうというものです。","voiceIndex":105,"id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"今、各学校の入札金額が出たんですが、あくまで改修工事ということなので、ちょっと教えてほしいんですが、耐震補強、それから電気設備工事費、機械設備工事費がありますね。総額として、電気は幾ら、機械は幾らで、耐震補強を含めて総額幾らになるかという総額を教えてください。","respondent":"宍戸施設整備課長","answer":"１校ごとということになるといろいろあるんですけれども、基本的には今年、１０校分といたしまして、合計の金額が１３億８,０００万円余ということですので、平均して１億３,０００万円余です。","voiceIndex":107,"id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"今回、こっちは入札が９,０００万円以上というのはわかるんですが、あくまで耐震補強工事ということで総務委員会で話として出てくるわけですから、一応これだけかかるんだよということは、やはりきちんと報告していただいて、それは別に報告しなくてもいいんだよという、分割して契約内容を分けちゃえばそういう話なのかもしれませんが。","respondent":"阿部経理課長","answer":"あくまでも１件の契約が９,０００万円以上のものつきまして、当委員会に報告しているというものです。したがいまして、電気設備工事等につきましては９,０００万円未満ですので、どこどこと契約をしたという報告を先ほど関連別途工事の中で説明したです。","voiceIndex":109,"id":"exchange-020"},{"speaker":"須貝委員","kind":"意見","question":"意見だけ。別にこれから議論という話じゃなくて、あくまでこれから小学校、中学校の耐震補強工事ということで全面的に出すならば、民間でも何でもそうですが、一応総額がこういうふうにかかりましたということは、この場で報告だけでもしていいんじゃないかなと。あくまで契約だけの範囲で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":111,"id":"exchange-021"},{"speaker":"須貝委員","kind":"質問・要望","question":"議会のほうはわかりますが、やっぱりちょっとわかりにくいのかなというふうに、あくまで工事全体として、私はこういうふうに出して、あくまで契約に関してはこの契約、９,０００万円以上に対して今回審議していただきたいという話で持っていくのが筋じゃないかなと思いますので、それは意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-022"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ちょっと確認しておきたいんですけれども、先ほどの９,０００万円以下の４校の話なんですが、これは工事はいつぐらいまでに終わるんですか。大体同じ時期になるのか。できたら具体的にどこの学校はいつぐらいというのがわかったら、教えていただきたいと思います。","respondent":"宍戸施設整備課長","answer":"残りの４校につきましても、１校ずつ工期がどうだったかというのはわからないんですけれども、大体９月末かおおむね１０月末まで工期はとらせていただいていると思います。残りの４校につきましては、具体的には鈴ケ森小学校、延山小学校、中延小学校、大崎中学校です。","voiceIndex":115,"id":"exchange-023"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"宮崎委員","kind":"意見","question":"公契約のあり方で、以前、建設関係の組合のほうからも請願があって、意見書を出したという経過があるんですけれども、実際にどういうふうになっているのかというのをこの委員会でも調査すべきなのではないかなと思っています。とりわけ今、仕事がないというのが１つあるんですけれども、仕事があっても収入というか、賃金、労賃が安いということがありますので、実際に調査すべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":121,"id":"exchange-024"},{"speaker":"土井委員","kind":"質問・要望","question":"先ほどもありましたけれども、都区協議については、節目節目のところで委員長にお計らいいただいて、ご報告をいただく。意見を述べするという機会をつくっていただきたいなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":123,"id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1822#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":43313,"voices":126}},{"id":"h21-20090602-14","meetingId":"h21-cm06","date":"2009年6月2日","dateIso":"2009-06-02","committee":"行財政改革特別委員会","time":"午後１時０４分～午後３時０４分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"品川区の歩道橋２２というのがあるんですけれども、歩道橋の考え方、いわゆるこれをつくられた時期というのは、まだ日本中が若い人たちがみなぎっていたと思うんだけれども、品川区だけではなくて、国にとっても高齢化が進んできているときに、歩道橋の意味というのが、なかなか大変だよというので何年か前にも質問をしたことがあるし。","respondent":"岩田防災まちづくり事業部長、久保田行財政改革担当課長","answer":"ただ、国道、都道のように歩道が広いところというのは、区道の横断歩道橋はほとんどありませんので、そういう面では予算があっても物理的にそういうバリアフリー化ができるかどうかというのは非常に難しい問題ですけれども。それで、例えば指定管理施設等につきましてはこの中に含まれてございませんで、指定管理者のほうから光熱水費のほうは直接払っているというところが基本となっています。","voiceIndex":38,"id":"exchange-001"},{"speaker":"川西委員","kind":"質問・要望","question":"跡地活用についての区のほうのこの現在の社会情勢をいろいろ勘案した中で、重点的に区としてどういうふうにしていきたいかというのを、できるできないは別にして、３つぐらい挙げて教えていただきたいと思います。","respondent":"久保田行財政改革担当課長","answer":"例えば、暫定的に何か活用を図っていくといったようなところも今後考えていかなければならないのかなというところでございまして、こうしたことを踏まえながら、それぞれの施設の立地や周辺の状況。","voiceIndex":41,"id":"exchange-002"},{"speaker":"川西委員","kind":"質問・要望","question":"私は今のこの社会的ないわゆる環境問題を考えるときに、跡地の中はできるだけ可能ならば緑地や緑を整備するということを、地域で野球場、サッカー場の要望があることも承知はしておりますけれども、それはそれとして取り入れていただくのはいいんですけれども、そういうふうに考えていくべきではないか。これ、文化センター、５ありますと、料理教室があるのは２つ、五反田と荏原なんですね。","respondent":"久保田行財政改革担当課長","answer":"私どもといたしましては、現在ある施設をどのように活用していくのかといったところを常に考えているところでございまして、施設の配置全体の中でも、先ほどご説明がありましたけれども、中長期改修計画等もありますので。","voiceIndex":43,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"次なんですけれども、中長期改修計画の件なんですが、区有施設の改修工事の費用負担についてちょっとわからないので教えていただきたいんですけれども、区有施設の改修工事、これからかなりあるのではないかということで、調査をするということなんですが、国と都と区の負担の分担というのは、大体どういうふうになるのかというのがちょっとわからないものですから教えていただきたいと思います。","respondent":"久保田行財政改革担当課長、金子企画財政課長、家壽田都市整備下水道課長","answer":"１点目の跡地活用についてですけれども、まずまとめる時期はいつぐらいからかですが、これまでご説明させていただきましたとおり。いずれにしましても、区の基本的な考え方としましては、こういった特定財源をできる限り有効に活用しようというところが基本的な考え方ですので。橋梁の予防的修繕について簡単にご説明いたします。所管としましては、その口座のほうに公共料金に相当する金額を繰り入れていくといったことで、事務を円滑に進めるために設置をしたです。","voiceIndex":45,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"出た後にパブリックコメントを経て、意見がある程度出されて、それで決まったわけなんですけれども、最初のパブリックコメントにかける前の意見が出るまでの庁内の中の検討の仕組みが今の説明ではちょっとわからないといいますか、委員会にお諮りしていますとか、機会を通してさまざまな声を聞いていますとか、日常的に問い合わせが来るんですよというお話しだったんですが、それがどういう。","respondent":"久保田行財政改革担当課長","answer":"跡地活用の過程ですけれども、すべてのものを一律にこういう仕組みがあって検討しているというところではないということはこれまでご説明してきたとおりです。","voiceIndex":50,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"先ほどちょっと紹介した行革委員会のまとめなんですが、ここに区有財産の活用に当たってということで先ほど紹介しましたけれども、策定過程においても立地環境や長期的な行政需要、地域住民の意見などが計画に反映されるよう検討されたいということで意見を出させていただいたんですけれども。","respondent":"久保田行財政改革担当課長","answer":"その後に、その施設の内容や必要に応じましてパブリックコメントを実施してまいりまして、平塚小学校につきましても、昨年１１月から１２月にかけましてパブリックコメントをやりまして、各施設につきまして、荏原平塚と、平塚小学校の施設につきまして。","voiceIndex":52,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"今の説明なんですが、ちょっと納得いかない点があったので、もう一度質問しますけれども、パブリックコメントにかけているので策定過程においても区民の意見を聞いているんだというお話しだったんですけれども、昨年のパブリックコメントの内容というか、そのやりとりなどを見ましても、基本的には、この前も委員会でも言ったんですが、区の案に基本的な方向。","respondent":"久保田行財政改革担当課長","answer":"私ども、利用計画案を立ててパブリックコメントを前回、平塚小学校についてはやったという経過がありますけれども、そのパブリックコメントをかける前に、私ども、１０月ぐらいから議会のほうに案もお示しいたしまして。","voiceIndex":54,"id":"exchange-007"},{"speaker":"渡部委員","kind":"質問","question":"１ページなんですが、跡地活用について、杜松小学校と荏原第四中学校が平成２５年からということで、今回の行財政改革特別委員会で話し合われるんですけれども、４年後に向けて、この辺のこういうふうにやるというようなものに対して、地域の声といいますか、八潮のときのようにまちづくり協議会ですとか、地元の方に早めにおろして、地元の方を入れてといいますか。","respondent":"久保田行財政改革担当課長","answer":"地域の声、意見を入れてですけれども、こうした手法についても、八潮のときの手法がいいのか、それぞれほかのやり方もありますので、ここのところは地域のほうのそれぞれの特性といったところもありますので、現在こういうやり方でというのはなかなかお示しできませんけれども。","voiceIndex":56,"id":"exchange-008"},{"speaker":"阿部委員","kind":"質問","question":"３点ほどお伺いしたいと思います。そういったそれぞれの地域の情報ですとか、周辺の、同時に中長期の施設改修の計画も立てるということですので、そういった情報もあわせて考えることで、時間軸でも平面軸でも効率的な運用ができるのではないかと思いますので、ぜひ資料として、もちろん今日でなくて構わないんですけれども、出していただけるように、これは委員長にお願いすればよろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-009"},{"speaker":"山内委員","kind":"質問・要望","question":"６ページの区内施設の有効活用の利用率のところなんですけれども、大体こういうものは資料で示されるときは必ずこうやって利用率が出ますよね。この利用率が高いところ、低いところというのは如実にあらわれているわけですけれども、例えば、高いところはこのまま既存のままでよろしいでしょう。そこをちょっと教えていただきたいんですけれども。","respondent":"久保田行財政改革担当課長","answer":"高いところにつきましては、例えば大崎第一地域センターであれば、五反田、目黒の間にあるといったところで交通の便がいいといったところ、また企業等も研修や会社説明会でも使っているといったこともありますので、一定程度の利用率があるのかなというふうに考えております。","voiceIndex":63,"id":"exchange-010"},{"speaker":"山内委員","kind":"質問","question":"そうすると、これは今年の平成２０年度の数字ですよね。もちろんこのデータというのは前々からずっととってきていると思うんですが、例えば、じゃあ、ちょっと内容を変えました、極端に上がりましたとか、そういうような過去に事例というのはあるんですか。地域センター、文化センターを含めて、何か画期的なことをしたら数字が上がったよとか、そういうようなことというのは過去にあったのかなと。","respondent":"久保田行財政改革担当課長","answer":"ちょっと大崎第一の例を出してあれですけれども、複合施設のほうに移転をしてきれいになったというところもありますので、そうした意味では利用率のほうも多少は上がっているのかなというふうに分析はしています。","voiceIndex":65,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"跡地活用に関することを先ほどからいろいろな委員のお話がありましたけれども、それを聞いていて一言。先ほども課長のほうからも、行政需要だったり、地域の要望だったり、財産としての有効活用、こういう視点を持っているということ。それは意見です。その辺ちょっと、どういうふうに区分けがあるのか、これに載っていないほかにどんな施設があるのか、ちょっと教えていただけますか。","respondent":"久保田行財政改革担当課長","answer":"今回こちら資料にまとめたもの、冒頭でもご説明をさせていただきましたけれども、活用の用途がまだ未定のものというところが１点。暫定的に活用しているところというところが２点目です。","voiceIndex":67,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"それと、直接区が管理していない区内の跡地といいますか、その辺というのは、どんなふうに考えているのか、全く民間会社が所有しているものから、ずばり下神明駅のＪＴの社宅、今、大分壊れて更地に近くなっているという話を聞きましたけれども、土地の規模の大きいもの、小さいものいろいろありますけれども、区が直接所管しているものはいずれ報告を受けることは可能ですけれども。","respondent":"久保田行財政改革担当課長","answer":"それ以外の広い意味での跡地ということであれば、民間の企業や事業者の跡地というところもありますけれども、こちらにつきましては、そちらのほうの事業者が主体的にいろいろと検討し、考えていくところですので、まだ跡地になっていない段階もそうですし。","voiceIndex":69,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"経過を見て、地域の人にとっては建設説明会がすべてだったみたいなことが率直なところなんですけれども、跡地活用について今まで経緯や進め方に違い、変化が生まれてきていると思うんですけれども、区の考え方として、基本方針をどういうふうに変えてきたのか、変わってきたのか、それとも何も変わらないのかわからないですけれども、ちょっとその考え方をあわせて教えていただけますか。","respondent":"日下部企画部長、岩田防災まちづくり事業部長","answer":"ただ、これの前段で、実は学校の５校の統合の問題、一貫校の整備の問題が出てまいりまして、その時点で区側としましては、八潮プロジェクトという庁内プロジェクトをつくりまして、そこで関係各課のいろいろな。下神明の日本たばこの社宅の件ですが、政府系企業には間違いないんですが、一応株式会社ですので、あの土地がどのように今、日本たばこが考えておられるかということについては、一定別の方策がありましたので打診をしたご回答では。","voiceIndex":71,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区の従来の進め方のお話がありましたけれども、この委員会としては、土地の大きい小さいにかかわりなく、行政需要だったり、地域の要望だったり、そこの利用していた当事者だったり、そういう視点に立って検討するに当たって、やっぱり基礎的なデータがなければなかなかわからないと思うので、そういうところはしっかり出していただきたいなというふうに思いますし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"ここに施設名がありますけれども、小学校、中学校、幼稚園、あと地域センター、この間で見ると学童もそうですけれども、そこを利用していた人たちの思いというものがあるわけですよね。そういうのをどう受けとめながら跡地利用を考えていくのかということを聞いているんですけれども、いかがでしょうか。","respondent":"日下部企画部長","answer":"跡地活用に当たっての地域のいろいろな思いといいますか、そういうものをどう受けとめるのかということでありますけれども、これはもう以前からそういう形で取り組んでおりますけれども、これは地域のいろいろご意見があれば、それはそれとして区としても受けとめていく。","voiceIndex":76,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"最後にしようかなと思うんですけれども、もう１つ、跡地活用を考える区の考え方のスタンスを伺いたいなと思ったのは、再開発のことといいますか、学校統廃合のことといいますか、今、教育委員会だったり、区長部局だったり、統廃合計画、いわゆる４０人学級で小学校、中学校を統合するという、今後の人口動態を話しておりましたけれども、今後の人口がどう推移していくのか。","respondent":"岩田防災まちづくり事業部長","answer":"ただ、法定再開発のようなかなり規模がでかくて、保育需要とか学校施設への負荷がかなりかかる可能性があるものについては、事前に施設規模、それからその規模による発生率というものがありますので。","voiceIndex":78,"id":"exchange-017"},{"speaker":"中塚委員","kind":"意見","question":"ご心配にはおよびませんという話だったけれども、行政需要で言えば、今の保育園不足は、私は大崎中心の再開発の影響があると思っていますし、義務化していないというところがあると思いますので、ちょっと今の部長の意見は違うなと思います。意見で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":80,"id":"exchange-018"},{"speaker":"市川委員","kind":"質問・要望","question":"跡地活用についてなんですけれども、区の考え方を示しつつ、地域の要望を聞いていくということなんですけれども、そうしますと、要望を聞くということと、地域での偏りができるということも一方で考えられるかなと思うんですけれども、その辺の品川区全体を見たときの施設の地域のバランスみたいなものを区としてはどういうふうに考えていらっしゃるのか。","respondent":"久保田行財政改革担当課長","answer":"地域的に施設のバランス等というのも大変重要な課題でございまして、そうしたことも踏まえながら検討はしてきているところですけれども、その跡地が地域的なバランスにぴたっとはまって跡地が発生するといったこともなかなかない状況もありますので、そうした中では。","voiceIndex":81,"id":"exchange-019"},{"speaker":"市川委員","kind":"質問・要望","question":"バランスよく配置していただきたいなという希望があるんですけれども、そうしたときに、区民の要望に対して区として暫定的に区民の方に建物を建て替える前に、暫定的に使用していただきながら、ほかの跡地が出たときにそれとの兼ね合いも見て建て替えをするとかというような、そういう考え方はないのかということをお聞きします。","respondent":"久保田行財政改革担当課長","answer":"私どもも跡地の活用について検討していく中では、例えば区の行政需要等も踏まえながら、暫定的な活用といったものも必要だというふうに考えております。そうしたものも踏まえながら、その先の有効活用というところも検討はしていかなければならないです。","voiceIndex":83,"id":"exchange-020"},{"speaker":"市川委員","kind":"質問・要望","question":"としますと、仕組みづくりをどうやっていくのかということはとても大事なことだと思いますので、先ほどからいろいろなご意見も出ていますけれども、ぜひこの場でどういう仕組みをとって跡地活用について考えていくのかというのは、この委員会でぜひ議論をしていただきたいというふうに思います。","respondent":"久保田行財政改革担当課長","answer":"目的外利用ですので、利用した回数といったもの等については、多分把握はしていると思うんですけれども、それに対して利用率ということですから、利用可能な分母の部分とか、そういったもので集計はしていないというご説明をさせていただきましたので、もし今後必要であれば。","voiceIndex":85,"id":"exchange-021"},{"speaker":"山元委員","kind":"質問・要望","question":"４ページの橋梁長寿命化修繕計画ということで、この橋は全部で７７ということなんですが、１つは、これ、品川区内に全部ある橋の、全部で７７個なのかというのを１つ教えていただきたいということと、この修繕計画でまず４８が対象になっているということなんですが、この順番というんですか、一番ひどいところからやっていくのか、またそれとも地域的にやっていくのかとか、何かそういう計画的なもの。","respondent":"家壽田都市整備下水道課長","answer":"それと、今後の整備の優先度等なんですが、もちろん壊れそうな緊急のものであればすぐやらなければいけないと思いますし、また、お金で効果があるところは、いつやれば一番効果的なのかというのは、これからまさに検討していく段階ですので、その辺が計画がまとまった段階では。","voiceIndex":87,"id":"exchange-022"},{"speaker":"山元委員","kind":"質問・要望","question":"本当に個人的で申しわけないんですが、立会川の橋はもう本当に……。でも、すごく愛着のある橋があるんですね。それは直していただきたい気持ちと同時に、あくまでも修繕で、壊すのでなく修繕ですよね。","respondent":"家壽田都市整備下水道課長","answer":"それも含めてかなり広範囲に、景観であるとか愛着、それから財政面、安全面、幅広く考えて議論していくのが今回の長寿命化計画だと考えています。","voiceIndex":89,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"区内の施設の有効活用について、１点だけ伺いたいことがあったんですけれども、先ほどから利用率のことが少し話題になっておりましたけれども、有効活用、例えば単純に効率を考えると、利用率というのは限りなく１００％に近づけようとなる。そういうところををどんなふうにお考えになっているのか、そこの考え方を教えていただけますか。","respondent":"久保田行財政改革担当課長","answer":"こうした相反するところもありますので、そうした中で私どもとしましては、７割から８割程度ということであれば、一定の区民の方が利用もされていますし、あいているところ、例えば急に使いたくなったというようなときにも。","voiceIndex":91,"id":"exchange-024"}]},{"id":"topic-02","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"公有財産の有効活用ということなのですけれども、やっぱり先ほどの議論の中でもありましたし、区も言っているんですけれども、地域として求められている必要なものという観点ということと同時に、区全体の行政需要がどうなのかとか、区の中でのバランスがどうなのかという観点も２つ目として必要だということも出されました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"なので、集会所だったり、スポーツ施設だったり、保育園だったり、児童センターだったり、シルバーセンター、高齢者施設、いろいろな行政の施設がありますけれども、その利用状況だったり、申し込み状況、そういったところからも何が足りないのか、どんな施設が今、求められているのか、人口から比べれば今後どういうものが必要になってくるのか、そういう読み取り方もきっとできるんじゃないのかなと思うし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-026"},{"speaker":"川西委員","kind":"質問・要望","question":"原小の跡にも似たようなものができたというふうな地域バランスも示していただくことによって、どういうものが、私、さっき自然環境なんて言いましたけれども、それだけにこだわらずに必要かということも出てくるのではないかと思いますので、この施設ごとの地域バランス、ここのところ何年か、１０年でもいいですよ、２０年でもいいんですけれども、つくってきたもの、跡地を利用してつくられてきたもの。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-027"},{"speaker":"若林委員","kind":"質問・要望","question":"単年度、１年間のこういう１、２という活用に関することですけれども、単年度といえども、やっぱりスタートのこの長期基本計画とのかかわり、私たちもしっかり議論をしたいし、また区のお考えも聞きたいという意味で、そういう折々に触れた適切な資料提供なんかもいただきたいなというふうに、今具体的にはありませんけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5862#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":40590,"voices":104}}]);
